// Banco de preguntas PCA — Piloto Comercial Avión (457 preguntas, 9 materias).
// s = materia (índice en MATERIAS), q = pregunta, o = opciones, a = índice de la correcta, e = explicación.

export const MATERIAS = ["Aerodinámica básica", "Sistemas de aeronaves", "Instrumentos de vuelo", "Reglamentación", "Procedimientos y operaciones de aeródromos", "Meteorología", "Servicios meteorológicos", "Performance de la aeronave", "Navegación"];

export type PreguntaPCA = { id: number; s: number; q: string; o: string[]; a: number; e: string };

export const PREGUNTAS_PCA: PreguntaPCA[] = [
  {"id": 1, "s": 0, "q": "¿Si un avión es calificado de categoría utilitaria, significaría que este avión podría ser operado en cuál de las siguientes maniobras?", "o": ["Acrobacias limitadas, excluyendo barrenas.", "Acrobacias limitadas, incluyendo barrenas (Si se aprueba)", "Cualquier maniobra excepto acrobáticas y barrenas."], "a": 1, "e": "Los aviones de categoría utilitaria pueden hacer todas las maniobras de la categoría normal más las acrobacias limitadas, incluyendo barrenas (Si están aprobadas). La respuesta (A) es incorrecta porque la categoría utilitaria incluye barrenas. La respuesta (C) es incorrecta porque la categoría normal prohíbe acrobacias y barrenas."},
  {"id": 2, "s": 0, "q": "La relación entre la carga aerodinámica total impuesta sobre el ala y el peso bruto de un avión en vuelo se conoce como:", "o": ["Factor de carga y afecta directamente la velocidad de pérdida.", "Factor de aspecto y afecta directamente la velocidad de pérdida.", "Factor de carga y este no tiene relación con la velocidad de pérdida."], "a": 0, "e": "El factor de carga es la relación entre la carga aerodinámica impuesta a las alas de un avión y el peso bruto del avión. Un factor de carga incrementa la velocidad de pérdida y disminuye la velocidad de pérdida."},
  {"id": 3, "s": 0, "q": "El factor de carga es la sustentación generada por las alas de un avión en un momento dado:", "o": ["Dividido por el peso total del avión.", "Multiplicado por el peso total del avión.", "Dividido por el peso en vació del avión."], "a": 0, "e": "El factor de carga es la relación entre la carga total soportada por el ala y el peso total del avión; es decir, la carga aérea total soportada por las alas dividida por el peso total del avión. La respuesta (B) es incorrecta porque el factor de carga multiplicado por el peso del avión es igual a la sustentación requerida. La respuesta (C) es incorrecta porque el factor de carga es la sustentación dividida por el peso total del avión."},
  {"id": 4, "s": 0, "q": "Mientras se ejecuta un giro nivelado a 60 grados, el avión tiene un factor de carga de2,0. ¿Qué significa esto?", "o": ["La carga total sobre la estructura del avión es dos veces su peso.", "El factor de carga está por encima de la carga limite.", "El factor de ráfagas es dos veces la carga limite total."], "a": 0, "e": "El factor de carga es la relación entre la carga aérea total soportada por el ala y el peso total del avión; es decir, la carga total soportada por las alas dividida por el peso total del avión."},
  {"id": 5, "s": 0, "q": "Para cualquier ángulo de inclinación, en cualquier avión, el factor de carga impuesto enun giro coordinado con altitud constante:", "o": ["Es constante y la velocidad de pérdida incrementará.", "Varía con la tasa de giro.", "Es constante y la velocidad de pérdida disminuirá."], "a": 0, "e": "En un avión a cualquier velocidad, si se mantiene una altitud constante durante el giro, el factor de carga para cualquier grado de inclinación es la misma, que es la resultante de la gravedad y la fuerza centrífuga. La carga soportada por las alas incrementa con el ángulo de giro. Las velocidades de pérdida incrementan en proporción a la raíz cuadrada del factor de carga. La respuesta (B) es incorrecta porque la velocidad de giro no afecta al factor de carga. La respuesta (C) es incorrecta porque la velocidad de pérdida aumentará con el aumento de la inclinación."},
  {"id": 6, "s": 0, "q": "La carga del ala del avión durante un giro coordinado nivelado con vientos suaves depende de:", "o": ["La tasa de giro.", "El ángulo de banqueo.", "La velocidad real del aire."], "a": 1, "e": "Para cualquier ángulo de banqueo, la tasa inclinación varia con la velocidad del aire. Si el ángulo de banqueo se mantiene constante y la velocidad del aire es incrementada, la tasa de giro disminuirá. Debido a esto; no hay un cambio en la fuerza centrífuga para ningún ángulo de banqueo dado. Por lo tanto, el factor de carga seguirá siendo el mismo. El factor de carga varia cambiando el ángulo de banqueo y se incrementa rápidamente cuando el ángulo de inclinación alcanza los 50°. La respuesta (A) es incorrecta porque la tasa de giro y la velocidad aerodinámica real no influyen en la carga alar en un giro coordinado. La respuesta (C) es incorrecta porque la tasa de giro y la velocidad aerodinámica real no influyen en la carga alar en un giro coordinado."},
  {"id": 7, "s": 0, "q": "En una recuperación rápida de una maniobra de picada, los efectos del factor de carga harían que la velocidad de pérdida:", "o": ["Incremente.", "Disminuye.", "No varia."], "a": 0, "e": "Hay una relación directa entre el factor de carga sobre el ala y sus características de pérdida. La velocidad de pérdida incrementa en proporción a la raíz cuadrada del factor de carga."},
  {"id": 8, "s": 0, "q": "Mientras se mantiene un ángulo de banqueo y altitud constante en un giro coordinado,un aumento de la velocidad del aire:", "o": ["Incrementa la tasa de giro resultante y disminuye el factor de carga.", "Disminuye la tasa de giro resultante y no cambia el factor de carga.", "Incrementa la tasa de giro resultante y no cambia el factor de carga."], "a": 1, "e": "Para cualquier ángulo de banqueo, la velocidad de giro varia con la velocidad del aire. En otras palabras, si el ángulo de banqueo se mantiene constante y la velocidad del aire es incrementada, la tasa de giro disminuirá, o si la velocidad del aire disminuye, la tasa de giro incrementará. Debido a esto, no hay un cambio en la fuerza centrífuga para cualquier inclinación dada. Por lo tanto, el factor de carga permanece igual. La respuesta (A) es incorrecta porque el factor de carga permanece igual para un ángulo de banqueo constante. La respuesta (C) es incorrecta porque la tasa de giro en un ángulo de banqueo constante disminuirá con el incremento en la velocidad del aire, y el factor de carga permanecerá igual."},
  {"id": 9, "s": 0, "q": "La sustentación en un ala se define más adecuadamente como:", "o": ["Fuerza que actúa perpendicularmente al viento relativo.", "Diferencia de presiones actuando perpendicular sobre la cuerda del ala.", "Presión reducida resultante de un flujo laminar sobre la curvatura superior de un perfil aerodinámico, que actúa perpendicularmente a la curvatura media."], "a": 0, "e": "La sustentación se opone a la fuerza descendente del peso. Se produce por el efecto dinámico del aire que actúa sobre el ala y actúa perpendicularmente a la trayectoria de vuelo (viento relativo) a través del centro de sustentación del ala."},
  {"id": 10, "s": 0, "q": "Mientras se mantiene el ángulo de banqueo constante en un giro nivelado, si la tasa de giro es variada, el factor de carga:", "o": ["Permanecerá constante con respecto a la densidad del aire y el vector de sustentación resultante.", "Variara en función de la velocidad y la densidad del aire proveniente de la resultante de la variación proporcional del vector de sustentación.", "Variara en función de la resultante del vector de sustentación."], "a": 0, "e": "Para cualquier ángulo de inclinación la tasa de inclinación variara con respecto a la velocidad del aire. En otras palabras, si el ángulo de banqueo se mantiene constante y la velocidad del aire aumenta, la tasa de giro decrecerá, o si la velocidad del aire disminuye, la tasa de giro incrementará. Debido a esto, no hay un cambio en la fuerza centrifuga para una inclinación dada. Por lo tanto, el factor de carga seguirá siendo el mismo. La respuesta (B) es incorrecta porque la velocidad de giro varía en función de la velocidad del aire con un ángulo de inclinación constante. La respuesta (C) es incorrecta porque el factor de carga varía en función del vector de carga resultante."},
  {"id": 11, "s": 0, "q": "La necesidad de reducir la velocidad de una aeronave por debajo de V(A) se produce porel siguiente fenómeno meteorológico:", "o": ["Alta densidad por altitud, que incrementa la velocidad indicada de pérdida.", "Turbulencia, que causa incrementos en la velocidad de pérdida.", "Turbulencia, que causa una disminución en la velocidad de pérdida."], "a": 1, "e": "Cuando se encuentra una turbulencia severa, el avión debe volarse a una velocidad de maniobra o inferior. Esta es la velocidad con menos probabilidades de provocar daños estructurales en el avión, incluso si se utiliza todo el recorrido de control, sin embargo, permite un margen de seguridad suficiente por encima de la velocidad de pérdida en aire turbulento. Cuando un avión está volando a una velocidad alta con un ángulo de ataque bajo y de repente se encuentra con una corriente vertical de aire que semueve hacia arriba, el viento relativo cambia a una dirección ascendente al encontrarse con el perfil aerodinámico. Esto aumenta el ángulo de ataque en las alas y tiene el mismo efecto que aplicar una fuerte presión de retroceso en el control del elevador. Aumenta el factor de carga lo que a su vez aumenta la velocidad de pérdida. La respuesta (A) es incorrecta porque la velocidad de pérdida indicada no se ve afectada por los cambios en la altitud por densidad. La respuesta (C) es incorrecta porque los factores de carga más elevados impuestos a la aeronave por la turbulencia aumentan la velocidad de pérdida."},
  {"id": 12, "s": 0, "q": "En teoría, si la velocidad del aire de un avión se duplica mientras está en vuelo nivelado, la resistencia parásita será:", "o": ["Dos veces mayor", "La mitad de grande.", "Cuatro veces más grande."], "a": 2, "e": "La resistencia parásita tiene más influencia a altas velocidades, y la resistencia inducida tiene más influencia a bajas velocidades. Por ejemplo, si un avión en condiciones de vuelo estable a 100 nudos es acelerado a 200 nudos, la resistencia parásita será 4 veces más grande."},
  {"id": 13, "s": 0, "q": "En teoría, si la velocidad del aire de una aeronave en vuelo nivelado es cortada a la mitad, el valor de la resistencia parásita será:", "o": ["Un tercio del valor.", "La mitad del valor.", "Un cuarto del valor."], "a": 2, "e": "La resistencia parásita incrementa como el cuadrado de la velocidad del aire."},
  {"id": 14, "s": 0, "q": "A medida que la velocidad del aire disminuye en vuelo nivelado, por debajo de la velocidad en la cual ocurre la máxima relación L/D, la resistencia total de un avión:", "o": ["Disminuye debido a la baja resistencia parásita.", "Incrementa debido al incremento de la resistencia inducida.", "Incrementa debido al incremento de la resistencia parásita."], "a": 1, "e": "La resistencia parásita es mayor a altas velocidades del aire. La resistencia inducida es el producto de la sustentación y tiene mayor influencia con ángulos de ataque altos y velocidades del aire lentas. Este incrementa de forma directamente proporcional al aumento del ángulo de ataque. Cualquier ángulo de ataque inferior o superior al de la relación L/D (Max) reduce la relación sustentación/resistencia y en consecuencia, aumenta la resistencia total. La respuesta (A) es incorrecta porque la resistencia total aumenta cuando la velocidad del aire disminuye por debajo de L/D(MAX) debido al aumento de la resistencia inducida. La respuesta (C) es incorrecta porque la resistencia parásita disminuye con velocidades inferiores a L/D(MAX)."},
  {"id": 15, "s": 0, "q": "Si la velocidad del aire es incrementada de 90 nudos a 135 nudos durante un giro nivelado, en un banqueo a 60°, el factor de carga:", "o": ["Incrementará, así como la velocidad de pérdida.", "Disminuirá y la velocidad de pérdida se incrementará.", "Permanecerá igual pero el radio de giro se incrementará."], "a": 2, "e": "A un ángulo de banqueo determinado, una mayor velocidad del aire hará que el radio de giro sea mayor y el avión girara a una velocidad más lenta. Esto compensa la fuerza centrífuga añadida, permitiendo que el factor de carga permanezca constante."},
  {"id": 16, "s": 0, "q": "Un factor de carga de 1,2 significa que la carga total sobre la estructura de un avión es1,2 veces su:", "o": ["Peso bruto.", "Carga limite.", "Factor de ráfaga."], "a": 0, "e": "En aerodinámica, el factor de carga es la relación de la máxima carga que puede soportar el avión y el peso bruto del avión. Por ejemplo, un factor de carga de 1,2 significa que la carga total sobre la estructura del avión es 1,2 veces su peso bruto."},
  {"id": 17, "s": 0, "q": "¿Qué afirmación es verdadera en relación con el cambio del ángulo de ataque?", "o": ["Una disminución en el ángulo de ataque incrementará la presión debajo del ala, y disminuirá la resistencia.", "Un aumento en el ángulo de ataque incrementará la resistencia.", "Un aumento en el ángulo de ataque disminuirá la presión debajo del ala, e incrementará la resistencia."], "a": 1, "e": "El aire que golpea la parte inferior del ala es desviado hacia abajo, produciendo una reacción opuesta que empuja (Eleva) el ala hacia arriba. Para aumentar la sustentación, el ala se debe inclinar hacia arriba, incrementando el ángulo de ataque y desviando el aire hacia abajo. Cuanto más grande sea el ángulo de ataque, más se inclinará la fuerza de sustentación hacia la parte trasera de la aeronave, aumentando la resistencia."},
  {"id": 18, "s": 0, "q": "¿Cuál es la verdad sobre el uso de flaps durante los giros nivelados?", "o": ["El descenso de los flaps incrementa la velocidad de pérdida.", "El elevamiento de los flaps incrementa la velocidad de pérdida.", "Para elevar los flaps será necesario añadir presión hacia delante sobre la palanca de mando."], "a": 1, "e": "Si se elevan los flaps la velocidad de pérdida aumenta. La respuesta (A) es incorrecta porque los flaps disminuyen la velocidad de pérdida. La respuesta (C) es incorrecta porque al elevar los flaps disminuye la sustentación proporcionada, por lo que se requiere contrapresión para mantener la altitud."},
  {"id": 19, "s": 0, "q": "Una de las principales funciones de los flaps durante la aproximación y el aterrizaje es:", "o": ["Disminuir el ángulo de descenso sin incrementar la velocidad del aire.", "Proveer la misma cantidad de sustentación a una baja velocidad.", "Disminuir la sustentación, permitiendo así una aproximación más pronunciada de lo normal."], "a": 1, "e": "Extender los flaps incrementa la sustentación del ala y también incrementa la resistencia inducida. El incremento de la resistencia permite al piloto hacer aproximaciones más pronunciadas sin aumentar la velocidad del aire. La respuesta (A) es incorrecta porque los flaps incrementan el ángulo de descenso sin incrementar la velocidad del aire. La respuesta (C) es incorrecta porque los flaps aumentan la sustentación y la resistencia inducida."},
  {"id": 20, "s": 0, "q": "Para incrementar la velocidad de giro y al mismo tiempo disminuir el radio, el pilotodebería:", "o": ["Mantener el banqueo y disminuir la velocidad.", "Incrementar el banqueo y aumentar la velocidad.", "Incrementar el banqueo y disminuir la velocidad."], "a": 2, "e": "La componente horizontal de la sustentación será igual a la fuerza centrífuga de un viraje en vuelo estable. Para incrementar la tasa de giro, el ángulo de banqueo debe ser incrementado y la velocidad del aire debe ser disminuida. La respuesta (A) es incorrecta porque, aunque a un ángulo de banqueo dado, una disminución en la velocidad del aire incrementará la tasa de giro y disminuirá el radio, esto será tan efectivo como aumentar la inclinación y disminuir la velocidad. La respuesta (B) es incorrecta porque el piloto debe disminuir la velocidad para incrementar el radio de giro."},
  {"id": 21, "s": 0, "q": "¿Cuál es la opción correcta con respecto a la tasa y radio de giro para un avión que vuelaen giro coordinado a una altitud constante?", "o": ["Para un especifico ángulo de banqueo y velocidad de aire, la tasa y radio de giro no variaran.", "Para mantener una tasa de giro estable, el ángulo de giro debe ser incrementado.", "Cuanto más rápida es la velocidad del aire, más rápido será la tasa y más largo el radio de giro independientemente del ángulo de giro."], "a": 0, "e": "Para un ángulo de banqueo especifico y una velocidad dada, el radio y la tasa de giro permanecerán constantes si la altitud se mantiene constante. La tasa de giro varia con la velocidad del aire o el ángulo de banqueo. Si el ángulo de giro se mantiene constante y la velocidad del aire incrementa, la tasa de giro disminuirá, y el radio de giro incrementará. Para mantener constante la tasa de giro cuando la velocidad del aire es incrementada, el ángulo de giro deberá ser incrementado."},
  {"id": 22, "s": 0, "q": "¿Por qué es necesario aumentar la presión ejercida hacia atrás en el elevador para mantener la altitud durante un giro? Para compensar la:", "o": ["Pérdida de la componente vertical de sustentación.", "Pérdida de la componente horizontal e incrementar la fuerza centrífuga.", "Deflexión del timón y la ligera oposición del alerón durante el giro."], "a": 0, "e": "La sustentación durante un giro es dividida en dos componentes, una vertical y otra horizontal. La componente vertical de sustentación debe ser igual a el peso para mantener la altitud. Dado que la componente vertical de sustentación decrece a medida que aumenta el ángulo de banqueo, el ángulo de ataque debe ser incrementado progresivamente para producir la suficiente sustentación vertical para soportar el peso del avión. El incremento de presión en el elevador proporciona el aumento en el ángulo de ataque. La respuesta (B) es incorrecta porque describe un giro de derrape. La respuesta (C) es incorrecta porque puede ser necesaria una ligera presión opuesta de los alerones para compensar la tendencia al sobre banqueo, no para mantener la altitud."},
  {"id": 23, "s": 0, "q": "Para mantener la altitud durante un giro, el ángulo de ataque debe ser incrementado para compensar la disminución de:", "o": ["Las fuerzas opuestas a la resultante de la componente de resistencia.", "La componente vertical de sustentación.", "La componente horizontal de sustentación."], "a": 1, "e": "La sustentación durante un giro es dividida en dos componentes, una vertical y otra horizontal. La componente vertical de sustentación debe ser igual al peso para mantener la altitud. Dado que la componente vertical de la sustentación disminuye a medida que el ángulo de banqueo incrementa, el ángulo de ataque debe ser incrementado progresivamente para producir la suficiente sustentación vertical. El aumento de la presión en el elevador trasero proporciona un aumento del ángulo de ataque. La respuesta (A) es incorrecta porque la frase “La resultante de la componente de resistencia” no tiene sentido. La respuesta (C) es incorrecta porque a medida que la componente horizontal disminuye, la componente vertical de sustentación incrementa, por lo tanto, el ángulo de ataque debe disminuir."},
  {"id": 24, "s": 0, "q": "La velocidad de pérdida es afectada por:", "o": ["El peso, factor de carga y la potencia.", "El factor de carga, ángulo de ataque y la potencia.", "El ángulo de ataque, peso y la densidad del aire."], "a": 0, "e": "La velocidad de pérdida es afectada por: 1. El peso. Al aumentar el peso, la velocidad de pérdida también aumenta. 2. El ángulo de inclinación (Factor de carga). A medida que el ángulo de inclinación incrementa, también lo hace la velocidad de pérdida. 3. La potencia. Un aumento en la potencia reducirá la velocidad de pérdida. Un cambio en la altitud por la densidad (densidad del aire) el ángulo de ataque no tiene ningún efecto sobre la velocidad de pérdida indicada ya que, para un avión determinado, el ángulo de ataque critico o de pérdida permanece constante."},
  {"id": 25, "s": 0, "q": "Un ala rectangular, en comparación con otras formas de ala, tiene la tendencia de entrar primero en pérdida primero en:", "o": ["La punta del ala, con la pérdida progresiva hacia la raíz del ala.", "La raíz del ala, con la pérdida progresiva hacia la punta del ala.", "El borde de fuga central, con la pérdida progresiva para afuera, hacia la raíz y punta del ala."], "a": 1, "e": "El ala rectangular tiende a entrar primero en pérdida en la raíz del ala y el patrón de entrada en pérdida progresa hacia la punta. Este tipo de patrón de entrada en pérdida disminuye las tendencias de balanceo no deseadas y aumenta el control lateral a la entrada en pérdida."},
  {"id": 26, "s": 0, "q": "Al cambiar el ángulo de ataque de las alas, el piloto puede controlar la:", "o": ["Sustentación, velocidad del aire y resistencia.", "Sustentación, velocidad del aire y centro de gravedad.", "Sustentación y velocidad, pero no la resistencia."], "a": 0, "e": "Al cambiar el ángulo de ataque, el piloto puede controlar la sustentación, la velocidad del aire y la resistencia. La respuesta (B) es incorrecta porque el ángulo de ataque no afecta al centro de gravedad. La respuesta (C) es incorrecta porque el ángulo de ataque también determina la resistencia."},
  {"id": 27, "s": 0, "q": "El perfil aerodinámico de un avión está diseñado para producir la sustentaciónresultante de una diferencia en:", "o": ["La presión negativa del aire por debajo y el vacío por encima del perfil aerodinámico.", "El vacío por debajo de la superficie y una presión del aire mayor sobre la superficie del perfil aerodinámico.", "Una alta presión del aire por debajo de la superficie y una menor presión del aire encima de la superficie del perfil aerodinámico."], "a": 2, "e": "La mayor velocidad se encuentra en la parte superior del ala y la menor velocidad en la parte inferior. Porque hay una diferencia de la velocidad por encima y por debajo del ala, el resultado es una alta presión en la parte inferior del ala y una baja presión en la parte superior. Esta zona de baja presión produce una fuerza ascendente conocida como efecto Magnus, el fenómeno físico por el que la rotación de un objeto afecta a su trayectoria a través de un fluido, incluido el aire."},
  {"id": 28, "s": 0, "q": "El ángulo de ataque de un ala controla directamente:", "o": ["El ángulo de incidencia del ala.", "La cantidad de flujo de aire encima y por debajo del ala.", "La distribución de presión actuando sobre el ala."], "a": 2, "e": "El ángulo de ataque de un perfil aerodinámico controla directamente la distribución de presión encima y por debajo del perfil. Cambiando el ángulo de ataque el piloto puede controlar la sustentación, velocidad del aire y la resistencia. La respuesta (A) es incorrecta porque el ángulo de incidencia del ala es un ángulo fijo entre la línea de la cuerda del avión y el eje longitudinal del mismo. La respuesta (B) es incorrecta porque la cantidad de flujo de aire encima y por debajo del ala permanece constante."},
  {"id": 29, "s": 0, "q": "En teoría, si el ángulo de ataque y otros factores permanecen constantes y la velocidad del aire se duplica, la sustentación producida a mayor velocidad será:", "o": ["La misma que a la velocidad más baja.", "Dos veces más grande que la velocidad más baja.", "Cuatro veces más grande que la velocidad más baja."], "a": 2, "e": "La sustentación es proporcional al cuadrado de la velocidad del avión. Por ejemplo, un avión que viaja a 200 nudos tiene cuatro veces más sustentación que el mismo avión que viaja a 100 nudos, si el ángulo de ataque y otros factores permanecen constantes. La respuesta (A) es incorrecta porque la velocidad del aire es el doble, entonces la sustentación será cuatro veces mayor. La respuesta (B) es incorrecta porque al duplicarse la velocidad del aire, la sustentación será cuatro veces mayor."},
  {"id": 30, "s": 0, "q": "El ala de un avión está diseñada para producir la sustentación resultante de una diferencia en la:", "o": ["Presión de aire negativa por debajo y un vacío por encima de la superficie del ala.", "Vacío por debajo de la superficie del ala y una mayor presión del aire por encima de la superficie del ala.", "Mayor presión del aire por debajo de la superficie del ala y menor presión de aire por encima de la superficie del ala."], "a": 2, "e": "El ala es diseñada para proveer acciones mayores que su peso, desarrollando una acción de sustentación relativamente positiva (Alta) de presión por debajo del ala y una acción de sustentación negativa (Baja) de la presión actuando encima del ala. El aumento de la velocidad del aire sobre la parte superior del ala produce la caída de presión. La diferencia de presión entre la superficie superior y la inferior no explica toda la sustentación producida. El aire también incide en la superficie inferior del ala, y la reacción de este flujo descendente hacia atrás da lugar a una fuerza ascendente hacia delante del ala."},
  {"id": 31, "s": 0, "q": "En un ala, la fuerza de sustentación actúa perpendicularmente y la fuerza de resistencia actúa paralela a la:", "o": ["Línea de cuerda", "Trayectoria de vuelo.", "Eje longitudinal."], "a": 1, "e": "En la misma dirección que el viento relativo, que es paralelo a la trayectoria de vuelo. La respuesta (A) es incorrecta porque no hay una relación fija entre la sustentación y la resistencia con respecto a la línea de cuerda. La respuesta (C) es incorrecta porque no hay una relación fija entre la sustentación y la resistencia con respecto al eje longitudinal del avión."},
  {"id": 32, "s": 0, "q": "¿Qué afirmación es correcta, en relación con las fuerzas opuestas que actúan sobre un avión en vuelo nivelado en estado estable?", "o": ["Las fuerzas son iguales.", "El empuje es mayor que la resistencia y el peso y la sustentación son iguales.", "El empuje es mayor que la resistencia y la sustentación es mayor que el peso."], "a": 0, "e": "Durante un vuelo recto y nivelado a velocidad constante, el empuje y la resistencia son iguales y la sustentación y el peso son iguales."},
  {"id": 33, "s": 0, "q": "El ángulo de ataque en el cual un ala entrará en pérdida, permanecerá constante independientemente de:", "o": ["El peso, la presión dinámica, ángulo de banqueo o la altitud de paso.", "La presión dinámica, pero variará con el peso, ángulo de banqueo y la altitud de paso.", "El peso y la altitud de paso, pero variará con la presión dinámica y el ángulo de banqueo."], "a": 0, "e": "Cuando el ángulo de ataque se vuelve tan grande que el aire no puede fluir sobre la superficie superior del ala, es imposible que el aire siga el contorno del ala. Este es el ángulo de ataque crítico o de pérdida. Para cualquier avión, el ángulo de ataque crítico o de pérdida permanecerá constante independientemente del peso, presión dinámica, ángulo de banqueo, o altitud de paso. Estos factores afectan la velocidad en la que ocurre la pérdida, pero no al ángulo. La respuesta (B) es incorrecta porque la velocidad de pérdida varía con el peso y el ángulo de inclinación. La respuesta (C) es incorrecta porque la velocidad de pérdida varía con el peso y el ángulo de inclinación. ⚠️ NOTA DEL INSTRUCTOR: en el banco oficial de la Aerocivil esta pregunta aparece con la respuesta C, pero esa clave está errada. La respuesta técnicamente correcta es la A, como lo confirma la misma explicación del banco. Tenlo presente: en el examen oficial podrían calificar la C como correcta."},
  {"id": 34, "s": 0, "q": "En aviones pequeños, la recuperación normal de los giros puede generar dificultades si:", "o": ["El CG está demasiado atrás y la rotación es alrededor del eje longitudinal.", "El CG está demasiado atrás y la rotación es alrededor del CG.", "Se entrará en barrena antes de que se desarrolle completamente la pérdida."], "a": 1, "e": "La recuperación de una pérdida en cualquier avión se vuelve progresivamente más difícil si el centro de gravedad es movido hacia atrás. Esto es particularmente importante en la recuperación en la maniobra de barrena, ya que hay un punto en la carga hacia atrás de cualquier avión en el que se desarrolla un giro “plano”. La respuesta (A) es incorrecta porque la rotación es alrededor del centro de gravedad en una barrena. La respuesta (C) es incorrecta porque un avión debe primero entrar en pérdida para poder realizar una barrena."},
  {"id": 35, "s": 0, "q": "La recuperación de una pérdida en cualquier avión se hace más difícil cuando:", "o": ["El centro de gravedad ha sido movido hacia atrás.", "El centro de gravedad ha sido movido hacia delante.", "El compensador del elevador es ajustado nariz abajo."], "a": 0, "e": "La recuperación de la pérdida en cualquier avión será progresivamente más dificultosa cuando el centro de gravedad es movido hacia atrás."},
  {"id": 36, "s": 0, "q": "Si un avión está cargado en la parte posterior de su rango de CG, tenderá a ser inestable sobre su:", "o": ["Eje vertical.", "Eje lateral.", "Eje longitudinal."], "a": 1, "e": "La estabilidad lateral es controlada por el CG a lo largo del eje longitudinal. Un avión será menos estable lateralmente a medida que el CG se desplace hacia atrás a lo largo del eje longitudinal. La estabilidad longitudinal (cabeceo) es la estabilidad sobre el eje lateral. La respuesta (A) es incorrecta porque el CG tiene poca relación con el eje vertical. La respuesta (C) es incorrecta porque la estabilidad lateral no se ve muy afectada por la ubicación del CG."},
  {"id": 37, "s": 0, "q": "Un avión que sale del efecto suelo:", "o": ["Experimenta una reducción en la fricción con el suelo y requiere una ligera reducción de potencia.", "Experimenta un incremento en la resistencia inducida y requiere más empuje.", "Requiere un bajo ángulo de ataque para mantener el mismo coeficiente de sustentación."], "a": 1, "e": "A medida que el ala se encuentra bajo el efecto suelo con un coeficiente de sustentación constante, hay una reducción de los vórtices de punta de ala. Esto provoca una reducción en la resistencia inducida. Mientras está en efecto suelo, el avión requiere menos empuje para mantener la sustentación. También necesitara un ángulo de ataque bajo. Cuando un avión deja el efecto suelo, hay un incremento en la resistencia se requerirá un mayor ángulo de ataque. Adicionalmente se requerirá más empuje para compensar la pérdida. La respuesta (A) es incorrecta porque el rozamiento con el suelo se reduce al salir del efecto suelo. La respuesta (C) es incorrecta porque se requiere un mayor ángulo de ataque para mantener el mismo coeficiente de sustentación cuando abandona el suelo."},
  {"id": 38, "s": 0, "q": "Si la velocidad del aire es incrementada durante un giro nivelado, ¿qué acción sería necesaria para mantener la altitud? El ángulo de ataque:", "o": ["Y el ángulo de giro deben incrementarse.", "Deberá ser incrementado o reducido el ángulo de giro.", "Deberá ser disminuido o incrementado el ángulo de giro."], "a": 2, "e": "Para compensar la sustentación añadida que se producirá si la velocidad del aire aumenta durante un giro, el ángulo de ataque debe disminuirse, o el ángulo de giro debe ser incrementado, si se quiere mantener una altitud constante. La respuesta (A) es incorrecta porque se puede disminuir el ángulo de ataque o aumentar el ángulo de inclinación para mantener la altitud al aumentar la velocidad del aire. La respuesta (B) es incorrecta porque para mantener una altitud constante en un giro a medida que aumenta la velocidad del aire, el ángulo de inclinación debe disminuir."},
  {"id": 39, "s": 0, "q": "Para mantener una tasa de giro estándar con la velocidad del aire incrementando, el ángulo de banqueo del avión tendrá que:", "o": ["Permanecer constante.", "Incrementar.", "Disminuir."], "a": 1, "e": "A medida que la velocidad del aire aumenta en un ángulo de banqueo constante la velocidad de giro disminuirá. Por ejemplo, para un ángulo de banqueo de 30° a 100 nudos su tasa de giro será 6.5 grados por segundo. Si usted mantiene el ángulo de banqueo en 30 grados e incrementa la velocidad a 150 nudos su tasa de giro disminuirá a 4.4 grados por segundo. Por lo tanto, para mantener una tasa de giro estándar de 3 o 1,5 grados por segundo (Aviones de alta velocidad), a medida que la velocidad del aire incrementa el ángulo de banqueo deberá incrementarse."},
  {"id": 40, "s": 0, "q": "La velocidad de pérdida de un avión se verá más afectada por:", "o": ["Cambios en la densidad del aire.", "Variaciones en las altitudes de vuelo.", "Variaciones en cargas del avión."], "a": 2, "e": "La velocidad de pérdida se ve más afectada por el factor de carga. La velocidad de pérdida del avión incrementa en proporción a la raíz cuadrada del factor de carga, mientras que un cambio en la altitud (densidad del aire) no tiene efecto en la velocidad de pérdida indicada."},
  {"id": 41, "s": 0, "q": "Un avión entrará en pérdida en el mismo:", "o": ["Valor de ángulo de ataque independientemente de la altitud con relación al horizonte.", "Velocidad del aire independientemente de la altitud con relación al horizonte.", "Ángulo de ataque y altitud con relación al horizonte."], "a": 0, "e": "La definición de una pérdida es cuando el avión excede el ángulo de ataque crítico. Esto sucede porque el flujo de aire suave sobre la superficie del ala del avión se interrumpe y la sustentación se degenera rápidamente. Esto puede ocurrir a cualquier velocidad del aire, en cualquier altitud, y con cualquier ajuste de potencia."},
  {"id": 42, "s": 0, "q": "Si el ángulo de ataque es mantenido en efecto suelo cuando este está fuera del efecto suelo, la sustentación:", "o": ["Incrementa, e induce que la resistencia parásita disminuya.", "Decrece, y la resistencia parásita incrementa.", "Incrementa, e induce que la resistencia parásita aumente."], "a": 0, "e": "Si el avión es llevado bajo el efecto suelo con un ángulo de ataque constante, experimentará un crecimiento en el coeficiente de sustentación y una reducción del empuje requerido. La reducción de los vórtices en la punta del ala debido al efecto tierra alteran la distribución de sustentación a lo largo de la envergadura y reduce el flujo inducido. La reducción del flujo inducido causa significantes reducciones en la resistencia inducida, pero no tiene un efecto directo sobre la resistencia parásita."},
  {"id": 43, "s": 0, "q": "¿Qué rendimiento es característico del vuelo con la máxima relación de sustentación/arrastre en avión de hélice?", "o": ["Ganancia de altitud en una distancia determinada.", "Alcance y planeo de máxima distancia.", "Coeficiente de sustentación y mínimo coeficiente de resistencia."], "a": 1, "e": "La condición de alcance máximo ocurre cuando la proporción entre la velocidad y la potencia requerida es mayor. La condición de máxima autonomía (de los aviones de hélice) se obtiene con la máxima relación sustentación/ resistencia (L/D (MAX)). El mejor ángulo de planeo es el que permite a el avión recorrer grandes distancias sobre el terreno con la menor pérdida de altitud. Este es también el máximo L/D del avión y suele expresarse en forma de una tasa. Esto implica que el avión debe volarse a L/D (MAX) para obtener la mayor distancia de planeo."},
  {"id": 44, "s": 0, "q": "¿Cuál es la verdad respecto a las fuerzas que actúan sobre un avión en un descenso en estado estable? La suma de todas:", "o": ["Las fuerzas ascendentes son menores que la suma de todas las fuerzas descendentes.", "Las fuerzas hacia atrás son más grandes que la suma de todas las fuerzas hacia delante.", "Las fuerzas ascendentes son iguales que la suma de todas las fuerzas descendentes."], "a": 2, "e": "En vuelo estable, la suma de las fuerzas opuestas es igual a cero. La suma de todas las fuerzas ascendentes es igual a todas las fuerzas descendentes. La suma de todas las fuerzas hacia delante es igual a la suma de todas las fuerzas hacia atrás."},
  {"id": 45, "s": 0, "q": "¿Cuál es la verdad con respecto a la fuerza de sustentación en vuelo estable no acelerado?", "o": ["A menor velocidad del aire, el ángulo de ataque debe ser menor para generar la suficiente sustentación para mantener la altitud.", "Hay una correspondiente velocidad indicada requerida para cada ángulo, para así generar la suficiente sustentación y mantener la altitud.", "Un perfil aerodinámico entrará en pérdida a la misma velocidad del aire indicada; por lo tanto, un incremento en el peso requerirá un incremento en la velocidad para generar la suficiente sustentación y mantener la altitud."], "a": 1, "e": "Para mantener el equilibrio de las fuerzas de sustentación y peso, y mantener el avión recto y nivelado en un estado de equilibrio, cuando la velocidad incrementa el ángulo de ataque deberá disminuir. A la inversa, a medida que el avión disminuya su velocidad, el ángulo de ataque deberá aumentar para crear la suficiente sustentación para mantener el vuelo recto y nivelado. Por lo tanto, para cada ángulo de ataque hay una correspondiente velocidad del aire requerida para mantener la altitud en vuelo estable no acelerado, siendo constantes todos los demás valores. La respuesta (A) es incorrecta porque para proporcionar la suficiente sustentación, el ángulo de ataque debe incrementar a medida que se reduce la velocidad del aire. La respuesta (C) es incorrecta porque el ángulo de ataque deberá incrementar para compensar la disminución de la sustentación."},
  {"id": 46, "s": 0, "q": "Cuando hay una transición de un vuelo recto y nivelado a un ascenso con velocidad constante, el ángulo de ataque y sustentación:", "o": ["Se incrementan y se mantiene con una mayor relación peso-sustentación para mantener el ascenso.", "Permanecen igual y mantendrá estable la relación peso-sustentación durante el ascenso.", "Se incrementan momentáneamente y la sustentación vuelven a un estado estable durante el ascenso."], "a": 2, "e": "Al realizar la transición de un vuelo nivelado a un ascenso, las fuerzas que actúan sobre el avión sufren ciertos caminos. El primer cambio, se produce cuando se aplica una contrapresión al mando del elevador. Este cambio inicial es el resultado del aumento del ángulo de ataque que se produce cuando se eleva la actitud de cabeceo del avión. Esto da a lugar a una actitud de ascenso. Cuando se establece la trayectoria de vuelo inclinada y la velocidad de ascenso, el ángulo de ataque y la sustentación correspondiente se estabilizan en el valor original."},
  {"id": 47, "s": 0, "q": "Para mantener un avión en vuelo nivelado, con velocidades del aire que varían de muy lentas a muy rápidas, un piloto debe coordinar el empuje y:", "o": ["Ángulo de incidencia.", "Peso bruto.", "Ángulo de ataque."], "a": 2, "e": "El vuelo recto y nivelado puede ser mantenido en un amplio rango de velocidades. El piloto debe coordinar el ángulo de ataque y el empuje en todos los regímenes de velocidad para que la aeronave pueda mantenerse en vuelo nivelado."},
  {"id": 48, "s": 0, "q": "Para generar la misma cantidad de sustentación cuando la altitud aumenta, un avión debe volar a:", "o": ["La misma velocidad verdadera del aire independientemente del ángulo de ataque.", "A una baja velocidad verdadera del aire y un alto ángulo de ataque.", "Una alta velocidad verdadera del aire para cualquier ángulo de ataque."], "a": 2, "e": "Para mantener la sustentación a una mayor altitud, un avión debe volar a una mayor velocidad verdadera del aire para cualquier ángulo de ataque. La respuesta (A) es incorrecta porque la velocidad verdadera del aire debe ser incrementada a medida que se incrementa la altitud generando la misma cantidad de sustentación. La respuesta (B) es incorrecta porque la velocidad verdadera del aire debe ser incrementada a medida que se incrementa la altitud generando la misma cantidad de sustentación."},
  {"id": 49, "s": 0, "q": "Para producir la misma sustentación cuando se está bajo el efecto suelo que cuando se encuentra fuera de él, el avión requiere", "o": ["Un bajo ángulo de ataque.", "El mismo ángulo de ataque.", "Un mayor ángulo de ataque."], "a": 0, "e": "Si el avión es llevado bajo el efecto suelo con un ángulo de ataque constante, este experimentara un aumento en el crecimiento en el coeficiente de sustentación y una reducción en el empuje requerido. La reducción de los vórtices en la punta del ala debido al efecto suelo alteran la distribución de la sustentación en el ala y reducen el flujo inducido. La reducción del flujo inducido causa una significante reducción en la resistencia inducida, peno no tienen un efecto directo sobre la resistencia parásita."},
  {"id": 50, "s": 0, "q": "Al aumentar el ángulo de banqueo, la componente vertical de sustentación:", "o": ["Disminuye y la componente horizontal de sustentación incrementa.", "Incrementa y la componente horizontal de sustentación disminuye.", "Disminuye y la componente horizontal de sustentación disminuye."], "a": 0, "e": "La sustentación en un banqueo es dividida en dos componentes, una vertical y la otra horizontal. La componente vertical de sustentación debe ser igual al peso para mantener la altitud. Dado que la componente vertical de sustentación disminuye a medida que incrementa el ángulo de banqueo, el ángulo de ataque debe ser progresivamente incrementado para producir la suficiente sustentación vertical para soportar el peso del avión. El incremento de la presión en el elevador trasero proporcionara el aumento del ángulo de ataque."},
  {"id": 51, "s": 0, "q": "Si la altitud del avión permanece en una nueva posición después de presionar el control del elevador hacia delante y soltarlo, el avión mostrara:", "o": ["Estabilidad longitudinal estática neutral.", "Estabilidad longitudinal estática positiva.", "Estabilidad longitudinal dinámica neutral."], "a": 0, "e": "La estabilidad estática neutral es la tendencia inicial del avión a permanecer en la nueva condición después de que su equilibrio ha sido perturbado. Cuando la altitud de un avión es momentáneamente desplazada y esta permanece en la nueva altitud, está mostrando una estabilidad longitudinal estática neutra. La estabilidad longitudinal hace que un avión sea estable alrededor de su eje lateral (cabeceo). La respuesta (B) es incorrecta porque la estabilidad estática longitudinal positiva es la tendencia inicial del avión a volver a su actitud original después de presionar el control del elevador hacia adelante y soltarlo. La respuesta (C) es incorrecta porque la estabilidad dinámica longitudinal neutra es la tendencia general del avión a permanecer en la nueva condición durante un período de tiempo."},
  {"id": 52, "s": 0, "q": "La inestabilidad dinámica en un avión puede ser identificada mediante:", "o": ["Las oscilaciones en un banco, las cuales se vuelven progresivamente más pronunciadas.", "Las oscilaciones de cabeceo, las cuales se vuelven progresivamente más pronunciadas.", "Las oscilaciones en los tres ejes se vuelven progresivamente más pronunciadas."], "a": 1, "e": "La estabilidad longitudinal, o cabeceo sobre el eje lateral, se considera el más afectado por ciertas variables en diversas condiciones de vuelo. Un avión longitudinalmente inestable tiene la tendencia a bajar y subir progresivamente, lo que puede resultar en una entrada en pérdida. Un avión longitudinalmente inestable es dificultoso y a veces peligroso de volar. La respuesta (A) es incorrecta porque las oscilaciones de balanceo se refieren a la estabilidad lateral. La respuesta (C) es incorrecta porque las oscilaciones de balanceo se refieren a la estabilidad lateral."},
  {"id": 53, "s": 0, "q": "La estabilidad longitudinal implica el movimiento del avión controlado a través del:", "o": ["Timón de dirección.", "Elevador.", "Alerones."], "a": 1, "e": "La estabilidad longitudinal o cabeceo es el movimiento alrededor del eje lateral. El cabeceo es controlado por medio del elevador. La respuesta (A) es incorrecta porque el timón afecta a la estabilidad direccional. La respuesta (C) es incorrecta porque los alerones afectan a la estabilidad lateral."},
  {"id": 54, "s": 0, "q": "¿Qué cambios en el control longitudinal de un avión deben realizarse para mantener la altitud, mientras la velocidad del aire es disminuida?", "o": ["Incrementar el ángulo de ataque para producir más sustentación que resistencia.", "Incrementar el ángulo de ataque para compensar la disminución de sustentación.", "Disminuir el ángulo de ataque para compensar el incremento de la resistencia."], "a": 1, "e": "A medida que el avión disminuye su velocidad, la disminución de la velocidad del aire requiere un incremento del ángulo de ataque para producir la sustentación constante necesaria para mantener la altitud, La respuesta (A) es incorrecta porque si se genera más sustentación que resistencia, un incremento en el ángulo de ataque causa que el avión ascienda. La respuesta (C) es incorrecta porque el ángulo de ataque debe ser incrementado para mantener la altitud, si la velocidad del aire está siendo disminuida. La respuesta (B) es incorrecta porque ésta describe un giro con derrape. La respuesta (C) es incorrecta porque se requiere una ligera presión de oposición en los alerones para compensar la tendencia de sobregiro, no para mantener la altitud."},
  {"id": 55, "s": 0, "q": "Si la altitud inicial del avión tiende a retornar a su posición original después de presionar el mando del elevador hacia delante y soltarlo, el avión muestra:", "o": ["Estabilidad dinámica positiva.", "Estabilidad estática positiva.", "Estabilidad dinámica neutral."], "a": 1, "e": "La estabilidad estática se ocupa de las tendencias iniciales. La estabilidad estática positiva es la tendencia inicial del avión a retornar a su estado original después de ser perturbado."},
  {"id": 56, "s": 0, "q": "Una hélice que gira en el sentido de las agujas del reloj, visto desde atrás, crea una corriente de deslizamiento en espiral. La corriente de deslizamiento en espiral, junto con el efecto del torque, tiende a girar al avión hacia la:", "o": ["A la derecha respecto al eje vertical y a la izquierda respecto al eje longitudinal.", "A la izquierda respecto al eje vertical y a la derecha respecto al eje longitudinal.", "A la izquierda respecto al eje vertical y a la izquierda respecto al eje longitudinal."], "a": 1, "e": "La estela de la hélice que golpea la aleta vertical, lo que provoca una guiñada hacia la izquierda, al mismo tiempo que provoca un momento de balanceo sobre la derecha."},
  {"id": 57, "s": 0, "q": "¿Qué factor disminuye su máximo rango al disminuir el peso?", "o": ["Altitud.", "Velocidad del aire.", "Ángulo de ataque."], "a": 1, "e": "La condición de máximo rango se obtiene con la máxima relación L/D que ocurre para un ángulo de ataque y un coeficiente de sustentación determinados. A medida que el peso bruto disminuye, la velocidad del aire para el máximo L/D decrecerá. La respuesta (A) es incorrecta porque cuando el peso disminuye, el rango máximo de altitud puede incrementar. La respuesta (C) es incorrecta porque el ángulo de inclinación no juega un rol en la determinación de un rango máximo."},
  {"id": 58, "s": 0, "q": "¿Qué afirmación es verdadera con respecto a la circulación de vórtices en la estela turbulenta generada por un avión?", "o": ["Los helicópteros generan únicamente turbulencia, no circulación de vórtices.", "La fuerza del vórtice es mayor cuando el avión generador es de gran tamaño, y lento.", "Cuando la circulación del vórtice se hunde en el efecto suelo, tiende a disiparse rápidamente y genera poco peligro."], "a": 1, "e": "La fuerza de un vórtice se rige por el peso, la velocidad y la forma del ala de la aeronave generadora. La fuerza máxima del vórtice se produce cuando la aeronave generadora es pesada y lenta."},
  {"id": 59, "s": 0, "q": "Escoja la afirmación correcta sobre la estela turbulenta:", "o": ["La generación de vórtices comienza con la iniciación del giro en el despegue.", "El peligro principal es la pérdida de control por el giro inducido", "La mayor fuerza del vórtice es producida cuando el avión generador es grande y rápido."], "a": 1, "e": "Los vórtices se generan a 400-500 fpm. La generación de vórtices comienza cuando se produce la sustentación en el despegue. La mayor fuerza de los vórtices se produce cuando el avión es pesado y lento. El principal peligro es la pérdida de control debido al balanceo inducido causado por los vórtices giratorios. La respuesta (A) es incorrecta porque la generación de vórtices comienza en el punto de rotación cuando el avión despega. La respuesta (C) es incorrecta porque la mayor fuerza de los vórtices se produce cuando el avión generador es pesado y lento."},
  {"id": 60, "s": 0, "q": "Durante un despegue realizado detrás de un avión de gran tamaño, el piloto puede minimizar el peligro de los vórtices de las alas realizando la siguiente acción:", "o": ["Permanecer en el aire antes de alcanzar la trayectoria de vuelo del avión hasta poder girar para evitar su estela.", "Mantener una velocidad extra en el despegue y ascenso.", "Alargar el giro en el despegue y no rotando hasta más allá del punto de rotación del avión."], "a": 0, "e": "Los vórtices comienzan a formarse cuando el avión está realizando una rotación. Planee salir de la pista antes de alcanzar el punto de rotación del avión, luego vuele por encima de la trayectoria vuelo o apártese de ella."},
  {"id": 61, "s": 0, "q": "Si usted vuela en la trayectoria de un avión de gran tamaño, para evitar los vórtices usted deberá volar:", "o": ["A la misma altitud que el avión más grande.", "Por debajo de la altitud del avión más grande.", "Por encima de la trayectoria de vuelo del avión más grande."], "a": 2, "e": "Volar por encima de la trayectoria de vuelo del avión siempre que sea posible, porque los vórtices descienden. Evite volar por debajo y detrás de la trayectoria de un avión grande."},
  {"id": 62, "s": 0, "q": "Para evitar posibles turbulencias en la estela de un avión de gran tamaño que acaba de aterrizar, antes de su despegue, en qué punto de la pista se debe planificar su despegue:", "o": ["Pasado el punto en que el avión toco tierra.", "En el punto en que el avión toco tierra, o justo antes de este punto.", "Aproximadamente 500 pies antes del punto donde el avión toco tierra."], "a": 0, "e": "Los vórtices dejan de generarse cuando el avión aterriza. Planifique su vuelo más allá de este punto."},
  {"id": 63, "s": 0, "q": "¿Cuándo se aterriza detrás de un avión de gran tamaño, que procedimiento deberá seguirse para evitar vórtices?", "o": ["Permanecer por encima de su trayectoria de vuelo de aproximación final, hasta el aterrizaje.", "Permanecer por debajo de su trayectoria de vuelo de aproximación final.", "Permanecer muy por debajo de su trayectoria de vuelo de aproximación final y aterrizar al menos 2000 pies por detrás."], "a": 0, "e": "Mantenerse en o por encima de la trayectoria de vuelo de aproximación final de la aeronave de gran tamaño. Observe el punto de aterrizaje y aterrice más allá de él."},
  {"id": 64, "s": 0, "q": "Un avión con ala con flechada con una estabilidad estática débil y un diedro aumentado provoca un aumento de:", "o": ["La tendencia al momento de picada.", "Tendencia a un tonel holandés.", "Estabilidad longitudinal."], "a": 1, "e": "Cuando el efecto del diedro es grande en comparación con la estabilidad estática de la dirección, el movimiento de balanceo tiene una amortiguación débil y se incrementa. La respuesta (A) es incorrecta porque la tendencia al momento de picado se produce al atravesar la barrera del sonido. La respuesta (C) es incorrecta porque la estabilidad longitudinal no se ve afacetada por la estabilidad direccional o el diedro."},
  {"id": 65, "s": 0, "q": "¿Cuál es el mejor indicador para el piloto acerca del factor de carga del avión?", "o": ["Con qué firmeza el piloto es presionado en la silla durante una maniobra.", "La cantidad de presión requerida para operar los controles.", "La velocidad del aire cuando se sale de un descenso."], "a": 0, "e": "El factor de carga puede detectarse observando la fuerza con la que el piloto es presionado en el asiento durante una maniobra. Si una aeronave se eleva desde una inmersión, sometiendo al piloto a 3 GS, este sería presionado hacia abajo en el asiento con una fuerza igual a tres veces su peso."},
  {"id": 66, "s": 0, "q": "Si la velocidad del aire se disminuye de 98 nudos a 85 nudos durante un giro coordinadoy nivelado de 45 grados, el factor de carga:", "o": ["Será el mismo, pero el radio del giro disminuirá.", "Disminuirá y la tasa de giro decrecerá.", "Será el mismo, pero el radio de giro aumentará."], "a": 0, "e": "A un ángulo de inclinación determinado, una pérdida en la velocidad del aire hará que el radio de giro sea menor y el avión girara a mayor velocidad. Esto compensa la reducción de la fuerza centrífuga, permitiendo que el factor de carga permanezca siendo el mismo."},
  {"id": 67, "s": 0, "q": "Si la velocidad del aire es incrementada de 89 nudos a 98 nudos durante un giro coordinado con una inclinación de 45°, el factor de carga:", "o": ["Decrecerá y el radio de giro disminuirá.", "Permanecen igual, pero el radio de giro se incrementará.", "Aumentará, pero el radio de giro disminuirá."], "a": 1, "e": "Cuando se realiza un giro con una velocidad del aire alta con un ángulo de banqueo determinado, la inercia es mayor y la componente de sustentación requerida para el giro será más alta, causando que la tasa de giro se más lenta. Por lo tanto, a un ángulo de banqueo determinado, una velocidad del aire alta hará que el radio de giro incremente por lo que el avión girara a una velocidad más lenta. Esto compensa la fuerza centrífuga añadida, permitiendo que el factor de carga siga siendo el mismo."},
  {"id": 68, "s": 1, "q": "Antes del apagado, a mínima potencia, la llave de ignición se selecciona momentáneamente a apagado. El motor continúa encendido sin interrupción; esto:", "o": ["Es normal porque el motor generalmente se detiene moviendo la mezcla al corte de ralentí.", "Normalmente no debería suceder. Indica que un magneto no está conectado a tierra en la posición apagado.", "Es una práctica indeseable, pero indica que nada está mal."], "a": 1, "e": "Si el cable de tierra del interruptor magnético está desconectado, el magneto está encendido, aunque el interruptor de encendido esté en la posición apagado. El motor podría disparar si la hélice se mueve desde fuera del avión. La respuesta (A) es incorrecta porque el motor debe detenerse cuando se gira la llave de encendido a la posición apagado. La respuesta (C) es incorrecta porque indica que hay un cable de tierra defectuoso."},
  {"id": 69, "s": 1, "q": "Dejar el calentador del carburador encendido durante el despegue:", "o": ["Empobrece la mezcla para obtener más potencia en el despegue.", "Disminuirá la distancia de despegue.", "Incrementará la distancia de la carrera de despegue."], "a": 2, "e": "Modificar calor del carburador por “calentador del carburador”. Modificar velocidad de despegue por velocidad de rotación. Aumentará la distancia de la carrera de despegue."},
  {"id": 70, "s": 1, "q": "Una forma de detectar un cable de tierra primario roto del magneto es:", "o": ["Poner el motor en ralentí y seleccionar la ignición en apagado.", "Ajustar máxima potencia, mientras mantiene presionado los frenos y selecciona momentáneamente la ignición en apagado", "Opere con solo un magneto, empobrezca la mezcla y busque un aumento en la presión del colector."], "a": 0, "e": "Si el cable de tierra del interruptor del magneto está desconectado, el magneto está ENCENDIDO, aunque el interruptor de encendido esté en la posición APAGADO. El motor podría encender si la hélice se mueve desde fuera del avión. La respuesta (B) es incorrecta porque no es necesario agregar toda la potencia al realizar laverificación. La respuesta (C) es incorrecta porque la forma de detectar un cable de tierra del magnetoroto es seleccionar la ignición a la posición APAGADO); si el motor sigue funcionando, se confirma el problema."},
  {"id": 71, "s": 1, "q": "Es más probable que se ensucien las bujías si la aeronave:", "o": ["Gana altitud sin ajuste de mezcla.", "Descensos sin ajuste de mezcla.", "El acelerador se avanza muy abruptamente."], "a": 0, "e": "Si la mezcla de combustible/aire es demasiado rica, se producirá un consumo excesivo de combustible, un funcionamiento irregular del motor y una pérdida apreciable de potencia. Debido al exceso de combustible, se produce un efecto de enfriamiento que provoca temperaturas por debajo de lo normal en las cámaras de combustión. Este enfriamiento da como resultado un ensuciamiento de la bujía. A menos que la mezcla se empobrece con una ganancia de altura, la mezcla se vuelve excesivamente rica."},
  {"id": 72, "s": 1, "q": "La razón más probable por la que un motor sigue funcionando después de seleccionar la ignición a apagado es:", "o": ["El depósito de carbón que brillan en las bujías.", "Un cable de tierra del magneto está en contacto con la carcasa del motor.", "Un cable de tierra de magneto roto."], "a": 2, "e": "Si el cable de tierra del interruptor del magneto está desconectado el magneto está ENCENDIDO, aunque el interruptor de encendido esté en la posición APAGADO. El motor podría encender si la hélice se mueve desde fuera del avión. La respuesta (A) es incorrecta porque los depósitos de carbón brillantes son el resultado de la pre- ignición La respuesta (B) es incorrecta porque un cable de tierra del magneto debe estar en contacto con la carcasa del motor para proporcionar una conexión a tierra."},
  {"id": 73, "s": 1, "q": "Si el cable de tierra entre el magneto y el interruptor de encendido se desconecta, el motor:", "o": ["No funcionará un magneto.", "No se puede iniciar con el interruptor en la posición de BOTH.", "Podría arrancar accidentalmente si la hélice se mueve con combustible en el cilindro."], "a": 2, "e": "Si el cable de tierra del interruptor del magneto está desconectado, el magneto está ENCENDIDO, aunque el interruptor de encendido esté en la posición APAGADO. El motor podría encender si la hélice se mueve desde fuera del avión. La respuesta (A) es incorrecta porque ambos magnetos permanecen encendidos cuando se desconecta el cable de tierra. La respuesta (B) es incorrecta porque el motor aún se puede arrancar y los magnetos no se pueden apagar."},
  {"id": 74, "s": 1, "q": "Para el enfriamiento interno, los motores recíprocos de la aeronave dependen especialmente de:", "o": ["Un aumentador de cowl flaps que funcione correctamente.", "La circulación de aceite lubricante.", "La razón adecuada de freón/compresor a la salida."], "a": 1, "e": "El aceite lubricante tiene dos propósitos: 1. Proporciona una capa de aceite sobre las superficies de las partes móviles, evitando el contacto de metal con metal y la generación de calor; y 2. Absorbe y disipa, a través del sistema de enfriamiento de aceite, parte del calor del motor producido por el proceso de combustión interna. La respuesta (A) es incorrecta porque, aunque los cowl flaps ayudan ayudan al enfriamiento interno, no son la fuente principal de enfriamiento. La respuesta (C) es incorrecta porque la Razón de freón/compresor a la salida"},
  {"id": 75, "s": 1, "q": "El piloto controla la razón de aire/combustible con:", "o": ["Acelerador.", "Presión en el colector.", "Control de mezcla."], "a": 2, "e": "La razón aire/combustible de la mezcla combustible entregada al motor se controla mediante el control de mezcla. La respuesta (A) es incorrecta porque el acelerador regula el volumen total de combustible y aire que ingresa a la cámara de combustión. La respuesta (B) es incorrecta porque la presión del colector indica la potencia del motor."},
  {"id": 76, "s": 1, "q": "¿Qué enunciado describe mejor el principio operativo de una hélice de velocidad constante o de paso variable?", "o": ["A medida que el piloto cambia el ajuste del acelerador, el gobernador de hélice hace que el ángulo de paso de las palas de la hélice permanezca sin cambios.", "Un ángulo de pala alto, o un mayor ángulo de inclinación reduce la resistencia de la hélice y permite más potencia del motor para los despegues.", "El control de la hélice regula las RPM del motor y, a su vez, las RPM de la hélice."], "a": 2, "e": "El control de la hélice regula las RPM del motor y, a su vez, las RPM de la hélice. Las RPM se registran en el tacómetro. La respuesta (A) es incorrecta porque el gobernador de la hélice hace que el ángulo de inclinación de las palas de la hélice cambie para ayudar a mantener una velocidad especifica. La respuesta (B) es incorrecta porque un ángulo alto de la pala aumentará la resistencia de la hélice con menos potencia del motor."},
  {"id": 77, "s": 1, "q": "En aeronaves equipadas con hélices de velocidad constante/paso variable y motores de aspiración normal, ¿Qué procedimiento se debe utilizar para evitar una tensión indebida en los componentes del motor? Cuando la potencia está siendo:", "o": ["Disminuida, reduzca las RPM antes de reducir la presión del colector.", "Aumentada, incrementa las RPM antes de aumentar la presión del colector.", "Aumentada o disminuida, las RPM deben ajustarse antes que la presión del colector."], "a": 1, "e": "El procedimiento de cambio de potencia en una hélice de velocidad constante es aumentar las RPM antes de la presión del colector. Para disminuir la potencia, reduzca la presión del colector antes de reducir las RPM. Esto ayudará a evitar una tensión indebida en los componentes del motor. La respuesta (A) es incorrecta porque cuando se reduce la potencia, la presión del colector debe reducirse antes de reducir las RPM. La respuesta (C) es incorrecta porque cuando se reduce la potencia, la presión del colector debe reducirse antes de reducir las RPM."},
  {"id": 78, "s": 1, "q": "La detonación puede ocurrir en configuraciones de alta potencia cuando:", "o": ["La mezcla de combustible se enciende instantáneamente en lugar de arder de manera progresiva y uniforme.", "Una mezcla de combustible excesivamente rica provoca una ganancia explosiva de potencia.", "La mezcla de combustible se enciende demasiado pronto debido a los depósitos de carbón caliente en el cilindro."], "a": 0, "e": "La detonación o golpe es una explosión o golpe repentino en un área pequeña de la parte superior del pistón, en lugar de la quemadura suave normal en la cámara de combustión. La respuesta (B) es incorrecta porque la detonación puede ocurrir con una mezcla de combustible demasiado pobre y una pérdida de potencia. La respuesta (C) es incorrecta porque describe la pre-ignición."},
  {"id": 79, "s": 1, "q": "El encendido no controlado de la carga de combustible/aire antes de la ignición normal por chispa se conoce como:", "o": ["Combustión instantánea.", "Detonación", "Preignicion."], "a": 2, "e": "Cuando la cabeza del cilindro se calienta demasiado, puede encender la mezcla de combustible / aire antes de la chispa. Esta condición se llama preignición. La respuesta (A) es incorrecta porque la detonación es una combustión instantánea de la mezcla de combustible / aire, que se produce al usar una mezcla demasiado pobre, al usar un grado de combustible demasiado bajo o al operar con temperaturas demasiado altas. La respuesta (B) es incorrecta porque la detonación es una combustión instantánea de la mezcla de combustible / aire, que se produce al usar una mezcla demasiado pobre, al usar un grado de combustible demasiado bajo o al operar con temperaturas demasiado altas."},
  {"id": 80, "s": 1, "q": "La razón combustible/aire es relacionada entre:", "o": ["Volumen de combustible y volumen de aire que entra en el cilindro.", "Peso del combustible y peso del aire que ingresa al cilindro.", "Peso de combustible y peso de aire que ingresa al carburador."], "a": 1, "e": "El control de mezcla se usa para cambiar la mezcla de combustible a aire que ingresa a la cámara de combustión (cilindro). La razón combustible/aire es el peso de combustible a un peso dado de aire. La respuesta (A) es incorrecta porque, a medida que aumenta la altitud, la cantidad de aire en un volumen fijo disminuye. La respuesta (C) es incorrecta porque el carburador es donde se establece la razón combustible/aire antes de ingresar a los cilindros."},
  {"id": 81, "s": 1, "q": "El control de la mezcla se puede ajustar, lo cual:", "o": ["Evita que la combinación de combustible / aire se vuelva demasiado rica a mayores altitudes.", "Regula la cantidad de flujo de aire a través del Venturi del carburador.", "Evita que la combinación de aire / combustible se empobrece a medida que el avión asciende."], "a": 0, "e": "A medida que la aeronave asciende, la mezcla de aire y combustible se vuelve más rica y el exceso de combustible hace que el motor pierda potencia y funcione más bruscamente. El control de mezcla proporciona un medio para que el piloto reduzca el combustible para compensar este desequilibrio en la mezcla a medida que aumenta la altitud. La respuesta (B) es incorrecta porque el acelerador regula el flujo de aire a través del Venturi del carburador. La respuesta (C) es incorrecta porque la razón combustible / aire se vuelve más rica a medida que la aeronave asciende."},
  {"id": 82, "s": 1, "q": "¿Qué afirmación es verdadera con respecto a la aplicación del calentador al carburador?", "o": ["Enriquece la mezcla combustible/aire.", "Se empobrece la mezcla combustible/aire.", "No tiene ningún efecto sobre la mezcla combustible/aire."], "a": 0, "e": "El uso del calor del carburador enriquece la mezcla, lo que tiende a reducir la potencia del motor y también aumenta la temperatura de funcionamiento."},
  {"id": 83, "s": 1, "q": "La detonación ocurre en un motor reciproco de una aeronave cuando:", "o": ["Hay un aumento explosivo de combustible causado por una mezcla de combustible / aire demasiado rico.", "Las bujías reciben una descarga eléctrica causada por un cortocircuito en el cableado.", "La carga de combustible / aire sin quemar en los cilindros se somete a combustión instantánea."], "a": 2, "e": "La detonación es una explosión repentina, o combustión instantánea, de la mezcla de aire / combustible en los cilindros, que produce calor extremo y tensiones estructurales severas en el motor. La respuesta (A) es incorrecta porque la detonación es causada por una mezcla demasiado pobre. La respuesta (B) es incorrecta porque la detonación no tiene nada que ver con el cableado."},
  {"id": 84, "s": 1, "q": "La eficiencia de la hélice es:", "o": ["La relación entre caballos de fuerza de potencia y caballos de fuerza de freno.", "La distancia real que avanza una hélice en una revolución.", "La relación entre el paso de geometría y el paso efectivo."], "a": 0, "e": "Dado que la eficiencia de cualquier máquina es la relación entre la salida de potencia útil y la potencia de entrada real, la eficiencia de la hélice es la relación entre los caballos de fuerza de potencia y los caballos de fuerza del freno. La respuesta (B) es incorrecta porque el paso efectivo es la distancia real que avanza una hélice en una revolución. La respuesta (C) es incorrecta porque la relación entre el paso geométrico y el paso efectivo se denomina deslizamiento."},
  {"id": 85, "s": 1, "q": "Una hélice de paso fijo está diseñada para obtener la mejor eficiencia solo con una combinación determinada de:", "o": ["Altitud y RPM.", "Velocidad aerodinámica y RPM.", "Velocidad aerodinámica y altitud."], "a": 1, "e": "Las hélices de paso fijo son más eficientes solo con una combinación determinada de velocidad aerodinámica y RPM. La respuesta (A) es incorrecta porque la altitud no afecta la eficiencia de la hélice. La respuesta (C) es incorrecta porque la altitud no afecta la eficiencia de la hélice."},
  {"id": 86, "s": 1, "q": "La razón por la cual hay variación en el paso geométrico (torsión) a lo largo de una palade una hélice es que:", "o": ["Permite un ángulo de incidencia relativamente constante a lo largo de su longitud en crucero.", "Evita que la parte de la pala más cercana al buje de la hélice entre en perdida durante el crucero.", "Permite un ángulo de ataque relativamente constante a lo largo de su longitud cuando está en vuelo de crucero."], "a": 2, "e": "La torsión o las variaciones en el paso geométrico de las palas permiten que la hélice funcione con un ángulo de ataque relativamente constante a lo largo de su longitud cuando se encuentra en vuelo de crucero. La respuesta (A) es incorrecta porque las variaciones en el paso geométrico permiten un ángulo de ataque constante a lo largo de su longitud. La respuesta (B) es incorrecta porque las puntas de la hélice entrarían en perdida durante el crucero si no existiera una variación en el paso geométrico."},
  {"id": 87, "s": 1, "q": "Una desafinación de los contrapesos del cigijeñal del motor es una fuente de sobrecarga que puede ser causada por:", "o": ["Apertura y cierre rápidos del acelerador.", "Formación de hielo en la válvula mariposa en el carburador.", "Operar con una mezcla de combustible / aire excesivamente rica."], "a": 0, "e": "La rápida actuación del acelerador puede provocar la detonación, lo que puede desafinar el cigúeñal. La respuesta (B) es incorrecta porque el hielo en el carburador puede hacer que el motor deje de funcionar, pero no afectará los contrapesos del cigueñal del motor. La respuesta (C) es incorrecta porque operar con una mezcla excesivamente rica ensucia las bujías, pero no afecta el cigúeñal."},
  {"id": 88, "s": 1, "q": "La mezcla que da la mejor potencia se obtiene con la razón de combustible/aire con lacual:", "o": ["Las temperaturas de la cabeza de cilindros de son las más frías.", "Se puede obtener la mayor potencia para cualquier ajuste del acelerador dado.", "Se puede obtener una potencia determinada con la mayor presión del colector o ajuste del acelerador."], "a": 1, "e": "El ajuste del acelerador determina la cantidad de aire que fluye hacia el motor. Luego, el control de mezcla se ajusta para obtener la mejor relación combustible / aire, lo que da como resultado la mejor potencia que el motor puede desarrollar en este ajuste de aceleración en particular. La respuesta (A) es incorrecta porque las culatas de cilindros estarán más frías cuando la mezcla sea más rica. La respuesta (C) es incorrecta porque describe la configuración de potencia más alta."},
  {"id": 89, "s": 1, "q": "Considere un motor de avión reciproco. La detonación puede ser causada por:", "o": ["Una mezcla “rica”.", "Bajas temperaturas del motor.", "Utilizar un grado de combustible inferior al recomendado."], "a": 2, "e": "La detonación es una explosión o impacto repentino en un área pequeña de la parte superior del pistón, en lugar de la combustión suave normal en la cámara de combustión. Puede ser causado por combustible de baja calidad o una mezcla pobre."},
  {"id": 90, "s": 1, "q": "¿Qué puede pasar al aplicar calor al carburador?", "o": ["No afecta la mezcla.", "Inclinar la mezcla de combustible/aire.", "Se enriquece la mezcla de combustible/aire."], "a": 2, "e": "El uso del calor del carburador enriquece la mezcla, lo que tiende a reducir la potencia del motor y también aumenta la temperatura de funcionamiento."},
  {"id": 91, "s": 1, "q": "Una indicación de temperatura del aceite del motor anormalmente alta puede ser causada por:", "o": ["Un rodamiento defectuoso.", "El nivel de aceite es demasiado bajo.", "Operando con una mezcla excesivamente rica."], "a": 1, "e": "La indicación de presión de aceite varía inversamente con la temperatura del aceite. La temperatura alta y la presión baja generalmente indican un nivel de aceite bajo. La respuesta (A) es incorrecta porque un rodamiento defectuoso aumentará las partículas de metal en el aceite, pero no afectará significativamente la temperatura del aceite. La respuesta (C) es incorrecta porque una mezcla rica da como resultado temperaturas de funcionamiento del motor más bajas; por lo tanto, no aumentaría la temperatura del aceite del motor."},
  {"id": 92, "s": 1, "q": "¿Qué ocurre si no se empobrece con el control de mezcla a medida que aumenta laaltitud?", "o": ["El volumen de aire que ingresa al carburador disminuye y la cantidad de combustible disminuye.", "La densidad del aire que ingresa al carburador disminuye y aumenta la cantidad de combustible.", "La densidad del aire que ingresa al carburador disminuye y la cantidad de combustible permanece constante."], "a": 2, "e": "El flujo de combustible permanece constante si no se realizan ajustes. El mismo volumen de aire entra en el carburador, pero el peso y la densidad del aire son menores, lo que provoca una mezcla excesivamente rica, lo cual que las bujías se ensucien y disminuyan la potencia."},
  {"id": 93, "s": 1, "q": "A menos que se ajuste, la mezcla de aire/combustible se vuelve más rica con un aumentode altitud debido a que la cantidad de combustible:", "o": ["Disminuye mientras que el volumen de aire disminuye.", "Permanece constante mientras que el volumen de aire disminuye.", "Permanece constante mientras la densidad del aire disminuye."], "a": 2, "e": "El flujo de combustible permanece constante si no se realizan ajustes. El mismo volumen de aire entra en el carburador, pero el peso y la densidad del aire son menores, lo que provoca una mezcla excesivamente rica, que provoca que las bujías se ensucien y disminuyan la potencia."},
  {"id": 94, "s": 1, "q": "El propósito básico de ajustar el control de mezcla de combustible / aire en altitud es para que:", "o": ["Disminuya el flujo de combustible para compensar la disminución de la densidad del aire.", "Disminuya la cantidad de combustible en la mezcla para compensar el aumento de la densidad del aire.", "Aumente la cantidad de combustible en la mezcla para compensar la disminución de la presión y la densidad del aire."], "a": 0, "e": "El flujo de combustible permanece constante si no se realizan ajustes. El mismo volumen de aire entra en el carburador, pero el peso y la densidad del aire son menores, lo que provoca una mezcla excesivamente rica, que provoca que las bujías de ensucien y una disminución de la potencia."},
  {"id": 95, "s": 1, "q": "En altitudes elevadas, una mezcla excesivamente rica provocará que:", "o": ["El motor se sobrecaliente.", "Se ensucien las bujías.", "El motor opere más suave a pesar de que se aumente el consumo de combustible."], "a": 1, "e": "El flujo de combustible permanece constante si no se realizan ajustes. El mismo volumen de aire entra en el carburador, pero el peso y la densidad del aire son menores, lo que provoca una mezcla excesivamente rica, que provoca que las bujías se ensucien y una disminución de la potencia. La respuesta (A) es incorrecta porque una mezcla pobre hará que el motor se sobrecaliente. La respuesta (C) es incorrecta porque un motor funciona con más suavidad cuando la mezcla se ajusta a la altitud."},
  {"id": 96, "s": 1, "q": "Su avión tiene un sistema de calefacción de colector de escape. El colector del sistemade escape debería inspeccionarse periódicamente para evitar:", "o": ["Intoxicación por monóxido de carbono.", "Sobrecalentamiento en la cabina.", "Temperaturas extremadamente frías en la cabina."], "a": 0, "e": "La intoxicación por monóxido de carbono de los gases de escape que se filtran a la cabina del piloto por un colector de escape defectuoso se ha relacionado con varios accidentes de aviación fatales."},
  {"id": 97, "s": 1, "q": "Para establecer un ascenso después del despegue en una aeronave equipada con una hélice de velocidad constante, el rendimiento del motor se reduce a la potencia de ascenso disminuyendo la presión del colector y:", "o": ["Aumentando las RPM disminuyendo el ángulo de la pala de la hélice.", "Disminuyendo las RPM disminuyendo el ángulo de la pala de la hélice.", "Disminuyendo las RPM aumentando el ángulo de la pala de la hélice."], "a": 2, "e": "Un ajuste de paso bajo y altas RPM se utiliza para obtener la máxima potencia para el despegue. Luego, después de que el avión este en el aire, un aumento del paso o de cabeceo del avión generara unas RPM más bajas, lo que proporciona la potencia adecuada y una mejor economía mientras se mantiene la velocidad aérea adecuada. La respuesta (A) es incorrecta porque las RPM se reducen para reducir la potencia al aumentar el ángulo de la pala de la hélice. La respuesta (B) es incorrecta porque se debe aumentar el ángulo de la pala para disminuir las RPM."},
  {"id": 98, "s": 1, "q": "Durante el pre-vuelo en clima frio, las líneas de ventilación del cárter deben recibir atención especial porque son susceptibles de ser obstruidas por:", "o": ["Aceite congelado del cárter.", "Humedad del aire exterior que se ha congelado.", "Hielo de los vapores del cárter que se han condensado y posteriormente congelado."], "a": 2, "e": "El respiradero del cárter requiere una consideración especial cuando se prepara para el clima frío. Las líneas de ventilación congeladas pueden crear numerosos problemas. Cuando los vapores del cárter se enfrían, pueden condensarse en la línea de ventilación y posteriormente congelarse y cerrarla. Se recomienda un cuidado especial durante el pre vuelo para asegurarse de que el sistema de ventilación esté libre de hielo."},
  {"id": 99, "s": 1, "q": "Para desarrollar la máxima potencia y empuje una hélice de velocidad constante debe ajustarse a un ángulo de pala que produzca un:", "o": ["Gran ángulo de ataque y bajas revoluciones por minuto.", "Pequeño ángulo de ataque y altas revoluciones por minuto.", "Gran ángulo de ataque y altas revoluciones por minuto."], "a": 1, "e": "Un ángulo de ataque más pequeño hace que las palas tomen cantidades más pequeñas de aire, lo que a su vez permite que el motor funcione a mayores RPM, produciendo más potencia."},
  {"id": 100, "s": 1, "q": "Para el despegue, el ángulo de la pala de una hélice de paso variable debe establecerseen un:", "o": ["Pequeño ángulo de ataque y altas revoluciones por minuto.", "Gran ángulo de ataque y bajas revoluciones por minuto.", "Gran ángulo de ataque y altas revoluciones por minuto."], "a": 0, "e": "Un ángulo de ataque más pequeño hace que las palas tomen cantidades más pequeñas de aire, lo que a su vez permite que el motor funcione a mayores RPM, produciendo más potencia."},
  {"id": 101, "s": 1, "q": "¿Cuál es la verdad con respecto al precalentamiento de una aeronave durante las operaciones en clima frío?", "o": ["El área de la cabina y el motor deben precalentarse.", "El área de la cabina no debe precalentarse con calentadores portátiles.", "Se debe soplar aire caliente directamente al motor a través de las tomas de aire."], "a": 0, "e": "Las bajas temperaturas pueden provocar un cambio en la viscosidad de los aceites de motor, las baterías pueden perder un alto porcentaje de su eficacia y los instrumentos pueden atascarse. Debido a lo anterior, es deseable precalentar los motores y la cabina antes de arrancar a bajas temperaturas. Se debe tener mucho cuidado en el proceso de precalentamiento para evitar incendios."},
  {"id": 102, "s": 1, "q": "¿Qué se debe esperar al realizar un aterrizaje a favor del viento? La posibilidad de:", "o": ["Anticiparse al punto de aterrizaje previsto y una velocidad más alta en el aterrizaje.", "Sobrepasar el punto de aterrizaje previsto y una velocidad de tierra más alta en el momento de aterrizaje", "Anticiparse al punto de aterrizaje previsto y una velocidad de tierra más alta en el momento del aterrizaje."], "a": 1, "e": "En esta situación, el piloto debe apuntar al extremo cercano de la pista, debido a que el viento de cola aumenta la velocidad de tierra de la aeronave."},
  {"id": 103, "s": 2, "q": "¿Cuál es el símbolo correcto para la velocidad de pérdida o la velocidad mínima de vuelo estable en una configuración determinada?", "o": ["Vs.", "Vsi.", "Vso."], "a": 1, "e": "Vs1 es la velocidad de pérdida o la velocidad mínima de vuelo estable obtenida en una configuración determinada. La respuesta (A) es incorrecta porque Vs es la velocidad de pérdida o la velocidad mínima de vuelo a la que se puede controlar el avión. La respuesta (C) es incorrecta porque Vso es la velocidad de pérdida O la velocidad mínima de vuelo en la configuración de aterrizaje."},
  {"id": 104, "s": 2, "q": "¿Cuál es el símbolo correcto para la velocidad de pérdida o la velocidad mínima de vueloa la que se puede controlar el avión?", "o": ["Vs.", "Vs1", "Vso."], "a": 0, "e": "Vs es la velocidad de pérdida o la velocidad mínima de vuelo a la que se puede controlar el avión. La respuesta (B) es incorrecta porque Vs1 es la velocidad de pérdida o la velocidad mínima de vuelo obtenida en una configuración determinada. La respuesta (C) es incorrecta porque Vso es la velocidad de pérdida o la velocidad mínima de vuelo en configuración de aterrizaje."},
  {"id": 105, "s": 2, "q": "-Se define VF como:", "o": ["velocidad de diseño de los flaps.", "velocidad de operación de los flaps.", "velocidad máxima con flaps extendidos."], "a": 0, "e": "VF es la velocidad de diseño de los flaps. La respuesta (B) es incorrecta porque el rango de operación de los flaps está indicado por el arco blanco en el indicador de velocidad. La respuesta (C) es incorrecta porque VFE es la velocidad máxima con flaps extendidos."},
  {"id": 106, "s": 2, "q": "Se define Vuo como:", "o": ["velocidad máxima de crucero estructural.", "velocidad de operación normal.", "velocidad máxima de operación."], "a": 0, "e": "Vno significa velocidad máxima de crucero estructural."},
  {"id": 107, "s": 2, "q": "Se define VLE como:", "o": ["velocidad máxima con el tren de aterrizaje extendido.", "velocidad máxima para la operación del tren de aterrizaje.", "velocidad máxima con los flaps de borde de ataque extendidos."], "a": 0, "e": "VLE es la velocidad máxima con el tren de aterrizaje extendido. La respuesta (B) es incorrecta porque VLo es la velocidad máxima para la operación del tren de aterrizaje. La respuesta (C) es incorrecta porque la velocidad máxima con los flaps de borde de ataque extendidos no está definida."},
  {"id": 108, "s": 2, "q": "Se define VNE como:", "o": ["velocidad máxima para extender la rueda de nariz.", "velocidad de nunca exceder.", "velocidad máxima con el tren de aterrizaje extendido."], "a": 1, "e": "VNE es la velocidad de nunca exceder. La respuesta (A) es incorrecta porque esta velocidad no está definida. La respuesta (C) es incorrecta porque es VLE."},
  {"id": 109, "s": 2, "q": "Se define Vy como:", "o": ["velocidad para el mejor régimen de descenso.", "velocidad de mejor ángulo de ascenso.", "velocidad de mejor régimen de ascenso."], "a": 2, "e": "Vy es la velocidad de mejor régimen de ascenso. La respuesta (A) es incorrecta porque no está definida. La respuesta (B) es incorrecta porque es Vx."},
  {"id": 110, "s": 2, "q": "Los aviones más modernos tienen una velocidad de maniobra que generalmente se puede calcular de la siguiente manera:", "o": ["1.2 Vso0", "1.7 Vso.", "la mitad de la velocidad de pérdida."], "a": 1, "e": "La velocidad máxima a la que una aeronave puede llevarse a la pérdida aerodinámica de manera segura ahora se determina para todos los diseños modernos. Esta velocidad se denomina \"velocidad de maniobra\" (Va) y debe introducirse en el AFM / POH de todas las aeronaves modernas. Para aviones de aviación general más antiguos, esta velocidad es aproximadamente 1,7 veces la velocidad normal de pérdida. Por ejemplo, un avión más antiguo que normalmente entra en pérdida a 60 nudos no deberá llevarse a la pérdida a una velocidad por encima de 102 nudos (60 nudos x 1,7 = 102 nudos). Una aeronave con una velocidad de pérdida normal de 60 nudos llevada a la pérdida a una velocidad de 102 nudos experimenta un factor de carga igual al cuadrado del aumento de velocidad, o sea 2,89 Gs (1,7 x 1,7 = 2,89 Gs)."},
  {"id": 111, "s": 2, "q": "¿Qué ajuste de altímetro se requiere cuando se opera una aeronave a 18,000 pies sobre el nivel del mar?", "o": ["Ajuste actual del altímetro de una estación a lo largo de la ruta.", "29.92\" Hg.", "Ajuste del altímetro correspondiente al aeropuerto de salida o destino."], "a": 1, "e": "Cada persona que opere una aeronave deberá mantener la altitud de crucero o el nivel de vuelo de esa aeronave, según sea el caso, por referencia a un altímetro que esté ajustado, cuando opere a 18.000 pies MSL o más, en 29,92 \" Hg."},
  {"id": 112, "s": 2, "q": "¿Qué velocidad sería incapaz de identificar un piloto por el código de colores de un indicador de velocidad?", "o": ["La velocidad de nunca exceder.", "La velocidad de pérdida sin potencia.", "La velocidad de maniobra."], "a": 2, "e": "La velocidad de maniobra no está codificada por colores en los indicadores de velocidad. La respuesta (A) es incorrecta porque la velocidad de nunca exceder se identifica por la línea roja en el extremo superior del arco amarillo. La respuesta (B) es incorrecta porque la velocidad de pérdida sin potencia se identifica por el extremo inferior de velocidad del arco blanco para la configuración de aterrizaje [V (SO)] y el extremo inferior de velocidad del arco verde para la configuración limpia [V (S1)]."},
  {"id": 113, "s": 2, "q": "La relación entre la velocidad verdadera de un avión y la velocidad del sonido en las mismas condiciones atmosféricas es:", "o": ["velocidad equivalente.", "flujo de aire transónico", "número Mach"], "a": 2, "e": "El número Mach es la relación entre la velocidad verdadera y la velocidad del sonido."},
  {"id": 114, "s": 2, "q": "¿Cuál podría ser un resultado de exceder el número Mach crítico?", "o": ["Pérdida aerodinámica en la hélice.", "Reducción de la resistencia.", "Dificultades en el control de la aeronave."], "a": 2, "e": "El número Mach crítico es el límite entre el vuelo subsónico y transónico. Cuando se forman ondas de choque en la aeronave, puede ocurrir una separación del flujo de aire seguida de un buffet y dificultades de control de la aeronave. Las ondas de choque, el buffet y la separación del flujo de aire tienen lugar por encima del número Mach crítico."},
  {"id": 115, "s": 2, "q": "¿Qué enunciado es verdadero sobre la desviación magnética de una brújula? La desviación", "o": ["varía con el tiempo a medida que cambia la línea agónica.", "varía para diferentes rumbos de la misma aeronave.", "es la misma para todos los aviones que se encuentren en la misma posición."], "a": 1, "e": "La desviación depende, en parte, del rumbo del avión. La diferencia entre la dirección indicada por una brújula magnética que no está instalada en un avión y una que está instalada en un avión, es la desviación. La respuesta (A) es incorrecta porque la variación varía con el tiempo a medida que se desplaza la línea agónica. La respuesta (C) es incorrecta porque la desviación varía de un avión a otro."},
  {"id": 116, "s": 2, "q": "Nombra los cuatro fundamentos involucrados en maniobrar una aeronave.", "o": ["Potencia, cabeceo, alabeo y compensación.", "Empuje, sustentación, virajes y planeos.", "Vuelo recto y nivelado, virajes, ascensos y descensos."], "a": 2, "e": "Las maniobras del avión generalmente se dividen en cuatro aspectos fundamentales de vuelo: 1. Recto y nivelado 2. Virajes 3. Ascensos 4. Descensos"},
  {"id": 117, "s": 2, "q": "¿Cuál es la diferencia funcional entre el coordinador de virajes y el indicador de virajes y deslizamiento? El coordinador de virajes", "o": ["es siempre eléctrico; el indicador de virajes y deslizamiento funciona siempre con el sistema de vacío.", "indica únicamente el ángulo de alabeo; el indicador de virajes y deslizamiento indica régimen de virajes y la coordinación.", "indica el régimen de alabeo, el régimen de viraje y la coordinación; el indicador de viraje y deslizamiento indica el régimen de viraje y la coordinación."], "a": 2, "e": "El coordinador de virajes indica el régimen de alabeo, además del régimen de viraje y la coordinación. El indicador de virajes y deslizamiento solo indica el régimen de viraje y la coordinación. La respuesta (A) es incorrecta porque ambos instrumentos suelen ser accionados eléctricamente. La respuesta (B) es incorrecta porque un coordinador de virajes no indica el ángulo de alabeo."},
  {"id": 118, "s": 2, "q": "¿Cuál es la ventaja de un coordinador de virajes eléctrico si el avión tiene un sistema de vacío para otros instrumentos giroscópicos?", "o": ["Es un respaldo en caso de falla del sistema de vacío.", "Es más confiable que los indicadores accionados por bomba de vacío.", "No caerá al igual que los indicadores accionados por bomba de vacío."], "a": 0, "e": "Un coordinador de virajes eléctrico proporciona respaldo en caso de que falle el sistema de vacío. Las respuestas (B) y (C) son incorrectas porque tanto los indicadores accionados por bomba de vacío como los eléctricos son confiables y ambos pueden caer."},
  {"id": 119, "s": 2, "q": "Si se realiza un viraje estándar, ¿cuánto tiempo tomaría recorrer 360\"?", "o": ["1 minuto.", "2 minutos.", "3 minutos."], "a": 1, "e": "Un viraje estándar significa que la aeronave vira a un régimen de 3 * por segundo. 360 * dividido por 3° por segundo es igual a 120 segundos o 2 minutos."},
  {"id": 120, "s": 2, "q": "Un avión está ubicado en un aeropuerto con una elevación de 5,000 pies MSL y una temperatura de 90 grados F. El altímetro está ajustado para la altura del aeropuerto. Más tarde esa noche, la temperatura desciende a 50 grados F. menos que se cambie el ajuste del altímetro, se leerá", "o": ["4,800 pies", "5,000 pies", "5,200 pies"], "a": 2, "e": "Una disminución de la temperatura del aire aumentará su densidad y disminuirá la altitud de densidad de un aeropuerto determinado. Si el altímetro no se ajusta por el cambio de presión, este indicará una altitud superior a la elevación del campo."},
  {"id": 121, "s": 2, "q": "La velocidad calibrada se describe mejor como la velocidad indicada corregida por", "o": ["error de instalación y del instrumento.", "error del instrumento.", "temperatura no estándar."], "a": 0, "e": "La velocidad calibrada es la velocidad indicada corregida según la ubicación (o instalación) y los errores del instrumento."},
  {"id": 122, "s": 2, "q": "La velocidad verdadera se describe mejor como velocidad calibrada corregida por", "o": ["error de instalación o del instrumento.", "temperatura no estándar.", "altitud y temperatura no estándar."], "a": 2, "e": "La velocidad verdadera es la velocidad indicada después de que se ha corregido por temperatura no estándar y altitud de presión."},
  {"id": 123, "s": 2, "q": "¿Por qué deben evitarse velocidades de vuelo superiores a VNE?", "o": ["La resistencia inducida en exceso producirá una falla estructural.", "Los factores de carga límite de diseño pueden excederse si se encuentran ráfagas.", "La efectividad del control se ve tan afectada que la aeronave se vuelve incontrolable."], "a": 1, "e": "Cualquier velocidad por encima de VNE puede causar daños; por lo tanto, se debe evitar volar por encima de esta velocidad incluso con aire en calma. La respuesta (A) es incorrecta porque la resistencia inducida disminuye con el aumento de la velocidad. La respuesta (C) es incorrecta porque la efectividad del control aumenta con el aumento de la velocidad."},
  {"id": 124, "s": 2, "q": "Es más probable que ocurran daños o fallas estructurales con aire en calma a velocidades por encima de", "o": ["VNO.", "Va.", "VNE."], "a": 2, "e": "Cualquier velocidad por encima de VNE puede causar daños; por lo tanto, se debe evitar volar por encima de esta velocidad incluso con aire en calma."},
  {"id": 125, "s": 2, "q": "La velocidad máxima de crucero estructural es la velocidad máxima a la que se puede Operar un avión durante", "o": ["maniobras abruptas.", "operaciones normales.", "vuelo con aire en calma."], "a": 1, "e": "La velocidad máxima de crucero estructural (Vno) es una velocidad tal, que de excederse el factor de carga límite, se pueden producir deformaciones permanentes a la estructura de la aeronave. Esta es la velocidad máxima para la operación normal. La respuesta (A) es incorrecta porque la velocidad de maniobra (Va) es la velocidad máxima para maniobras abruptas. La respuesta (C) es incorrecta porque el arco amarillo identifica el rango donde solo se recomienda volar con aire en calma."},
  {"id": 126, "s": 2, "q": "Un piloto está entrando a un área donde se han reportado turbulencias de aire claro significativas. ¿Qué acción es la correcta al encontrar la primera onda?", "o": ["Mantener la altitud y la velocidad.", "Ajustar la velocidad a la recomendada para aire turbulento.", "Iniciar un ascenso o descenso suave a la velocidad de maniobra."], "a": 1, "e": "En un área donde se ha reportado o se ha pronosticado una turbulencia de aire claro (CAT)significativa, se sugiere que el piloto ajuste la velocidad para volar a la velocidad recomendada para aire turbulento al encontrar la primera onda, ya que la intensidad de dicha turbulencia puede aumentarrápidamente. La respuesta (A) es incorrecta porque la acción apropiada es ajustar la velocidad para la velocidad de maniobra (VA). La respuesta (C) es incorrecta porque la acción apropiada es ajustar la velocidad para la velocidad de maniobra (VA)."},
  {"id": 127, "s": 2, "q": "Si se encuentran turbulencias severas durante el vuelo, el piloto debe reducir la velocidad a:", "o": ["velocidad mínima de control.", "velocidad de maniobra.", "velocidad máxima de crucero estructural."], "a": 1, "e": "La velocidad de maniobra (V (A)) es la velocidad máxima a la cual la aeronave puede soportar el límite máximo de carga (ya sea por ráfaga o deflexión total de las superficies de control) sin causar daño estructural. La respuesta (A) es incorrecta porque en turbulencias, la velocidad mínima de control provocaría que el avión entrara en pérdida o problemas de control significativos. La respuesta (C) es incorrecta porque la velocidad máxima de crucero estructural es mayor a VA."},
  {"id": 128, "s": 2, "q": "Para determinar la altitud de presión antes del despegue, el altímetro debe ajustarse a:", "o": ["el ajuste actual del altímetro.", "29,92\" Hg y leer la altitud indicada en el altímetro.", "la elevación del campo y la indicación de presión en la ventanilla de ajuste del altímetro."], "a": 1, "e": "La altitud de presión se puede determinar ajustando el altímetro a 29,92\" Hg y leyendo la indicación del altímetro. Las respuestas (A) y (C) son incorrecta porque indicaría la elevación del campo o la altitud verdadera."},
  {"id": 129, "s": 2, "q": "¿Cuál es la mejor técnica para minimizar el factor de carga en el ala cuando se vuela en turbulencia severa?", "o": ["Cambiar los ajustes de potencia, según sea necesario, para mantener una velocidad constante.", "Controlar la velocidad con potencia, mantener las alas niveladas y aceptar cambios de altitud.", "Ajustar la potencia y compensar para obtener una velocidad igual o inferior a la velocidad de maniobra, mantener las alas niveladas y aceptar cambios de velocidad y altitud."], "a": 2, "e": "En turbulencia severa, ajuste la potencia y la compensación para obtener una velocidad igual o inferior a la velocidad de maniobra; esto ayuda a evitar exceder el factor máximo de carga de la aeronave. Intente mantener una actitud constante y acepte los cambios de velocidad y altitud causados por las ráfagas. Las respuestsa (A) y (B) son incorrectas porque no es posible mantener una velocidad constante en turbulencia severa."},
  {"id": 130, "s": 2, "q": "¿Qué se debe tener en cuenta al utilizar un GPS portátil para navegación VFR?", "o": ["La precisión de la posición puede degradarse sin notificación.", "La capacidad RAIM se mantendrá durante todo el vuelo.", "Los puntos de la ruta seguirán siendo precisos incluso si la base de datos no está actualizada."], "a": 0, "e": "Si bien un receptor GPS portátil puede proporcionar una excelente capacidad de navegación a los pilotos VFR, esté preparado para la pérdida intermitente de la señal de navegación, posiblemente sin recibir mensajes de advertencia RAIM."},
  {"id": 131, "s": 2, "q": "Está volando una aeronave equipada con una pantalla electrónica de vuelo (EFD) y la computadora de datos de aire (ADC) falla. ¿Qué instrumento se verá afectado?", "o": ["Capacidad ADS-B In", "Indicador de velocidad.", "Indicador de actitud."], "a": 1, "e": "Las entradas pitot-estáticas son recibidas por la computadora de datos de aire (ADC). Si el ADC falla, el indicador de velocidad se verá afectado."},
  {"id": 132, "s": 3, "q": "La reglamentación que se refiere a operar una aeronave se relaciona con la persona que:", "o": ["actúa como piloto al mando de la aeronave.", "es el único manipulador de los controles de la aeronave.", "hace que la aeronave sea utilizada o autoriza su uso."], "a": 2, "e": "“Operar”, con respecto a aeronaves, significa uso, causa para usar o autorizar el uso de aeronaves. La respuesta (A) es incorrecta porque el piloto al mando puede no ser necesariamente el operador de la aeronave. La respuesta (B) es incorrecta porque el único manipulador puede no ser necesariamente el operador de la aeronave."},
  {"id": 133, "s": 3, "q": "Los pilotos comerciales deben contar con una licencia vigente y apropiada en su posesión física o que sea de fácil acceso en la aeronave cuando:", "o": ["piloteen solo para alquiler.", "lleven pasajeros solamente.", "actúen como tripulación de vuelo."], "a": 2, "e": "Ninguna persona puede actuar como piloto al mando o en cualquier otra capacidad como miembro de la tripulación de vuelo de una aeronave civil a menos que cuente con la respectiva licencia y una certificación médica vigente que esté en su posesión o sea de fácil acceso en la aeronave. [LAR 61.015 (a)] Asimismo, en el LAR 91 se indica que el piloto al mando se asegurará de que cada miembro de la tripulación de vuelo esté en posesión y porte una licencia con sus habilitaciones y certificado médico aeronáutico válidos y apropiados a las funciones que haya de ejercer, expedida por el Estado de matrícula de la aeronave o expedida por otro Estado y convalidada por el Estado de matrícula. Igualmente, se indica que entre los documentos que deben llevarse a bordo de las aeronaves, están las licencias apropiadas de cada miembro de la tripulación. [LAR 91.1310 (a)(1), LAR 91.420 (a)(3)] Las respuestas (A) y B son incorrectas porque se requiere tener la licencia de piloto y la certificación médica apropiadas independientemente del tipo de operación."},
  {"id": 134, "s": 3, "q": "¿Un certificado médico emitido a un piloto comercial el 10 de abril de este año le permiteal piloto ejercer cuál de los siguientes privilegios, considerando que es menor de 40 años?", "o": ["Privilegios de piloto comercial hasta el 10 de abril del próximo año.", "Privilegios de piloto comercial hasta el 10 de abril, 2 años después.", "Privilegios de piloto privado hasta el 31 de marzo del próximo año, pero no después."], "a": 0, "e": "El certificado médico Clase 1 correspondiente a la licencia piloto comercial, tiene la vigencia de un año cuando el titular es menor de 40 años. Si bien el piloto comercial tiene entre sus atribuciones ejercer A funciones como piloto privado, éstas pueden realizarse siempre que cuente con el citado certificado vigente. [LAR 67.025 Párrafo (a) (1) del LAR 67]."},
  {"id": 135, "s": 3, "q": "¿Cuándo se requiere que el piloto al mando tenga una habilitación de categoría y clase apropiada para la aeronave que vuela?", "o": ["En todos los vuelos solo.", "En aeronaves certificadas para más de un piloto.", "En aeronaves certificadas para un solo piloto."], "a": 2, "e": "Ninguna persona puede actuar como piloto al mando o copiloto de una aeronave civil, a menos que dicha persona esté en posesión y porte una licencia de piloto válida y vigente con las habilitaciones correspondientes, expedida por el Estado de matrícula de la aeronave o expedida por otro Estado y convalidada por el de matrícula. Asimismo, el piloto requiere contar con una habilitación de categoría y clase cuando va a ejercer en aeronaves certificadas para un solo piloto. La respuesta A es incorrecta porque los vuelos solo se refieren a los que realiza un alumno piloto como parte de la experiencia para acceder a una licencia de piloto privado, lo cual no se considera como piloto al mando y la respuesta B es incorrecta porque para volar una aeronave certificada para más de un piloto se requiere contar con una habilitación de tipo. [LAR 61.305 Párrafos (a) y (d) (1)]."},
  {"id": 136, "s": 3, "q": "A menos que se autorice lo contrario, se requiere que el piloto al mando tenga una habilitación de tipo cuando opere cualquier:", "o": ["avión certificado para un solo piloto.", "helicóptero y aeronave de despegue vertical.", "aviones multimotores con menos de 5,700 kg de peso máximo certificado al despegue."], "a": 1, "e": "Una persona no puede actuar como piloto al mando de ninguna de las siguientes aeronaves a menos que tenga una habilitación de tipo para esa aeronave: 1. Aeronaves certificadas para volar con una tripulación mínima de dos pilotos. 2. Aviones turbopropulsados. 3. Todos los helicópteros y aeronaves de despegue vertical. 4. Cualquier tipo de aeronave siempre que lo considere oportuno la AAC. [LAR 61.305 (d)(3)]"},
  {"id": 137, "s": 3, "q": "¿Cuál de las siguientes denominaciones son consideradas como habilitación de clase de aeronave?", "o": ["Transporte, normal, utilitario, acrobático.", "Avión, aeronave a rotor, planeador, aeronave más liviana que el aire.", "Monomotor terrestre, multimotor terrestre, hidroavión monomotor, hidroavión multimotor"], "a": 2, "e": "Las habilitaciones de clase conforme al LAR corresponden a la categoría avión y tienen cuatro clases que se describen en la Respuesta C que es la correcta. [LAR 61.305 (d)(2)]. 2."},
  {"id": 138, "s": 3, "q": "¿Qué tiempo de vuelo puede registrar el piloto en la función de copiloto?", "o": ["Todo el tiempo de vuelo actuando como copiloto en aeronaves certificadas para más de un piloto.", "Todo el tiempo de vuelo mientras esté desempeñándose como tal en una aeronave que, de acuerdo a su certificado tipo o requisitos operacionales, requiera más de un piloto.", "Solo el tiempo de vuelo durante el cual el copiloto es el único manipulador de los controles."], "a": 1, "e": "La respuesta A está incompleta porque puede registrar las horas de vuelo realizadas como copiloto en una aeronave que por certificado tipo requiera esta función o cuando las realice por requisitos operacionales establecidos por la AAC. La respuesta C no es correcta al no estar exigida esa condición en el reglamento. [LAR 61.120 (c)(3)]."},
  {"id": 139, "s": 3, "q": "Antes de transportar pasajeros en vuelo nocturno, el piloto al mando debe haberrealizado los despegues y aterrizajes requeridos en:", "o": ["cualquier tipo de aeronave.", "la misma categoría y clase de aeronave que se utilizará.", "la misma categoría, clase y tipo de aeronave (si se requiere una habilitación de tipo)."], "a": 2, "e": "Ninguna persona puede actuar como piloto al mando de una aeronave que transporta pasajeros durante el período nocturno, a menos que dentro de los 90 días anteriores haya realizado al menos tres despegues y tres aterrizajes hasta la completa detención, en la misma categoría, clase y tipo (si se requiere una habilitación de tipo) de la aeronave que se utilizará. [LAR 61.140 (b)]"},
  {"id": 140, "s": 3, "q": "Ningún piloto puede actuar como piloto al mando de una aeronave bajo IFR o en condiciones meteorológicas inferiores a los mínimos prescritos para VFR a menos que ese piloto, en los últimos 6 meses, haya realizado y registrado en condiciones reales o simuladas de instrumentos, al menos:", "o": ["seis (6) horas de vuelo por instrumentos en condiciones IFR reales o simuladas; tres (3) de las cuales hayan sido efectuadas en la categoría de la aeronave involucrada, incluyendo por lo menos seis (6) aproximaciones instrumentales o realizado una verificación de competencia en la categoría de aeronave involucrada.", "tres aproximaciones de instrumentos y 3 horas registradas de instrumentos.", "seis vuelos por instrumentos y seis aproximaciones."], "a": 0, "e": "Para actuar como piloto al mando bajo IFR, las respuestas B y C no están acordes con lo establecido en la normativa vigente [LAR 61.140 (c) (1)]."},
  {"id": 141, "s": 3, "q": "Para actuar como piloto al mando de una aeronave que requiera más de un piloto bajo el LAR 91, un piloto comercial debe haber completado satisfactoriamente un chequeo de vueloo completado una verificación de competencia dentro de los:", "o": ["6 meses calendario anteriores.", "12 meses calendario anteriores.", "24 meses calendario anteriores."], "a": 0, "e": "Ninguna persona puede actuar como piloto al mando de una aeronave certificada para más de un piloto, a menos que, dentro de los 6 meses calendario anteriores, haya completado un chequeo de vuelo, haya completado una verificación de competencia del piloto o haya completado una o más fases de un programa de verificación de competencia aprobado por la AAC. (LAR 61.145)."},
  {"id": 142, "s": 3, "q": "¿Cuál de las siguientes afirmaciones no es correcta, en cuanto a las responsabilidades del piloto al mando conforme al LAR 91?", "o": ["Notificar a la autoridad correspondiente más próxima, por el medio más rápido, cualquier accidente en relación con la aeronave, en el cual alguna persona resulte muerta o con lesiones graves o se causen daños de importancia a la aeronave o a la propiedad.", "Garantizar la protección de la aeronave siempre que en la operación manipule los mandos.", "Cumplir las reglas de vuelo, excepto en circunstancias que sean absolutamente necesario por razones de seguridad"], "a": 1, "e": "La respuesta B es la opción no correcta, porque el piloto al mando en todos los casos, manipule o no los mandos, es responsable de la operación, seguridad operacional y protección de la aeronave, así como de la seguridad de todos los miembros de la tripulación, los pasajeros y la carga que se encuentre abordo, entre otras responsabilidades (LAR 91.120)."},
  {"id": 143, "s": 3, "q": "Al operar una aeronave civil registrada en el Estado ¿Qué documento debe estar disponible en la aeronave?", "o": ["Un manual de operaciones del fabricante.", "Un manual de vuelo aprobado de la aeronave", "Un manual del propietario."], "a": 1, "e": "El manual de vuelo u otros documentos o información relacionados con toda limitación de utilización prescrita para la aeronave por la autoridad encargada de la certificación del Estado de matrícula, debe ser llevado a bordo de la aeronave. (LAR 91.1405)"},
  {"id": 144, "s": 3, "q": "¿Cuándo se requieren medidas previas al vuelo, en relación con las alternativas disponibles, si el vuelo planificado no se puede completar?", "o": ["Solo vuelos IFR.", "Cualquier vuelo que no se encuentre en las inmediaciones de un aeródromo y para todos los vuelos IFR.", "Cualquier vuelo realizado por remuneración o arrendamiento."], "a": 1, "e": "Para un vuelo bajo IFR o un vuelo que no se encuentre en las inmediaciones de un aeródromo, el piloto debe estar familiarizado con los informes y pronósticos meteorológicos, los requisitos de combustible, las alternativas disponibles si el vuelo planificado no se puede completar. (LAR 91.125)."},
  {"id": 145, "s": 3, "q": "Las medidas previas al vuelo relativas a los informes meteorológicos y los requisitosde combustible son aplicables a:", "o": ["cualquier vuelo realizado por remuneración o arrendamiento", "cualquier vuelo que no se encuentre en las inmediaciones de un aeródromo y para todos los vuelos IFR.", "solo vuelos IFR."], "a": 1, "e": "Antes de comenzar un vuelo en IFR o un vuelo que no se encuentre en las inmediaciones de un aeródromo, cada piloto al mando se familiarizará con toda la información disponible sobre ese vuelo, incluidos los informes y pronósticos meteorológicos, los requisitos de combustible, las alternativas disponibles si el vuelo planificado no se puede completar (LAR 91.125)."},
  {"id": 146, "s": 3, "q": "Usted es piloto al mando de un vuelo VFR que cree estará dentro del rango de combustible de su aeronave. Como parte de su planificación previa al vuelo, debe:", "o": ["estar familiarizado con todas las aproximaciones por instrumentos en el aeropuerto de destino.", "incluir un aeropuerto alternativo en el plan de vuelo y confirmar el desempeño adecuado de despegue y aterrizaje en el aeropuerto de destino.", "obtener informes meteorológicos, pronósticos y cumplir requisitos de combustible para el vuelo."], "a": 2, "e": "Antes de comenzar un vuelo en IFR o un vuelo que no se encuentre en las inmediaciones de un aeródromo, cada piloto al mando se familiarizará con toda la información disponible sobre ese vuelo, incluidos los informes y pronósticos meteorológicos, los requisitos de combustible, las alternativas disponibles si el vuelo planificado no se puede completar (LAR 91.125)."},
  {"id": 147, "s": 3, "q": "Antes de comenzar cualquier vuelo bajo IFR, el piloto al mando debe familiarizarse con toda la información disponible sobre ese vuelo. Además, el piloto debe:", "o": ["estar familiarizado con todas las aproximaciones por instrumentos en el aeropuerto de destino.", "incluir un aeropuerto alternativo en el plan de vuelo y confirmar el desempeño adecuado de despegue y aterrizaje en el aeropuerto de destino.", "estar familiarizado con las longitudes de las pistas en los aeropuertos de uso previsto, los informes meteorológicos, los requisitos de combustible, las alternativas disponibles si el vuelo no se puede completar."], "a": 2, "e": "Para un vuelo bajo IFR o un vuelo que no se encuentre en las inmediaciones de un aeródromo, el piloto debe estar familiarizado con los informes y pronósticos meteorológicos, los requisitos de combustible, las alternativas disponibles si el vuelo planificado no se puede completar. (LAR 91.125)."},
  {"id": 148, "s": 3, "q": "¿Cuál de los siguientes son algunos de los documentos necesarios a bordo de la aeronave durante un vuelo VFR?", "o": ["Comprobante de pago de seguro, itinerario de vuelo y libro de vuelo de la aeronave.", "Cuadro (s) de sección (s) VFR para el área en la que ocurre el vuelo, libro de registro de la aeronave y libro de registro del motor.", "Certificado de aeronavegabilidad, manual de vuelo aprobado del avión y certificado de registro (matrícula) de la aeronave."], "a": 2, "e": "En cada aeronave deberán llevarse a bordo los siguientes documentos: (1) certificado de matrícula. (2) certificado de aeronavegabilidad. (3) las licencias apropiadas para cada miembro de la tripulación. (4) el libro de a bordo (libro de vuelo), como se describe en la sección 91.1410. (5) si está provista de equipos de radio, la licencia de la estación de radio de la aeronave. (6) si lleva pasajeros, una lista de sus nombres, lugares de embarque y destino. (7) si transporta carga, un manifiesto y declaraciones detalladas de la carga. (8) documento que acredite la homologación por concepto de ruido, si es aplicable. (9) cartas actualizadas para la ruta del vuelo propuesto y para todas las rutas por las que posiblemente pudiera desviarse el vuelo. (10) los procedimientos a seguir por parte de los pilotos al mando de aeronaves interceptadas y las señales visuales para uso de las aeronaves, tanto interceptoras como interceptadas. (11) las señales visuales para uso de las aeronaves, tanto interceptoras como interceptadas; (12) cualquier aprobación específica emitida por el Estado de matrícula, si corresponde, para la operación u operaciones que se realicen; y (13) para aeronaves que operen bajo un acuerdo en virtud del Artículo 83 bis concertado entre el Estado de matrícula y el Estado del establecimiento principal del explotador, una copia auténtica certificada del resumen del acuerdo. (LAR 91.420) Asimismo, el manual de vuelo u otros documentos o información relacionados con toda limitación de utilización prescrita para la aeronave por la autoridad encargada de la certificación del Estado de matrícula y requeridos para la aplicación del Capítulo E del LAR 91, debe ser llevado a bordo de la aeronave. (LAR 91.405)."},
  {"id": 149, "s": 3, "q": "Los cinturones de seguridad de los miembros de la tripulación de vuelo requeridos deben estar abrochados:", "o": ["Solo durante el despegue y el aterrizaje.", "Mientras los miembros de la tripulación están en sus puestos.", "Solo durante el despegue y el aterrizaje cuando hay pasajeros a bordo del avión."], "a": 1, "e": "Todos los miembros de la tripulación de vuelo mantendrán abrochados sus cinturones de seguridad mientras estén en sus puestos. (LAR 91.570)."},
  {"id": 150, "s": 3, "q": "Se requiere que cada miembro de la tripulación de vuelo mantenga su arnés de hombro abrochado:", "o": ["Durante el despegue y el aterrizaje solo cuando haya pasajeros a bordo de la aeronave.", "Mientras se encuentra en su puesto, a menos que no pueda realizar las tareas requeridas.", "Durante el despegue y el aterrizaje, a menos que no pueda realizar las tareas requeridas."], "a": 2, "e": "Cuando se dispone de arneses de seguridad, cualquier miembro de la tripulación de vuelo que ocupe un asiento de piloto mantendrá abrochado el arnés de seguridad durante las fases de despegue y aterrizaje. (LAR 91.570)."},
  {"id": 151, "s": 3, "q": "Durante la verificación previa, usted descubre que uno de los asientos del pasajero tiene un arnés de hombro defectuoso. Todos los asientos están ocupados. Este vuelo es:", "o": ["Permitido.", "No permitido.", "Permitido siempre que se notifique al pasajero sobre el arnés de hombro defectuoso."], "a": 1, "e": "Ningún piloto puede hacer que se mueva en la superficie, despegue o aterrice una aeronave civil a menos que el PIC de esa aeronave se asegure de que cada persona a bordo haya sido notificada para abrocharse el cinturón de seguridad y, si está instalado, su arnés de hombro. (LAR 91.555)"},
  {"id": 152, "s": 3, "q": "Si uno de sus pasajeros afirma que prefiere no usar su arnés de hombro porque le resulta incómodo, ¿qué debería hacer usted?", "o": ["Explicar que es un requisito obligatorio y que se usa el arnés de hombro durante el despegue, aterrizaje y movimiento en la superficie.", "Permitirle usar el cinturón de seguridad durante todo el viaje sin el arnés de hombro.", "Permitirle usar su cinturón de seguridad para despegar y aterrizar y el arnés de hombro mientras está en ruta."], "a": 0, "e": "Si está instalado, se debe usar un arnés de hombro durante el movimiento en la superficie, el despegue y el aterrizaje. (LAR 91.555)"},
  {"id": 153, "s": 3, "q": "El uso de cinturones de seguridad es requerido durante el movimiento en la superficie, despegues y aterrizajes para:", "o": ["práctica de operación segura, pero no requerida por la reglamentación.", "cada persona mayor de 2 años a bordo.", "operaciones comerciales de pasajeros solamente."], "a": 1, "e": "Ningún piloto puede hacer que se mueva en la superficie, despegue o aterrice una aeronave a menos que el piloto al mando de esa aeronave se asegure de que cada persona a bordo haya sido notificada para abrocharse el cinturón de seguridad y, si está instalado, su arnés de hombro. Una persona que no ha cumplido dos años puede ser retenida por un adulto. (LAR 91.555)."},
  {"id": 154, "s": 3, "q": "Los dispositivos electrónicos portátiles que puedan causar interferencia con el sistemade navegación o comunicación no se pueden operar en una aeronave civil:", "o": ["en cualquier porción del espacio aéreo nacional.", "dentro del Estado.", "en las operaciones de transporte aéreo."], "a": 2, "e": "Los dispositivos electrónicos portátiles no pueden ser operados en aeronaves operadas por un titular de un certificado de operación de explotador de servicios aéreos. El piloto al mando no permitirá la operación de cualquier dispositivo electrónico portátil en ninguna aeronave civil, excepto grabadoras de voz, dispositivos de corrección auditiva, marcapasos, afeitadoras, entre otros. La respuesta (A) es incorrecta porque esta regla se aplica únicamente a vuelos comerciales e IFR. La respuesta (B) es incorrecta porque esta regla se aplica solo a vuelos comerciales e IFR. (LAR 91.025)"},
  {"id": 155, "s": 3, "q": "Los dispositivos electrónicos portátiles que puedan causar interferencia con el sistemade navegación o comunicación no se pueden operar en aeronaves civiles registradas en el Estado:", "o": ["Bajo vuelos IFR.", "En operaciones especiales.", "En cualquier porción del espacio aéreo nacional."], "a": 0, "e": "Cualquier dispositivo electrónico portátil que el operador de la aeronave haya determinado que podría causar interferencia con los sistemas de navegación o comunicación no puede usarse en ninguna aeronave operada bajo IFR. (LAR 91.025)."},
  {"id": 156, "s": 3, "q": "¿Cuáles son los requisitos de oxígeno cuando se opera en altitudes de presión de cabina superiores a los 13.000 pies MSL?", "o": ["Debe haber oxígeno disponible para la tripulación de vuelo.", "No se requiere oxígeno a ninguna altitud en un globo.", "La tripulación de vuelo y los pasajeros deben recibir oxígeno suplementario."], "a": 2, "e": "(b) Provisión de oxígeno: (1) No deberán iniciarse vuelos cuando se tenga que volar en altitudes de presión de cabina por encima de 10 000 pies, a menos que se lleve una provisión suficiente de oxígeno respirable para suministrarlo: (i) a todos los miembros de la tripulación y por lo menos al 10% de los pasajeros durante todo período de tiempo que exceda de 30 minutos, en que la altitud de presión de cabina en los compartimientos que ocupan se mantenga entre 10 000 pies y 13 000 pies; y (ii) a todos los miembros de la tripulación y a todos los pasajeros durante todo período de tiempo en que la altitud de presión de cabina sea superior a los 13 000 pies. (2) No deberán iniciarse vuelos de aviones presurizados o helicópteros con cabina a presión a menos que lleven suficiente cantidad almacenada de oxígeno respirable para todos los miembros de la tripulación y pasajeros y apropiada a las circunstancias del vuelo que se realice, en caso de pérdida de la presión y durante todo el período de tiempo en que la altitud de presión de cabina en cualquier compartimiento que ocupen sea superior a 10 000 pies. Además, cuando se opere una aeronave a altitudes de vuelo por encima de 25 000 pies, o a altitudes de vuelo menores de 25 000 pies y no pueda descender de manera segura en cuatro (4) minutos a una altitud de vuelo igual a 13 000 pies, la provisión de oxígeno no deberá ser inferior a 10 minutos para los ocupantes del compartimiento de pasajeros. (c) Uso de oxígeno: (1) Todos los miembros de la tripulación que cumplan funciones esenciales para la operación segura de la aeronave en vuelo, deberán utilizar continuamente oxígeno respirable siempre que prevalezcan las circunstancias por las cuales se haya considerado necesario su suministro, según los Párrafos (b) (1) o (b) (2). (2) Todos los miembros de la tripulación de vuelo de aeronaves presurizadas que vuelen a una altitud de vuelo mayor a 25 000 pies, deberán tener a su disposición, en el puesto en que prestan servicio de vuelo, una máscara del tipo de colocación rápida, en condiciones de suministrar oxígeno a voluntad. La respuesta (A) es incorrecta porque la tripulación de vuelo debe usar oxígeno por encima de los 13.000 pies MSL. La respuesta (B) es incorrecta porque los requisitos de oxígeno se aplican a todas las aeronaves. (LAR 91.590, Apéndice D LAR 61)."},
  {"id": 157, "s": 3, "q": "¿Cuál es el equipo necesario para las aeronaves propulsadas durante los vuelos nocturnos VFR?", "o": ["Sistema de luces anticolisión.", "Indicador de dirección giroscópico.", "Indicador giroscópico de inclinación."], "a": 0, "e": "Se requiere un sistema de luces anticolisión aprobado para volar bajo VFR entre la puesta y la salida del sol. La respuesta (B) es incorrecta porque se requiere un indicador de dirección giroscópico y un indicador de inclinación giroscópico para vuelos IFR. La respuesta (C) es incorrecta porque se requiere un indicador de dirección giroscópico y un indicador de giroscópico para vuelos IFR (LAR 91.190)"},
  {"id": 158, "s": 3, "q": "¿Cuál es el equipo necesario que requieren las aeronaves propulsadas durante los vuelos nocturnos VFR?", "o": ["Linterna con lente roja.", "Una luz de aterrizaje eléctrica.", "Altímetro sensible ajustable para presión barométrica."], "a": 1, "e": "Se requiere una luz de aterrizaje eléctrica solo si el vuelo nocturno es de alquiler. La respuesta (A) es incorrecta porque no hay requisitos específicos para las linternas y el color de la lente. La respuesta (C) es incorrecta porque solo se requieren altímetros sensibles para vuelos IFR. [LAR 91.815 (f)]"},
  {"id": 159, "s": 3, "q": "Se requiere equipo de flotación individual aprobado, fácilmente disponible para cada ocupante, en cada aeronave si se vuela sobre el agua:", "o": ["En aeronaves hidroavión a más de 50 NM de la costa.", "Más allá de la distancia de planeo desde la costa.", "A más de 50 millas terrestres de la costa."], "a": 1, "e": "Se requiere equipo de flotación individual aprobado y disponible para cada ocupante en cada aeronave si se vuela sobre el agua más allá de la distancia de planeo desde la costa. 'Orilla' se define como el área de la tierra adyacente al agua que está por encima del nivel del agua, excluidas las áreas terrestres que están intermitentemente bajo el agua. (LAR 91.820)"},
  {"id": 160, "s": 3, "q": "¿Cuál es la afirmación correcta respecto a las limitaciones operativas de un avión de categoría “restringida”?", "o": ["Se requiere que un piloto de un avión de categoría restringida posea una licencia de piloto comercial.", "Un avión de categoría restringida está limitado a un radio de operación de 25 millas desde su base de operaciones.", "Ninguna persona puede operar un avión de categoría restringida que transporte pasajeros o propiedades por remuneración o arrendamiento."], "a": 2, "e": "Una aeronave de categoría restringida no transportará personas o propiedades por remuneración o arrendamiento. (LAR 91.435)."},
  {"id": 161, "s": 3, "q": "¿Cuál es la afirmación correcta respecto a las limitaciones operativas de un avión de categoría 'primaria'?", "o": ["Un avión de categoría 'primaria' está limitado a un radio operativo específico desde su base de operaciones.", "Ninguna persona puede operar un avión de categoría 'primaria' que transporte pasajeros o propiedad por remuneración o arrendamiento.", "Un piloto de un avión de categoría 'primaria' debe tener una licencia de piloto comercial cuando transporta pasajeros por remuneración o arrendamiento."], "a": 1, "e": "Una aeronave de categoría restringida no transportará personas o propiedades por remuneración o arrendamiento. (LAR 91.455)"},
  {"id": 162, "s": 3, "q": "Las limitaciones operativas de una aeronave se pueden encontrar en el:", "o": ["Manual de vuelo de la aeronave aprobado por la AAC.", "Manual del propietario publicado por el fabricante de la aeronave.", "Manual de vuelo de la aeronave aprobado, marcas, listas y placas o cualquier combinación de los mismos."], "a": 2, "e": "El piloto al mando de un avión deberá, antes de iniciar un vuelo, estar familiarizado con: (1) El manual de vuelo del avión o el documento equivalente. (2) Con cualquier placa, lista, marca de instrumento o cualquiera combinación de ellos que contenga las limitaciones de operación prescritas por el Estado de diseño o de fabricación para cada avión del explotador. [LAR 91.1945 (a)]"},
  {"id": 163, "s": 3, "q": "El transporte de pasajeros:", "o": ["no está autorizado en una aeronave de categoría \"utilitaria\".", "no está autorizado en una aeronave de categoría \"limitada\".", "está autorizado en aeronaves de categoría 'restringida'."], "a": 1, "e": "Las operaciones por compensación o alquiler no están autorizadas en aeronaves de categoría limitada, aeronaves experimentales y aeronaves de categoría restringida. Se autorizan las operaciones que utilicen aeronaves de categoría utilitaria (como Cessna 152). La respuesta (A) es incorrecta porque el transporte de pasajeros por contrato está permitido en aeronaves de categoría normal y utilitaria. La respuesta (C) es incorrecta porque el transporte de pasajeros por contrato no está permitido en aeronaves de categoría restringida. Ninguna aeronave de categoría limitada será operada para el transporte de personas o propiedades con fines comerciales. (LAR 91.440)"},
  {"id": 164, "s": 3, "q": "El tiempo acumulado máximo que se puede operar un transmisor localizador de emergencia antes de que se deba recargar la batería recargable es:", "o": ["30 minutos.", "45 minutos.", "60 minutos."], "a": 2, "e": "Las baterías del ELT deben reemplazarse o recargarse cuando el transmisor ha estado en uso durante más de una hora acumulativa. [LAR 121,970 (f) (1)]."},
  {"id": 165, "s": 3, "q": "Mientras está en vuelo, un helicóptero y un avión convergen en un ángulo de 90°, y el helicóptero está ubicado a la derecha del avión. ¿Qué aeronave tiene el derecho de paso y por qué?", "o": ["El helicóptero, porque está a la derecha del avión.", "El helicóptero, porque los helicópteros tienen preferencia sobre los aviones.", "El avión, porque los aviones tienen preferencia sobre los helicópteros."], "a": 0, "e": "Cuando las aeronaves de la misma categoría convergen aproximadamente a la misma altitud (excepto de frente, o casi), la aeronave a la derecha de la otra tiene el derecho de paso. Las aeronaves de ala fija y las aeronaves de alas giratorias se consideran igualmente maniobrables, por lo que ninguna de las dos tiene preferencia sobre la otra. (LAR 91.185)."},
  {"id": 166, "s": 3, "q": "Dos aeronaves de la misma categoría se acercan a un aeropuerto con el propósito de aterrizar. El derecho de paso pertenece a la aeronave:", "o": ["a mayor altitud.", "a menor altitud, pero el piloto no se beneficiará de esta regla para cortar al frente o adelantar a la otra aeronave.", "que es más maniobrable, y que la aeronave puede, con precaución, adelantarse o adelantar a la otra aeronave."], "a": 1, "e": "Cuando dos o más aeronaves se acercan a un aeropuerto con el propósito de aterrizar, la aeronave inferior tiene el derecho de paso. Sin embargo, un piloto no se aprovechará de esta regla para adelantar o cortar frente a otra aeronave que se encuentre en la aproximación final a tierra. (LAR 91.185)."},
  {"id": 167, "s": 3, "q": "El avión A está adelantando al avión B. ¿Qué avión tiene el derecho de paso?", "o": ["Avión A; el piloto debe cambiar de rumbo a la derecha para adelantar.", "Avión B; el piloto debe esperar que lo rebasen por la derecha.", "Avión Bi; el piloto debe esperar que lo rebasen por la izquierda."], "a": 1, "e": "Cada aeronave que está siendo alcanzada tiene el derecho de paso y cada piloto de una aeronave que está adelantando deberá cambiar de rumbo a la derecha para rebasar bien. (LAR 91.185)"},
  {"id": 168, "s": 3, "q": "Un avión adelanta a un helicóptero. ¿Qué aeronave tiene el derecho de paso?", "o": ["Helicóptero; el piloto debe esperar que lo rebasen por la derecha.", "Avión; el piloto del avión debe cambiar de rumbo hacia la izquierda para adelantar.", "Helicóptero; el piloto debe esperar que lo rebasen por la izquierda."], "a": 0, "e": "Cuando las condiciones meteorológicas lo permitan, independientemente de que la operación se lleve acabo según las reglas de vuelo por instrumentos o las reglas de vuelo visual, cada persona que opere una aeronave mantendrá la vigilancia para ver y evitar otras aeronaves. Cada aeronave que está siendo alcanzada tiene el derecho de paso y cada piloto de una aeronave que está adelantando deberá cambiar de rumbo hacia la derecha para rebasar bien. (LAR 91.185)."},
  {"id": 169, "s": 3, "q": "Durante una operación nocturna, el piloto de la aeronave N.º 1 solo ve la luz verde de la aeronave N.º 2. Si las aeronaves están convergiendo, ¿qué piloto tiene el derecho de paso? El piloto de la aeronave:", "o": ["N.º 2; la aeronave N.º 2 está a la izquierda de la aeronave N.º 1.", "N.º 2; la aeronave N.º 2 está a la derecha de la aeronave N.º 1.", "N.º 1; la aeronave N.º 1 está a la derecha de la aeronave N.º 2."], "a": 2, "e": "Cuando las aeronaves de la misma categoría convergen aproximadamente a la misma altitud (excepto de frente, o casi), la aeronave a la derecha de la otra tiene el derecho de paso. La luz verde indica que la aeronave N.º 1 está mirando hacia el ala derecha de la aeronave N.º 2, lo que significa que la aeronave N.º 1 está a la derecha de la aeronave N.º 2. (LAR 91.185)."},
  {"id": 170, "s": 3, "q": "Un piloto que vuela un avión monomotor observa un avión multimotor acercándose porla izquierda. ¿Qué piloto debería ceder el paso?", "o": ["El piloto del avión multimotor debería ceder; el avión monomotor está a su derecha.", "El piloto del avión monomotor debe ceder el paso; el otro avión está a la izquierda.", "Cada piloto debe cambiar de rumbo hacia la derecha."], "a": 0, "e": "Cuando las aeronaves de la misma categoría convergen aproximadamente a la misma altitud (excepto de frente, o casi), la aeronave a la derecha de la otra tiene el derecho de paso. (LAR 91.185)."},
  {"id": 171, "s": 3, "q": "Un avión converge con un helicóptero. ¿Qué aeronave tiene el derecho de paso?", "o": ["El avión de la izquierda.", "El avión de la derecha.", "El más rápido de los dos aviones."], "a": 1, "e": "Si un avión de la misma categoría (o un avión y un helicóptero) están convergiendo, el avión a la derecha del otro tiene el derecho de paso. (LAR 91.185)."},
  {"id": 172, "s": 3, "q": "Si no está equipado con las luces de navegación requeridas, una aeronave debe terminar el vuelo:", "o": ["al atardecer.", "30 minutos después de la puesta del sol.", "1 hora después de la puesta del sol."], "a": 0, "e": "Ninguna persona, durante el período comprendido entre el atardecer y el amanecer, puede operar una aeronave a menos que cuente con luces de navegación. [LAR 91.190(a)(1)(ii); 91.835]."},
  {"id": 173, "s": 3, "q": "Si una aeronave no está equipada con un sistema de luces anticolisión, ninguna persona puede operar esa aeronave:", "o": ["después del atardecer hasta el amanecer.", "después del anochecer.", "1 hora después de la puesta del sol"], "a": 0, "e": "Durante el período comprendido entre el atardecer y el amanecer, ninguna persona puede operar una aeronave a menos que tenga luces anticolisión encendidas. Sin embargo, las luces anticolisión no necesitan estar encendidas cuando el piloto al mando determina que, debido a las condiciones de operación, sería de interés para la seguridad apagar las luces. [LAR 91.190(a)(1)(i); 91.835(a)]."},
  {"id": 174, "s": 3, "q": "¿Quién es el principal responsable de mantener una aeronave en condiciones de aeronavegabilidad?", "o": ["El mecánico principal responsable de esa aeronave.", "El piloto al mando u operador.", "El propietario o el explotador de la aeronave."], "a": 2, "e": "El propietario o el explotador de una aeronave es el principal responsable de mantener esa aeronave en condiciones de aeronavegabilidad, incluido el cumplimiento de las directivas de aeronavegabilidad. La respuesta (A) es incorrecta porque los mecánicos trabajan bajo el asesoramiento del propietario / explotador. La respuesta (B) es incorrecta porque el piloto solo es responsable de determinar la aeronavegabilidad antes del vuelo. (LAR 91.1105)."},
  {"id": 175, "s": 3, "q": "Después de que se haya completado una inspección anual y la aeronave se haya vueltoa poner en servicio, se debe realizar una anotación adecuada:", "o": ["en el certificado de aeronavegabilidad.", "en los registros de mantenimiento de la aeronave.", "en el manual de vuelo aprobado por la AAC."], "a": 1, "e": "Cada propietario o el explotador de una aeronave deberá hacer que la aeronave sea inspeccionada según lo prescrito por los reglamentos y, entre las inspecciones requeridas, se repararán las discrepancias según lo prescrito en el LAR 43. Además, cada propietario o el explotador deberá asegurarse de que el personal de mantenimiento realice las entradas apropiadas en los registros de mantenimiento de la aeronave que indiquen que la aeronave ha sido aprobada para volver al servicio. (LAR 91.1115; RAC 43)."},
  {"id": 176, "s": 3, "q": "¿Qué regulaciones existen en los términos y condiciones de un certificado de aeronavegabilidad estándar?", "o": ["LAR 21, 31, 43 y 91.", "LAR 21, 61 y 91.", "LAR 21, 43 y 91."], "a": 2, "e": "Se emite un certificado de aeronavegabilidad estándar para el tipo de aeronave certificada en las categorías normal, utilitaria, acrobática, regional, transporte y globos libres tripulados. El certificado de aeronavegabilidad tendrá vigencia indefinida si la aeronave se mantiene de acuerdo con las normas LAR 21, 43 y 91, y la aeronave está inscrita en el Registro Aeronáutico Nacional. (LAR 21, 43 y 91)"},
  {"id": 177, "s": 3, "q": "Si la operación de una aeronave en vuelo ha sido afectada sustancialmente por una alteración o reparación, los documentos de la aeronave deben demostrar que ésta ha sido objeto de un vuelo de comprobación y cuenta con la aprobación para retornar al servicio por parte de un piloto con la calificación adecuada antes de ser operada:", "o": ["bajo las reglas VFR o IFR.", "con pasajeros a bordo.", "Por remuneración o arrendamiento."], "a": 1, "e": "Ninguna persona puede llevar a otra persona (es decir, pasajeros) que no sean miembros de la tripulación en una aeronave que haya sido mantenida, reconstruida o alterada de una manera que pueda haber cambiado apreciablemente sus características de vuelo o afectado sustancialmente su operación en vuelo, hasta que un piloto con la calificación adecuada con al menos una licencia de piloto privado vuele la aeronave, realiza una verificación operativa del mantenimiento realizado o alteración realizada y registra el vuelo en los libros de la aeronave. Existe un procedimiento titulado “Prueba en vuelo de aeronavegabilidad” (MIA, Volumen !, Parte 1lI, Capítulo 10) en el cual se señala: “Las pruebas en vuelo de aeronavegabilidad deben realizarse solamente con la tripulación mínima establecida en el certificado de tipo de la aeronave, el inspector de aeronavegabilidad, el inspector de operaciones, si es necesario; y el personal de mantenimiento (si fuera necesario). No se debe incluir carga, a menos que forme parte de una prueba funcional específica” Por lo tanto, tampoco se incluye pasajeros a bordo."},
  {"id": 178, "s": 3, "q": "Una aeronave que transporta pasajeros por contrato ha estado en un programa de inspección cada 100 horas de tiempo en servicio. ¿Bajo qué condición, si corresponde, puede esa aeronave operar más allá de las 100 horas sin una nueva inspección?", "o": ["La aeronave puede volar para cualquier vuelo siempre que el tiempo en servicio no haya excedido las 110 horas.", "La aeronave puede enviarse para un vuelo de cualquier duración siempre que no se hayan excedido las 100 horas en el momento de la salida.", "El límite de 100 horas puede excederse en no más de 10 horas si es necesario para llegar a un lugar en el que se pueda realizar la inspección."], "a": 2, "e": "El límite de 100 horas puede excederse en no más de 10 horas si es necesario para llegar a un lugar donde se puede realizar la inspección. El exceso de tiempo, sin embargo, se incluye en el cálculo de las próximas 100 horas de tiempo en servicio. La respuesta (A) es incorrecta porque el período de gracia de 10 horas solo se aplica al transporte de Una aeronave a una instalación de mantenimiento, para la inspección de 100 horas. La respuesta (B) es incorrecta porque el período de gracia de 10 horas solo se aplica al transporte de un avión a una instalación de mantenimiento, para la inspección de 100 horas. (LAR 43)."},
  {"id": 179, "s": 3, "q": "¿Cuál afirmación es correcta con respecto a las inspecciones de mantenimiento requeridas?", "o": ["Una inspección de 100 horas puede sustituirse por una inspección anual.", "Una inspección anual puede sustituirse por una inspección de 100 horas.", "Se requiere una inspección anual incluso si se ha aprobado un sistema de inspección progresiva."], "a": 1, "e": "La anual se considera la inspección más rigurosa y puede sustituirse por la de 100 horas, no al revés. La respuesta (A) es incorrecta porque una inspección anual puede sustituirse por una inspección de 100 horas. La respuesta (C) es incorrecta porque se puede realizar una inspección progresiva en lugar de una inspección anual. (LAR 43)."},
  {"id": 180, "s": 3, "q": "No se debe usar un transpondedor ATC a menos que haya sido probado, inspeccionadoy se haya determinado que cumple con las regulaciones dentro de los:", "o": ["30 días.", "12 meses.", "24 meses."], "a": 2, "e": "Ninguna persona puede usar un transpondedor ATC a menos que, dentro de los 24 meses calendario anteriores, ese transpondedor ATC haya sido probado, inspeccionado y se haya determinado que cumple con las regulaciones. [LAR 91.877(a)(2); LAR 43 Apéndices 3 y 4]."},
  {"id": 181, "s": 3, "q": "Los registros de mantenimiento de la aeronave deben incluir el estado actual del:-", "o": ["certificado de aeronavegabilidad aplicable.", "partes con vida útil limitada únicamente del motor y la estructura del avión.", "partes de vida útil limitada de cada fuselaje, motor, hélice, rotor y componente de aeronave."], "a": 2, "e": "Cada propietario u operador registrado deberá mantener registros que contengan la siguiente información: el estado actual de las partes con vida limitada de cada fuselaje, motor, hélice, rotor y componentes de aeronave. [LAR 43.320 (b)(1)]"},
  {"id": 182, "s": 3, "q": "¿Cuál afirmación es cierta en relación con las Directivas de aeronavegabilidad (AD)?", "o": ["Las AD son de carácter consultivo y, por lo general, no se tratan de inmediato.", "El incumplimiento de los AD hace que una aeronave no esté en condiciones de volar.", "El cumplimiento de los AD es responsabilidad del personal de mantenimiento."], "a": 1, "e": "Ninguna persona puede operar un producto al que se aplique una Directiva de aeronavegabilidad, excepto de conformidad con los requisitos de dicha Directiva. La respuesta (A) es incorrecta porque los AD son obligatorios. La respuesta (C) es incorrecta porque el cumplimiento de los AD, junto con otras regulaciones de mantenimiento, es responsabilidad del propietario / operador. [LAR 91.1125(a)(3)]"},
  {"id": 183, "s": 3, "q": "Si un transpondedor ATC instalado en una aeronave no ha sido probado, inspeccionadoy no cumple con las regulaciones dentro de un período específico, ¿cuál es la limitación de su uso?", "o": ["No se permite su uso.", "Se puede utilizar en el espacio aéreo de Clase G.", "Puede usarse solo para vuelos VFR."], "a": 0, "e": "Ninguna persona puede usar un transpondedor ATC a menos que, dentro de los 24 meses calendario anteriores, ese transpondedor ATC haya sido probado, inspeccionado y se haya determinado que cumple con las regulaciones. [LAR 91.1110(f)(3)]"},
  {"id": 184, "s": 3, "q": "Para servir como piloto al mando de un avión certificado para más de un piloto y operado bajo LAR 91, una persona debe:", "o": ["completar un repaso de vuelo dentro de los 24 meses calendario anteriores.", "recibir y registrar entrenamiento en tierra y en vuelo con un instructor de vuelo autorizado.", "completar una verificación de competencia de piloto al mando dentro de los seis meses calendario anteriores en un avión con certificación de tipo para más de un piloto."], "a": 2, "e": "Para actuar como piloto al mando de una aeronave que tiene certificación de tipo para más de un piloto requerido, una persona debe completar una verificación de competencia como PIC en la aeronave que tiene certificación de tipo para más de un piloto como miembro de la tripulación de vuelo dentro de los seis (6) meses calendario anteriores. Además, el piloto debe completar una verificación de competencia PIC en el tipo particular de aeronave en la que esa persona servirá como PIC dentro de los 24 meses calendario anteriores. Este requisito no aplica a las personas que realizan las operaciones de acuerdo a un programa de entrenamiento de un explotador de servicios aéreos certificados. La verificación de competencia realizada de acuerdo con las previsiones de un poseedor de un AOC puede usarse para satisfacer este requisito. La verificación de competencia del piloto al mando requerida, puede ser satisfecha de alguna de las maneras siguientes: 1. Verificación de competencia de piloto al mando realizada ante una persona autorizada por la AAC, que incluya las maniobras y procedimientos para la habilitación de tipo, en una aeronave certificada para una tripulación de más de un piloto. 2. El examen práctico inicial y periódico requeridos para la emisión de una autorización como piloto examinador o inspector, en una aeronave certificada para una tripulación de más de un piloto. (LAR 61.145)"},
  {"id": 185, "s": 3, "q": "Para servir como copiloto de un avión certificado para más de un piloto y operado bajo LAR 91, una persona debe:", "o": ["recibir y registrar entrenamiento de vuelo de un instructor de vuelo autorizado en el tipo de avión para el cual se solicitan privilegios.", "poseer al menos una licencia de piloto comercial con una habilitación de categoría de avión.", "haya adquirido, bajo la debida supervisión, experiencia en el tipo de aeronave de que se trate y/o en simulador de vuelo, en los procedimientos y maniobras señalados en el LAR 61."], "a": 2, "e": "La respuesta A no es correcta por cuanto la instrucción de vuelo no solo puede ser en la aeronave, sino también en un simulador de vuelo correspondiente a la certificación de tipo de la aeronave a ser operada. La respuesta B no es correcta debido a que el piloto comercial debe contar además de la habilitación de categoría de avión, con la habilitación de tipo correspondiente a la aeronave que es la que respaldará las atribuciones a ejercer, así como la habilitación de vuelo por instrumentos en caso de realizar vuelos IFR. La respuesta correcta es la C conforme a lo que indica el LAR, dado que para ejercer como copiloto la persona debe contar con la experiencia en el tipo de aeronave a operar, en las maniobras y procedimientos detallados en el reglamento (LAR 61.120)."},
  {"id": 186, "s": 3, "q": "Las regulaciones de operación para aviones civiles requieren que, durante el movimiento en la superficie, despegues y aterrizajes, un cinturón de seguridad y un arnés parahombros (si están instalados) deben estar debidamente asegurados:", "o": ["solo para miembros de la tripulación de vuelo.", "personas a bordo.", "tripulantes de vuelo y de cabina."], "a": 1, "e": "Ningún piloto puede hacer que se mueva en la superficie, despegue o aterrice una aeronave civil registrada en el Estado, a menos que el piloto al mando de esa aeronave se asegure de que cada persona a bordo (mayor de dos años) haya sido notificada para abrocharse cinturón de seguridad y, si está instalado, su arnés de hombro. (LAR 91.555)."},
  {"id": 187, "s": 3, "q": "Ninguna persona puede operar una aeronave en condiciones de vuelo por instrumentos simulados a menos que:", "o": ["el otro asiento de control está ocupado por al menos un piloto comercial debidamente calificado.", "el piloto ha presentado un plan de vuelo IFR y ha recibido una autorización IFR.", "el otro asiento de control está ocupado por un piloto de seguridad, que posee al menos un certificado de piloto privado y está debidamente calificado."], "a": 2, "e": "Ninguna persona puede operar una aeronave civil en vuelo por instrumentos simulado a menos que el otro asiento de control esté ocupado por un piloto de seguridad que posea al menos un certificado de piloto privado con habilitaciones de categoría y clase apropiadas para la aeronave que está volando. [LAR 91.195(a)(2)]."},
  {"id": 188, "s": 3, "q": "Si la velocidad mínima segura para cualquier operación en particular es mayor que la velocidad máxima prescrita en LAR 91:", "o": ["El operador debe tener un Memorando de Acuerdo (MOA) con la agencia controladora.", "las aeronaves pueden operar a esa velocidad.", "El operador debe tener una carta de acuerdo con ATC."], "a": 1, "e": "Si la velocidad aérea mínima segura para cualquier operación en particular es mayor que la velocidad máxima prescrita en la Parte 91, la aeronave puede operarse a esa velocidad mínima. [LAR 91.165(b)]."},
  {"id": 189, "s": 3, "q": "Una persona con licencia de piloto comercial puede actuar como piloto al mando de una aeronave que transporta personas o bienes a cambio de una remuneración o por arrendamiento, si esa persona:", "o": ["posee las habilitaciones de categoría y clase apropiadas y cumple con los requisitos de experiencia de vuelo recientes de LAR 61.", "está calificado de acuerdo con LAR 61 y con las normas aplicables a la operación.", "está calificado de acuerdo con LAR 61 y ha pasado una verificación de competencia de piloto otorgada por un piloto de verificación autorizado."], "a": 1, "e": "El piloto no solo debe estar calificado de acuerdo con el LAR 61, el piloto también debe cumplir con las reglas generales del LAR 91 y las específicas a la operación a efectuar (LAR 121/LAR 135)."},
  {"id": 190, "s": 3, "q": "Ninguna persona puede operar una aeronave que tenga un certificado de aeronavegabilidad experimental:", "o": ["bajo las reglas de vuelo por instrumentos (IFR).", "al transportar propiedades por contrato.", "para transportar personas o bienes por remuneración."], "a": 2, "e": "Ninguna persona puede operar una aeronave que tenga un certificado experimental mientras transporta personas o bienes por remuneración o arrendamiento. (LAR 91.450)."},
  {"id": 191, "s": 3, "q": "Ha realizado 25 despegues y aterrizajes en aviones terrestres multimotor en los últimos 45 días. Para un vuelo que planea realizar hoy, ¿esto cumple con los requisitos de experiencia reciente de PIC para transportar pasajeros en qué aviones?", "o": ["multimotor o monomotor.", "Avión monomotor.", "Avión multimotor."], "a": 2, "e": "Ninguna persona puede actuar como piloto al mando de una aeronave que transporta pasajeros a menos que, dentro de los 90 días anteriores, haya realizado tres despegues y aterrizajes como único manipulador de los controles en una aeronave de la misma categoría, clase y tipo (si es necesario). (LAR 91.2640)."},
  {"id": 192, "s": 3, "q": "Está realizando la verificación previa de una aeronave y observa que la última inspección del transmisor del localizador de emergencia fue hace 11 meses calendario. Puede:", "o": ["Partir, si obtiene un permiso de vuelo especial.", "Partir, porque el ELT está dentro de los requisitos de inspección.", "No partir hasta que se lleve a cabo una nueva inspección."], "a": 1, "e": "Los transmisores de localización de emergencia (ELT) deben inspeccionarse dentro de los 12 meses calendario posteriores a la última inspección. (LAR 91.877)"},
  {"id": 193, "s": 3, "q": "¿Cuál es la dirección general de movimiento de la otra aeronave si durante un vuelo nocturno observa una luz blanca fija y una luz roja giratoria delante y a su altitud? El otro avión está:", "o": ["Alejándose.", "Cruzando a tu izquierda.", "Acercándose a usted de frente."], "a": 0, "e": "El piloto está viendo la baliza giratoria y la luz blanca en la cola. El otro avión se aleja. La respuesta (B) es incorrecta porque vería una luz roja fija si el otro avión cruzara a su izquierda. La respuesta (C) es incorrecta porque vería las luces de posición de la punta del ala tanto roja como verde si el otro avión se acercara a usted de frente. (LAR 91 Apéndice C)."},
  {"id": 194, "s": 4, "q": "La visibilidad mínima de vuelo para vuelos VFR aumenta a 5 millas terrestres a partir de una altitud de:", "o": ["A 14,500 pies MSL.", "A 10,000 pies MSL si están por encima de 1,200 pies AGL.", "A 10,000 pies MSL independientemente de la altura sobre el suelo."], "a": 1, "e": "La única área que requiere una visibilidad de 5 millas terrestres es de 10,000 pies MSL y más (cuando están por encima de 1,200 pies AGL)."},
  {"id": 195, "s": 4, "q": "Su vuelo VFR se realizará por encima de 10,000 MSL en espacio aéreo Clase E. ¿Cuál es la visibilidad mínima de vuelo?", "o": ["3 NM.", "5SM.", "1SM."], "a": 1, "e": "La única área que requiere una visibilidad de 5 millas terrestres es de 10,000 pies MSL y más (cuando están por encima de 1,200 pies AGL)."},
  {"id": 196, "s": 4, "q": "¿Cuáles son los requisitos mínimos de visibilidad de vuelo y proximidad a la nube para vuelos VFR, a 6.500 pies MSL, en espacio aéreo de Clase C, D y E?", "o": ["1 milla de visibilidad; despejado de nubes.", "3 millas de visibilidad; 1,000 pies arriba y 500 pies abajo.", "5 millas de visibilidad; 1,000 pies arriba y 1,000 pies abajo."], "a": 1, "e": "En el espacio aéreo Clase C, D o E a 6.500 pies MSL, el requisito de visibilidad de vuelo VFR es 3 SM. El requisito de distancia desde la nube es de 500 pies por debajo, 1,000 pies por encima y 2,000 pies en horizontal. La respuesta (A) es incorrecta porque la visibilidad de 1 SM y despejado de nubes es el mínimo meteorológico VFR cuando está a 1200 pies AGL o menos en el espacio aéreo Clase G durante el día. La respuesta (C) es incorrecta porque la visibilidad de 5 SM y el despeje de nubes de 1,000 pies arriba y abajo es el mínimo meteorológico VFR en el espacio aéreo de Clase E a 10,000 pies MSL o más. 5088.- Cuando se opera un avión con el propósito de aterrizar o despegar dentro del espacio aéreo Clase D bajo VFR especial, ¿qué distancia mínima de las nubes y qué visibilidad se requieren? A. Manténgase libre de nubes y la visibilidad desde el suelo debe ser de al menos 1 SM. B. 500 pies debajo de las nubes y la visibilidad del suelo debe ser de al menos 1 SM. C. Manténgase libre de nubes y la visibilidad del vuelo debe ser de al menos 1 NM. Ninguna persona puede operar un avión dentro del espacio aéreo de Clase D bajo VFR especial a menos que permanezcan libres de nubes y la visibilidad en tierra debe ser de al menos 1 SM. La respuesta (B) es incorrecta porque el despeje de nubes para VFR especial está libre de nubes. La respuesta (C) es incorrecta porque si no se informa la visibilidad en tierra, la visibilidad del vuelo durante el aterrizaje o el despegue debe ser de al menos 1 SM."},
  {"id": 197, "s": 4, "q": "En algunos aeropuertos ubicados en el espacio aéreo de Clase D donde no se informa la visibilidad en tierra, se realizan despegues y aterrizajes bajo VFR especial.", "o": ["No autorizado.", "Autorizado por ATC si la visibilidad del vuelo es de al menos 1 SM.", "Autorizado sólo si se observa que la visibilidad del suelo es de al menos 3 SM."], "a": 1, "e": "Ninguna persona puede operar un avión dentro del espacio aéreo de Clase D bajo VFR especial a menos que permanezcan libres de nubes y la visibilidad en tierra debe ser de al menos 1 SM. Si la visibilidad en tierra no se informa en ese aeropuerto, la visibilidad del vuelo durante el aterrizaje o despegue debe ser de al menos 1 SM. La respuesta (A) es incorrecta porque el VFR especial está autorizado si la visibilidad del vuelo es de al menos 1 SM. La respuesta (C) es incorrecta porque el requisito de visibilidad para VFR especial es 1 SM."},
  {"id": 198, "s": 4, "q": "Para operar un avión bajo “SPECIAL VFR (SVFR)” dentro del espacio aéreo Clase D durante la noche, ¿cuál se requiere?", "o": ["El piloto debe tener una habilitación de instrumentos, pero el avión no necesita estar equipado para vuelo por instrumentos, siempre que el clima se mantenga en o por encima de los mínimos SVFR.", "Un área SVFR nocturna. El espacio aéreo Clase D debe estar específicamente designado.", "El piloto debe tener una habilitación de instrumentos y el avión debe estar equipado para vuelo por instrumentos."], "a": 2, "e": "Ninguna persona puede operar un avión en el espacio aéreo de Clase D bajo VFR especial durante la noche a menos que esa persona esté habilitada para instrumentos y el avión esté equipado para vuelo por instrumentos. La respuesta (A) es incorrecta porque el avión debe estar equipado para vuelo por instrumentos. La respuesta (B) es incorrecta porque no existe una designación como 'área SVFR nocturna\"."},
  {"id": 199, "s": 4, "q": "Se requiere que se mantengan las altitudes de crucero VFR al volar:", "o": ["A 3,00 0 pies o más AGL, basado en el rumbo verdadero.", "Más de 3,000 pies AGL, basado en curso magnético.", "A 3,000 pies o más sobre MSL, basado en rumbo magnético."], "a": 1, "e": "En crucero nivelado a más de 3000 pies AGL, el rumbo magnético determina la altitud adecuada. La respuesta (A) es incorrecta porque las altitudes de crucero VFR se basan en el rumbo magnético y se aplican a vuelos por encima de los 3000 pies AGL. La respuesta (C) es incorrecta porque las altitudes de crucero VFR se basan en el rumbo magnético y se aplican a vuelos por encima de los 3000 pies AGL."},
  {"id": 200, "s": 4, "q": "Después de que se haya obtenido una autorización ATC, un piloto no puede desviarse de esa autorización, a menos que el piloto:", "o": ["solicite una autorización modificada.", "esté operando VFR en la parte superior.", "recibe una autorización enmendada o tiene una emergencia."], "a": 2, "e": "Cuando se ha obtenido una autorización del ATC, ningún piloto al mando puede desviarse de esa autorización a menos que se obtenga una autorización enmendada, exista una emergencia o la desviación sea en respuesta a una alerta de tráfico y un aviso de resolución del sistema para evitar colisiones."},
  {"id": 201, "s": 4, "q": "Al acercarse a aterrizar en un aeropuerto, sin una torre de control operativa, en espacio aéreo Clase G, el piloto debe:", "o": ["hacer todos los giros a la izquierda, a menos que se indique lo contrario.", "volar un patrón de tráfico por la izquierda a 800 pies AGL.", "Ingresar y volar un patrón de tráfico a 800 pies AGL."], "a": 0, "e": "Al acercarse para aterrizar en un aeropuerto sin una torre de control operativa en un área de espacio aéreo de Clase G, cada piloto de un avión debe hacer todos los giros de ese avión a la izquierda a menos que el aeropuerto muestre señales luminosas aprobadas o marcas visuales que indiquen que se deben realizar giros para a la derecha, en cuyo caso el piloto debe hacer todos los giros a la derecha."},
  {"id": 202, "s": 4, "q": "Al operar una aeronave en las cercanías de un aeropuerto con una torre de control operativa, en el espacio aéreo de Clase E, un piloto debe establecer comunicaciones antes de:", "o": ["8 NM y hasta 3000 pies AGL inclusive.", "5 NM y hasta 3000 pies AGL inclusive.", "4 NM y hasta 2500 pies AGL inclusive."], "a": 2, "e": "A menos que sea autorizado o requerido por ATC, ninguna persona puede operar una aeronave hacía, desde, a través o en un aeropuerto que tenga una torre de control operacional a menos que se mantengan comunicaciones de radio bidireccionales entre esa aeronave y la torre de control. Las comunicaciones deben establecerse antes de las 4 NM del aeropuerto, hasta 2,500 pies AGL inclusive."},
  {"id": 203, "s": 4, "q": "Al acercarse a aterrizar en un aeropuerto con una instalación ATC, en espacio aéreo ClaseD, el piloto debe establecer comunicaciones antes de:", "o": ["10 NH, hasta 3000 pies AGL inclusive.", "30 SM, y estar equipado con transpondedor.", "4 NM, hasta 2500 pies AGL inclusive."], "a": 2, "e": "A menos que sea autorizado o requerido por ATC, ninguna persona puede operar una aeronave hacía, desde, a través o en un aeropuerto que tenga una torre de control operacional a menos que se mantengan comunicaciones de radio bidireccionales entre esa aeronave y la torre de control. Las comunicaciones deben establecerse antes de las 4 NM del aeropuerto, hasta 2,500 pies AGL inclusive."},
  {"id": 204, "s": 4, "q": "¿Cuál de las siguientes afirmaciones es cierta respecto a las operaciones de vuelo hacia o desde un aeropuerto satélite, sin una torre de control operativa, dentro del área del espacio aéreo de Clase C?", "o": ["Antes del despegue, un piloto debe establecer comunicación con la instalación de control del ATC.", "La aeronave debe estar equipada con un transpondedor ATC y equipo de reporte de altitud.", "Antes del aterrizaje, un piloto debe establecer y mantener comunicación con una instalación ATC."], "a": 1, "e": "A menos que el ATC lo autorice o indique lo contrario, ninguna persona puede operar una aeronave en el espacio aéreo Clase C a menos que la aeronave esté equipada con un transpondedor operable y un equipo de reporte de altitud. La respuesta (A) es incorrecta porque los pilotos deben establecer comunicación con la instalación de control del ATC tan pronto como sea posible, lo que puede no ser antes del despegue. La respuesta (C) es incorrecta porque las comunicaciones deben establecerse antes de ingresar al espacio aéreo Clase C, mucho antes de un punto \"antes del aterrizaje\"."},
  {"id": 205, "s": 4, "q": "¿Cuál de las siguientes afirmaciones es cierta respecto a las operaciones de vuelo hacia o desde un aeropuerto satélite, sin una torre de control operativa, dentro del área del espacio aéreo de Clase C?", "o": ["Antes de ingresar a ese espacio aéreo, un piloto debe establecer y mantener comunicación con la instalación de servicio ATC.", "La aeronave debe estar equipada con un transpondedor ATC.", "Antes del despegue, un piloto debe establecer comunicación con la instalación de control del ATC."], "a": 0, "e": "Ninguna persona puede despegar o aterrizar una aeronave en un aeropuerto satélite dentro de un área de espacio aéreo de Clase C, excepto en cumplimiento con los patrones de tráfico de llegada y salida de la AAC. Cada persona debe establecer comunicaciones de radio bidireccionales con la instalación ATC que proporciona servicios de tránsito aéreo antes de ingresar a ese espacio aéreo y, posteriormente, mantener esas comunicaciones mientras se encuentre dentro de ese espacio aéreo. La respuesta (B) es incorrecta porque a menos que el ATC lo autorice o indique lo contrario, ninguna persona puede operar una aeronave en el espacio aéreo de Clase C a menos que la aeronave esté equipada con un transpondedor operable y un equipo de reporte de altitud; desde un aeropuerto satélite sin una torre de control operativa dentro del espacio aéreo de Clase C, el piloto debe establecer y mantener comunicaciones de radio bidireccionales con la instalación de control de ATC tan pronto como sea posible después de la salida. La respuesta (C) es incorrecta porque a menos que el ATC lo autorice o indique lo contrario, ninguna persona puede operar una aeronave en el espacio aéreo de Clase C a menos que la aeronave esté equipada con un transpondedor operable y un equipo de reporte de altitud; desde un aeropuerto satélite sin una torre de control operativa dentro del espacio aéreo de Clase C, el piloto debe establecer y mantener comunicaciones de radio bidireccionales con la instalación de control de ATC tan pronto como sea posible después de la salida."},
  {"id": 206, "s": 4, "q": "El radio del área exterior inexplorada del espacio aéreo Clase C es normalmente:", "o": ["20 NM.", "30 NM.", "40 NM."], "a": 0, "e": "El radio normal del área exterior será de 20 NM. Esta es el área donde se proporciona la separación después de que se establece la comunicación bidireccional. Es solo un requisito comunicarse con ATC antes de ingresar al espacio aéreo Clase C de 10 NM que se muestra en la carta seccional."},
  {"id": 207, "s": 4, "q": "¿Cuál de las siguientes afirmaciones es cierta respecto a las operaciones de vuelo en el espacio aéreo de Clase A?", "o": ["La aeronave debe estar equipada con equipo de medición de distancia (DME) aprobado.", "La aeronave debe estar equipada con un transpondedor ATC y un equipo de notificación de altitud.", "Puede realizar operaciones bajo reglas de vuelo visual."], "a": 1, "e": "A menos que el ATC lo autorice de otra manera, ninguna persona puede operar una aeronave dentro del espacio aéreo de Clase A menos que la aeronave esté equipada con un transpondedor aprobado y un equipo de notificación de altitud."},
  {"id": 208, "s": 4, "q": "Cuando la información meteorológica indique que existe una presión barométrica anormalmente alta o por encima de, pulgadas de mercurio, no se autorizarán operacionesde vuelo contrarias a los requisitos publicados en los NOTAM.", "o": ["31.00.", "32.00.", "3050."], "a": 0, "e": "Existen restricciones de vuelo especiales cuando cualquier información indica que la presión barométrica en la ruta de vuelo excede actualmente o excederá las 31 pulgadas de mercurio y ninguna persona puede operar una aeronave o iniciar un vuelo en contra de los requisitos establecidos."},
  {"id": 209, "s": 4, "q": "Al planificar un vuelo nocturno, un piloto debe verificar:", "o": ["disponibilidad y estado de los sistemas de iluminación de los aeropuertos de ruta y de destino.", "luces rojas de rumbo en ruta.", "ubicación de balizas de luz giratorias”."], "a": 0, "e": "Antes de un vuelo nocturno, y particularmente de un vuelo nocturno, los pilotos deben verificar la disponibilidad y el estado de los sistemas de iluminación en el aeropuerto de destino."},
  {"id": 210, "s": 4, "q": "Las balizas de luz que producen destellos rojos indican:", "o": ["aviso de fin de pista al final de la salida.", "que un piloto debe mantenerse alejado de un patrón de tráfico del aeropuerto y continuar dando vueltas.", "obstrucciones o áreas consideradas peligrosas para la navegación aérea."], "a": 2, "e": "Las balizas que emiten destellos rojos indican obstrucciones o áreas consideradas peligrosas para la navegación aérea."},
  {"id": 211, "s": 4, "q": "¿Cuál es la primera indicación de volar en condiciones de visibilidad restringida cuando se opera VFR de noche?", "o": ["Las luces de tierra comienzan a tomar la apariencia de estar rodeadas por un halo o resplandor.", "Una desaparición gradual de luces en el suelo.", "Las luces de la cabina comienzan a tomar la apariencia de un halo o brillan a su alrededor."], "a": 1, "e": "Generalmente, por la noche es difícil ver nubes y restricciones de visibilidad, particularmente en noches oscuras o bajo cielo nublado. Por lo general, la primera indicación de volar en condiciones de visibilidad restringida es la desaparición gradual de las luces en el suelo. La respuesta (A) y (C) son incorrectas porque las luces del suelo (no de la cabina) que adquieren la apariencia de un halo o resplandor indican niebla en el suelo."},
  {"id": 212, "s": 4, "q": "¿Quién tiene la autoridad final para aceptar o rechazar cualquier autorización de aterrizaje y espera corta (LAHSO)?", "o": ["Controlador de la torre de control.", "Controlador de aproximación ATC.", "Piloto al mando."], "a": 2, "e": "El piloto al mando tiene la autoridad final para aceptar o rechazar cualquier autorización LAHSO. La seguridad y el funcionamiento de la aeronave siguen siendo responsabilidad del piloto. 5139.- ¿Cuándo deben los pilotos rechazar una autorización de aterrizaje y espera corta (LAHSO)? A. Cuándo comprometerá la seguridad operacional. B. Si la superficie de la pista está contaminada. C. Solo cuando el controlador de la torre está de acuerdo. Se espera que los pilotos rechacen una autorización de LAHSO si determinan que comprometerá la seguridad operacional."},
  {"id": 213, "s": 4, "q": "Una autorización de aterrizaje y espera corta (LAHSO):", "o": ["excluye un “go around” por el ATC.", "no excluye un aterrizaje rechazado.", "requiere una salida de pista en la primera calle de rodaje."], "a": 1, "e": "Una autorización de LAHSO, una vez aceptada, debe cumplirse, al igual que cualquier otra autorización de ATC, a menos que se obtenga una autorización enmendada o se produzca una emergencia. Una autorización de LAHSO no excluye un aterrizaje rechazado."},
  {"id": 214, "s": 4, "q": "Cuál es la visibilidad mínima y el techo requeridos para que un piloto reciba una autorización de:", "o": ["3 millas terrestres y 1,000 pies.", "3 millas náuticas y 1,000 pies.", "3 millas terrestres y 1,500 pies."], "a": 0, "e": "Los pilotos solo deben recibir una autorización de LAHSO cuando hay un techo mínimo de 1,000 pies y una visibilidad de 3 millas terrestres. La intención de tener condiciones VFR 'básicas' es permitir que los pilotos mantengan contacto visual con otras aeronaves y operaciones de vehículos terrestres."},
  {"id": 215, "s": 4, "q": "¿Cómo puede determinar si otra aeronave está en de colisión con su aeronave?", "o": ["La nariz de cada avión apunta al mismo punto en el espacio.", "El otro avión siempre parecerá volverse más grande y cercano a un ritmo rápido.", "No habrá ningún movimiento relativo aparente entre su avión y el otro avión."], "a": 2, "e": "Es esencial recordar que, si otra aeronave parece no tener movimiento relativo, es probable que esté en curso de colisión con usted. Si la otra aeronave no muestra ningún movimiento lateral o vertical, pero aumenta de tamaño, realice una acción evasiva."},
  {"id": 216, "s": 4, "q": "Para operaciones de vuelo nocturno, la mejor visión nocturna se logra cuando:", "o": ["las pupilas de los ojos se han dilatado en aproximadamente 10 minutos.", "las varillas de los ojos se han adaptado a la oscuridad en aproximadamente 30 minutos.", "los conos de los ojos se han adaptado a la oscuridad en aproximadamente 5 minutos."], "a": 1, "e": "Al entrar en una habitación oscura, es difícil ver algo hasta que los ojos se adapten a la oscuridad. Después de aproximadamente 5 a 10 minutos, los conos se ajustan a la luz tenue y los ojos se vuelven 100 veces más sensibles a la luz de lo que eran antes de entrar en la habitación oscura. Se necesita mucho más tiempo, unos 30 minutos, para que las varillas se adapten a la oscuridad; pero cuando se ajustan, son unas 100.000 veces más sensibles a la luz que en el área iluminada."},
  {"id": 217, "s": 4, "q": "Al planificar un vuelo, el piloto debe verificar la disponibilidad y el estado de:", "o": ["todos los VOR que se utilizarán en ruta.", "balizas luminosas aeropuerto.", "sistema de iluminación para el aeropuerto destino."], "a": 2, "e": "Se recomienda que antes de un vuelo nocturno y particularmente de un vuelo de travesía nocturno, el piloto verifique la disponibilidad y el estado de los sistemas de iluminación en el aeropuerto de destino."},
  {"id": 218, "s": 4, "q": "Después de experimentar una falla en la central eléctrica por la noche, una de las principales consideraciones debe incluir:", "o": ["Apagar todos los interruptores eléctricos para ahorrar energía de la batería para el aterrizaje.", "Maniobrar y aterrizar en una carretera o camino iluminado.", "Planificar la aproximación de emergencia y el aterrizaje en una parte no iluminada de un área."], "a": 2, "e": "Si el motor falla por la noche, una de las consideraciones principales incluye planificar una aproximación de emergencia y aterrizar en una parte no iluminada del área."},
  {"id": 219, "s": 4, "q": "Al planificar un aterrizaje de emergencia por la noche, una de las principales consideraciones debe incluir:", "o": ["Aterrizaje sin superficies sustentadoras para asegurar una actitud de aterrizaje de nariz el momento del aterrizaje.", "Apagar todos los interruptores eléctricos para ahorrar energía de la batería para el aterrizaje.", "seleccionar un área de aterrizaje cerca del acceso público, si es posible."], "a": 2, "e": "Si el motor falla por la noche, una de las consideraciones principales incluye seleccionar un área de aterrizaje de emergencia, si es posible, que pueda facilitar el rescate o ayuda, si es necesario."},
  {"id": 220, "s": 4, "q": "¿Cuál de las siguientes afirmaciones es cierta sobre los colores azul y magenta que se utilizan para representar los aeropuertos en las cartas aeronáuticas seccionales?", "o": ["Los aeropuertos con torres de control bajo espacio aéreo de Clase A, B y C se muestran en azul, el espacio aéreo de Clase D y E en magenta.", "Los aeropuertos con torres de control bajo espacio aéreo de Clase C, D y E se muestran en magenta.", "Los aeropuertos con torres de control bajo espacio aéreo de Clase B, C, D y E se muestran en azul."], "a": 2, "e": "Los aeropuertos que tienen torres de control (espacio aéreo de clase B, C, D o E) se muestran en azul. Todos los demás se muestran en magenta."},
  {"id": 221, "s": 4, "q": "Un área de alerta es un área en la cual:", "o": ["el vuelo de la aeronave, aunque no está prohibido, está sujeto a restricciones.", "el vuelo de aeronaves está prohibido.", "existe un gran volumen de actividades de formación de pilotos o un tipo inusual de actividad aérea, ninguno de los cuales es peligroso para la aeronave."], "a": 2, "e": "Las áreas de alerta informan a los pilotos sobre el espacio aéreo que puede contener un alto volumen de entrenamiento de pilotos o un tipo inusual de actividad aérea. Si bien los pilotos deben estar particularmente alerta en estas áreas, no existen restricciones para volar a través de ellas. La respuesta (A) es incorrecta porque describe un área restringida. La respuesta (B) es incorrecta porque describe un área prohibida."},
  {"id": 222, "s": 4, "q": "¿Qué debe hacer o tener en cuenta un piloto al realizar la transición de un área de alerta?", "o": ["Todos los pilotos deben comunicarse con la agencia de control para asegurar la separación de las aeronaves.", "Las aeronaves no participantes pueden transitar por el área siempre y cuando operen de acuerdo con su autorización.", "Siempre que operen, tener en cuenta que el área puede contener una actividad aeronáutica inusual o un alto volumen de entrenamiento de pilotos."], "a": 2, "e": "Las áreas de alerta informan a los pilotos sobre el espacio aéreo que puede contener un alto volumen de entrenamiento de pilotos o un tipo inusual de actividad aérea. Si bien los pilotos deben estar particularmente alerta en estas áreas, no existen restricciones para volar a través de ellas."},
  {"id": 223, "s": 4, "q": "¿Cuándo deben los pilotos rechazar una autorización de aterrizaje y espera corta (LAHSO)?", "o": ["Solo cuando el controlador de la torre esté de acuerdo.", "Si la superficie de la pista está contaminada.", "Cuando compromete la seguridad operacional."], "a": 2, "e": "Se espera que los pilotos rechacen una autorización de LAHSO si determinan que comprometerá la seguridad."},
  {"id": 224, "s": 4, "q": "¿Cuál es la visibilidad mínima y el techo requeridos para que un piloto reciba una autorización de aterrizaje y espera corta (LAHSO)?", "o": ["3 millas terrestres y 1,500 pies.", "3 millas náuticas y 1,000 pies.", "3 millas terrestres y 1,000 pies."], "a": 2, "e": "Los pilotos solo deben recibir una autorización de LAHSO cuando hay un techo mínimo de 1,000 pies y una visibilidad de 3 millas terrestres. La intención de tener condiciones climáticas VFR 'básicas' es permitir que los pilotos mantengan contacto visual con otras aeronaves y operaciones de vehículos terrestres."},
  {"id": 225, "s": 4, "q": "¿Qué debe esperar cuando le dicen que las operaciones de LAHSO están en vigor ensu aeropuerto de destino?", "o": ["Todas las aeronaves deben operar con una autorización IFR debido al alto volumen de tráfico.", "Ese ATC le dará una autorización para aterrizar y esperar antes de un punto específico en la pista.", "Retrasos debido a condiciones de IFR bajas y alto volumen de tráfico."], "a": 1, "e": "Land and Hold Short Operations (LAHSO) es un procedimiento de control de tráfico aéreo para equilibrar las necesidades de una mayor capacidad aeroportuaria y eficiencia del sistema, en consonancia con la seguridad. La respuesta (A) es incorrecta porque las autorizaciones LAHSO también están disponibles para aeronaves que operan VFR. La respuesta (C) es incorrecta porque los LAHSO se encuentran en aeropuertos de alta densidad y no se deben a condiciones IFR."},
  {"id": 226, "s": 4, "q": "Los pilotos deben tener funcionando el sistema de luces anticolisión:", "o": ["siempre que un motor esté en funcionamiento.", "siempre que el piloto esté en la cabina.", "durante todo tipo de operaciones, tanto de día como de noche."], "a": 2, "e": "Se anima a los pilotos de aeronaves equipadas con balizas giratorias a que las enciendan cuando tengan la intención de volar, como una alerta para otras aeronaves y personal de tierra. La respuesta (A) es incorrecta porque las luces no son necesarias si el piloto simplemente está sentado en la cabina del piloto o, por ejemplo, si un mecánico está trabajando en la aeronave y no tiene la intención de rodar o volar. La respuesta (B) es incorrecta porque las luces no son necesarias si el piloto simplemente está sentado en la cabina del piloto o, por ejemplo, si un mecánico está trabajando en la aeronave y no tiene la intención de rodar o volar."},
  {"id": 227, "s": 4, "q": "Cuando se encuentre cerca de un VOR que se esté utilizando para la navegación en vuelos VFR, es importante:", "o": ["hacer giros de 90 ? a la izquierda y a la derecha para buscar otro tráfico.", "ejercer una vigilancia sostenida para evitar aeronaves que puedan estar convergiendo en el VOR desde otras direcciones.", "pasar el VOR en el lado derecho del radial para dejar espacio para aviones que vuelan en la dirección opuesta en el mismo radial."], "a": 1, "e": "Los pilotos deben tener mayor precaución al ingresar al espacio aéreo de alto uso; esto incluye el espacio aéreo alrededor de los VOR. La respuesta (A) es incorrecta porque los giros de 90 * no son apropiados en ruta. La respuesta (C) es incorrecta porque debe intentar mantener el centro del radial."},
  {"id": 228, "s": 4, "q": "A medida que avanza la hiperventilación, un piloto puede experimentar:", "o": ["disminución de la frecuencia y la profundidad de la respiración.", "mayor conciencia y sensación de bienestar.", "síntomas de asfixia y somnolencia."], "a": 2, "e": "Los síntomas comunes de la hiperventilación son mareos, náuseas, sensaciones de frío y calor, hormigueo en las manos, piernas y pies, somnolencia y, finalmente, pérdida del conocimiento. La respuesta (A) es incorrecta porque la hiperventilación es un aumento de la frecuencia y la profundidad respiratorias. La respuesta (B) es incorrecta porque una mayor conciencia y sensación de bienestar son síntomas de hipoxia."},
  {"id": 229, "s": 4, "q": "Para escanear correctamente el tráfico, un piloto debe:", "o": ["escanear lentamente el campo de visión de un lado a otro a intervalos regulares.", "concentrarse en cualquier movimiento periférico detectado.", "utilizar una serie de movimientos oculares cortos y regularmente espaciados que llevan áreas de uso sucesivas del cielo al campo visual central."], "a": 2, "e": "Debido a que los ojos pueden enfocarse solo en un área de visión estrecha, el escaneo efectivo se logra con una serie de movimientos oculares cortos y regularmente espaciados que llevan áreas sucesivas del cielo al campo visual central. La respuesta (A) es incorrecta porque un piloto debe concentrarse sistemáticamente en diferentes segmentos. La respuesta (B) es incorrecta porque el movimiento periférico no se detecta fácilmente, especialmente en condiciones adversas; por lo tanto, esta no sería una técnica de exploración eficaz."},
  {"id": 230, "s": 4, "q": "¿Cuál es un síntoma común de hiperventilación?", "o": ["Somnolencia.", "Disminución de la frecuencia respiratoria.", "Una sensación de bienestar."], "a": 0, "e": "Los síntomas habituales de la hiperventilación son mareos, náuseas, sensaciones de frío y calor, hormigueo en manos, piernas y pies, somnolencia y finalmente pérdida del conocimiento. La respuesta (B) es incorrecta porque la hiperventilación es un aumento de la frecuencia respiratoria. La respuesta (C) es incorrecta porque una sensación de bienestar o euforia es un síntoma de hipoxia."},
  {"id": 231, "s": 4, "q": "¿Qué sería el resultado más probable en caso de hiperventilación?", "o": ["Insuficiencia de oxígeno.", "Exceso de monóxido de carbono.", "Insuficiente monóxido de carbono."], "a": 2, "e": "A medida que la hiperventilación 'expulsa' el exceso de dióxido de carbono del cuerpo, un piloto puede experimentar síntomas de aturdimiento, asfixia, somnolencia, hormigueo en las extremidades y frialdad y reaccionar ante ellos con una hiperventilación aún mayor. La respuesta (A) es incorrecta porque la insuficiencia de oxígeno es un síntoma de hipoxia. La respuesta (B) es incorrecta porque el exceso de monóxido de carbono provocará intoxicación por monóxido de carbono."},
  {"id": 232, "s": 4, "q": "¿La hipoxia es el resultado de cuál de estas condiciones?", "o": ["Exceso de oxígeno en el torrente sanguíneo.", "Llega insuficiente oxígeno al cerebro.", "Exceso de dióxido de carbono en el torrente sanguíneo."], "a": 1, "e": "La hipoxia es el resultado de la insuficiencia de oxígeno en el torrente sanguíneo que llega al cerebro. La respuesta (A) es incorrecta porque la hipoxia es una falta de oxígeno en el torrente sanguíneo. La respuesta (C) es incorrecta porque el exceso de dióxido de carbono en el torrente sanguíneo no es un síntoma de hipoxia."},
  {"id": 233, "s": 4, "q": "Para superar los síntomas de la hiperventilación, un piloto debe:", "o": ["tragar o bostezar.", "reducir la frecuencia respiratoria.", "aumentar la frecuencia respiratoria."], "a": 1, "e": "La hiperventilación se puede aliviar disminuyendo conscientemente la frecuencia respiratoria. Hablar en voz alta o respirar en una bolsa para restaurar el dióxido de carbono reducirá efectivamente la frecuencia respiratoria. La respuesta (A) es incorrecta porque se usa tragar o bostezar para aliviar el bloqueo del oído. La respuesta (C) es incorrecta porque la frecuencia respiratoria debe reducirse para aumentar la cantidad de dióxido de carbono en la sangre."},
  {"id": 234, "s": 4, "q": "¿Qué es cierto con respecto a la presencia de alcohol en el cuerpo humano?", "o": ["Una pequeña cantidad de alcohol aumenta la agudeza visual.", "Un aumento de altitud disminuye el efecto adverso del alcohol.", "La capacidad de juicio y de toma de decisiones puede verse afectado negativamente por incluso pequeñas cantidades de alcohol."], "a": 2, "e": "Tan solo una onza de licor, una botella de cerveza o cuatro onzas de vino pueden afectar las habilidades de vuelo. La respuesta (A) es incorrecta porque todas las actividades mentales y físicas disminuirán incluso con pequeñas cantidades de alcohol en el torrente sanguíneo. La respuesta (B) es incorrecta porque los efectos adversos del alcohol aumentan a medida que aumenta la altitud."},
  {"id": 235, "s": 4, "q": "Para deshacerse de todo el alcohol contenido en una cerveza, el cuerpo humano necesita aproximadamente:", "o": ["1 Hora.", "3 Horas.", "4 Horas."], "a": 1, "e": "Tan solo una onza de licor, una botella de cerveza o cuatro onzas de vino pueden afectar las habilidades de vuelo, y el alcohol consumido en estas bebidas es detectable en el aliento y la sangre durante al menos 3 horas."},
  {"id": 236, "s": 4, "q": "Para deshacerse de todo el alcohol contenido en una bebida mezclada, el cuerpo humano necesita aproximadamente:", "o": ["1 Hora.", "2 Horas.", "3 Horas."], "a": 2, "e": "Tan solo una onza de licor, una botella de cerveza o cuatro onzas de vino pueden afectar las habilidades de vuelo, y el alcohol consumido en estas bebidas es detectable en el aliento y la sangre durante al menos 3 horas."},
  {"id": 237, "s": 4, "q": "La susceptibilidad a la hipoxia debido a la inhalación de monóxido de carbono aumentaa medida que:", "o": ["la humedad disminuye.", "aumenta la altitud.", "aumenta la demanda de oxígeno."], "a": 1, "e": "El monóxido de carbono inhalado al fumar o de los gases de escape, la hemoglobina baja (anemia) y ciertos medicamentos pueden reducir la capacidad de transporte de oxígeno de la sangre al grado que la cantidad de oxígeno proporcionada a los tejidos corporales ya será equivalente al oxígeno proporcionado a los tejidos cuando se exponen a una altitud de presión de cabina de varios miles de pies. La respuesta (A) es incorrecta porque el nivel de humedad no influye en los niveles de monóxido de carbono u oxígeno. La respuesta (C) es incorrecta porque la demanda de oxígeno no cambia."},
  {"id": 238, "s": 4, "q": "Para superar mejor los efectos de la desorientación espacial, un piloto debe:", "o": ["Confiar en las sensaciones corporales.", "Aumentar la frecuencia respiratoria.", "Confiar en las indicaciones de los instrumentos de la aeronave."], "a": 2, "e": "La desorientación espacial sólo puede evitarse mediante una referencia visual a puntos fijos fiables en el suelo o a los instrumentos de vuelo. La respuesta (A) es incorrecta porque las sensaciones corporales deben ignorarse. La respuesta (B) es incorrecta porque un aumento en la frecuencia respiratoria podría causar hiperventilación."},
  {"id": 239, "s": 4, "q": "Para hacer frente a la desorientación espacial, los pilotos deben confiar en:", "o": ["sensaciones corporales y referencias visuales externas.", "alimentación adecuada, descanso y adaptación nocturna.", "uso competente de los instrumentos de la aeronave."], "a": 2, "e": "La desorientación espacial no se puede prevenir por completo, pero puede y debe ignorarse o suprimirse suficientemente desarrollando una confianza absoluta en lo que los instrumentos de vuelo están diciendo sobre la actitud de la aeronave."},
  {"id": 240, "s": 4, "q": "Un piloto que vuela en un estado de fatiga es un peligro porque:", "o": ["volar fatigado es volar deficiente.", "El piloto se apresurará a revisar y descuidar los artículos.", "El piloto excederá las limitaciones de la aeronave para completar el vuelo."], "a": 0, "e": "Fatiga significa un estado fisiológico de reducción de la capacidad de rendimiento físico o mental resultante de la falta de sueño o del aumento de la actividad física que puede reducir el estado de alerta y la capacidad de un miembro de la tripulación de vuelo para operar una aeronave con seguridad o realizar tareas relacionadas con la seguridad."},
  {"id": 241, "s": 4, "q": "Al salir de una pista cubierta de nieve o aguanieve, ¿qué puede hacer un piloto para evitar daños en el tren de aterrizaje debido a las condiciones?", "o": ["No retraer el tren de aterrizaje inmediatamente para permitir que se seque al aire.", "Retraer inmediatamente el tren de aterrizaje para que se pueda calentar en los compartimentos del tren.", "Volar a una velocidad por encima del arco verde del indicador de velocidad aerodinámica puede eliminar la nieve y la aguanieve."], "a": 0, "e": "Si sale de una pista de aterrizaje con nieve húmeda o aguanieve en la superficie de despegue, el tren no debe retraerse inmediatamente para que la nieve húmeda o la aguanieve se seque al aire."},
  {"id": 242, "s": 4, "q": "La gestión de riesgos, como parte del proceso de toma de decisiones aeronáuticas (ADM), en qué característica se basa para reducir los riesgos asociados con cada vuelo?", "o": ["El proceso mental de analizar toda la información en una situación particular y tomar una decisión oportuna sobre qué acción tomar.", "Aplicación de procedimientos de gestión de estrés y elementos de riesgo.", "Conciencia situacional, reconocimiento de problemas y buen juicio."], "a": 2, "e": "La gestión de riesgos es la parte del proceso de toma de decisiones que se basa en el conocimiento de la situación, el reconocimiento de problemas y el buen juicio para reducir los riesgos asociados con cada vuelo."},
  {"id": 243, "s": 4, "q": "La gestión de riesgos por parte del piloto:", "o": ["aplica solo en vuelos IFR de pasajeros / carga.", "requiere educación continua y formación académica certificada para comprender los principios.", "se mejora con la práctica y el uso constante de herramientas de gestión de riesgos."], "a": 2, "e": "La gestión piloto de riesgos se mejora con la práctica y el uso constante de herramientas de gestión de riesgos básicas y prácticas."},
  {"id": 244, "s": 4, "q": "La toma de decisiones aeronáuticas (ADM) es un:", "o": ["Enfoque sistemático del proceso mental utilizado por los pilotos para determinar consistentemente el mejor curso de acción para un conjunto dado de circunstancias.", "Proceso de toma de decisiones que se basa en el buen juicio para reducir los riesgos asociados con cada vuelo.", "Proceso mental de analizar toda la información en una situación particular y tomar una decisión oportuna sobre qué acción tomar."], "a": 0, "e": "ADM es un enfoque sistemático del proceso mental utilizado por los pilotos de aeronaves para determinar consistentemente el mejor curso de acción en respuesta a un conjunto dado de circunstancias."},
  {"id": 245, "s": 4, "q": "El proceso de toma de decisiones aeronáuticas (ADM) identifica los pasos involucrados en una buena toma de decisiones. Uno de estos pasos incluye un piloto:", "o": ["haciendo una evaluación racional de las acciones requeridas.", "desarrollando la actitud de 'cosas correctas\".", "identificando actitudes personales peligrosas para un vuelo seguro."], "a": 2, "e": "Los pasos para una buena toma de decisiones son: identificar las actitudes personales peligrosas para un vuelo seguro, aprender técnicas de modificación de la conducta, aprender a reconocer y afrontar el estrés, desarrollar habilidades de evaluación de riesgos, utilizar todos los recursos en una situación de múltiples tripulaciones y evaluar la eficacia de las propias habilidades de ADM."},
  {"id": 246, "s": 4, "q": "Ejemplos de trampas de comportamiento clásicas en las que pueden caer los pilotos experimentados son:", "o": ["asumir responsabilidades adicionales y hacer valer la autoridad de PIC.", "promover la conciencia situacional y luego los cambios necesarios en el comportamiento.", "completar un vuelo según lo planeado, complacer a los pasajeros, cumplir con los horarios y demostrar las 'cosas correctas\"."], "a": 2, "e": "Hay una serie de trampas de comportamiento clásicas en las que se sabe que caen los pilotos. Los pilotos, en particular aquellos con experiencia considerable, por regla general siempre intentan completar un vuelo según lo planeado, complacer a los pasajeros, cumplir con los horarios y, en general, demostrar que tienen las \"cosas adecuadas\". La respuesta (A) es incorrecta porque promover la conciencia de la situación y luego los cambios necesarios en el comportamiento y afirmar la autoridad del PIC son comportamientos piloto positivos. La respuesta (B) es incorrecta porque promover la conciencia de la situación y luego los cambios necesarios en el comportamiento y afirmar la autoridad del PIC son comportamientos piloto positivos."},
  {"id": 247, "s": 4, "q": "El impulso básico para que un piloto demuestre las “cosas correctas” puede tener un efecto adverso en la seguridad, por:", "o": ["una total indiferencia por cualquier curso de acción alternativo.", "generar tendencias que conducen a prácticas peligrosas, a menudo ilegales, y que pueden conducir a un percance.", "imponer una evaluación realista de las habilidades de pilotaje en condiciones estresantes."], "a": 1, "e": "Los pilotos, en particular aquellos con experiencia considerable, por regla general siempre intentan completar un vuelo según lo planeado, complacer a los pasajeros, cumplir con los horarios y, en general, demostrar que tienen las \"cosas adecuadas\". En última instancia, estas tendencias pueden conducir a prácticas que son peligrosas y, a menudo, ilegales, y pueden provocar un percance."},
  {"id": 248, "s": 4, "q": "La mayoría de los pilotos han sido víctimas de tendencias peligrosas o problemas de comportamiento en algún momento. Algunas de estas tendencias peligrosas o patrones de comportamiento que deben identificarse y eliminarse incluyen:", "o": ["deficiencias en las habilidades instrumentales y conocimiento de los sistemas o limitaciones de la aeronave.", "deficiencias en el desempeño por factores humanos como fatiga, enfermedad o problemas emocionales.", "la presión de los compañeros, la puesta en práctica, la pérdida de conciencia de la posición o la situación y el funcionamiento sin reservas de combustible adecuadas."], "a": 2, "e": "Hay una serie de trampas de comportamiento clásicas en las que se sabe que caen los pilotos. Estas tendencias peligrosas o patrones de comportamiento, que deben identificarse y eliminarse, incluyen: presión de grupo, mentalidad, llegar allí, síndrome de agacharse, correr rápido, seguir las reglas de vuelo visual en condiciones de instrumentos, ponerse detrás de la aeronave, pérdida de conciencia posicional o de situación, operar sin reservas de combustible adecuadas, descender por debajo de la altitud mínima en ruta, volar fuera de la envolvente, negligencia en la planificación del vuelo, inspecciones previas al vuelo, listas de verificación, etc."},
  {"id": 249, "s": 4, "q": "Una parte inicial del proceso de toma de decisiones aeronáuticas (ADM) implica:", "o": ["realizar una prueba de inventario de actitud peligrosa de autoevaluación.", "comprender el impulso para tener las 'cosas correctas'.", "obtener instrucción y experiencia de vuelo adecuadas durante el entrenamiento."], "a": 0, "e": "Cada estudiante de ADM debe tomar la Prueba de Inventario de Actitudes Peligrosas de Autoevaluación para obtener una perspectiva realista de sus actitudes hacia el vuelo."},
  {"id": 250, "s": 4, "q": "Las actitudes peligrosas que contribuyen a un mal juicio del piloto pueden contrarrestarse eficazmente mediante:", "o": ["reconocimiento temprano de pensamientos peligrosos.", "tomar medidas significativas para ser más asertivo con las actitudes.", "reorientar esa actitud peligrosa para que se puedan tomar las medidas adecuadas."], "a": 2, "e": "Los pilotos deben familiarizarse con un medio de contrarrestar las actitudes peligrosas con un pensamiento antídoto apropiado."},
  {"id": 251, "s": 4, "q": "¿Cuáles son algunas de las actitudes peligrosas que se abordan en la toma de decisiones aeronáuticas (ADM)?", "o": ["Anti-autoridad (no me digas), impulsividad (hacer algo rápido sin pensar), machista (puedo hacerlo).", "Gestión de riesgos, gestión del estrés y elementos de riesgo.", "Mala toma de decisiones, conciencia de la situación y juicio."], "a": 0, "e": "ADM aborda las siguientes cinco actitudes peligrosas: Anti-autoridad (¡no me lo digas!), Impulsividad (¡haz algo rápido!), Invulnerabilidad (no me sucederá a mí), Macho (puedo hacerlo), Resignación (¿de qué sirve?)."},
  {"id": 252, "s": 4, "q": "Cuando un piloto reconoce un pensamiento peligroso, debe corregirlo indicando el antídoto correspondiente. ¿Cuál de los siguientes es el antídoto para “MACHO”?", "o": ["Sigue las reglas. Suelen tener razón.", "No tan rápido. Piensa primero.", "Arriesgarse es una tontería."], "a": 2, "e": "Los pilotos machistas (puedo hacerlo) que siempre están tratando de demostrar que son mejores que nadie, piensan 'Yo puedo hacerlo, les mostraré'. Los pilotos con este tipo de actitud intentarán demostrar su valía asumiendo riesgos para impresionar a los demás. Si bien se cree que este patrón es una característica masculina, las mujeres son igualmente susceptibles. El antídoto para esta actitud es: correr riesgos es una tontería. La respuesta (A) es incorrecta porque este es el antídoto para una actitud anti-autoridad. La respuesta (B) es incorrecta porque es el antídoto para una actitud impulsiva."},
  {"id": 253, "s": 4, "q": "¿Cuál es el primer paso para neutralizar una actitud peligrosa en el proceso de ADM?", "o": ["Reconocimiento de invulnerabilidad en la situación.", "Lidiar con un juicio inadecuado.", "Reconocimiento de pensamientos peligrosos."], "a": 2, "e": "Las actitudes peligrosas que contribuyen a un mal juicio del piloto pueden contrarrestarse eficazmente reorientando esa actitud peligrosa para que se puedan tomar las medidas adecuadas. El reconocimiento de pensamientos peligrosos es el primer paso para neutralizarlos en el proceso ADM."},
  {"id": 254, "s": 4, "q": "¿Qué debe hacer un piloto al reconocer un pensamiento como peligroso?", "o": ["Evitar desarrollar este pensamiento peligroso.", "Desarrollar este pensamiento peligroso y continuar con una acción modificada.", "Etiquetar ese pensamiento como peligroso, luego corregirlo indicando el antídoto aprendido correspondiente."], "a": 2, "e": "Cuando un piloto reconoce un pensamiento como peligroso, el piloto debe etiquetar ese pensamiento como peligroso, luego corregir ese pensamiento indicando el antídoto correspondiente."},
  {"id": 255, "s": 4, "q": "¿Cómo deben los pilotos ayudar a controlar el estrés de la cabina?", "o": ["Ser consciente de las situaciones de estrés de la vida que son similares a las de volar.", "Condicionarse para relajarse y pensar racionalmente cuando aparece el estrés.", "Evitar situaciones que mejorarán sus habilidades para manejar las responsabilidades de la cabina."], "a": 1, "e": "Una buena gestión de la cabina comienza con una buena gestión del estrés de la vida. Muchas de las técnicas de afrontamiento del estrés que se practican para el manejo del estrés de la vida no suelen ser prácticas durante el vuelo. Más bien, debe condicionarse para relajarse y pensar racionalmente cuando aparece el estrés."},
  {"id": 256, "s": 4, "q": "¿Con qué comienza una buena gestión del estrés en la cabina?", "o": ["Saber qué causa el estrés.", "Eliminando problemas de vida y estrés en la cabina.", "Buen manejo del estrés de la vida."], "a": 2, "e": "Si espera tener éxito en reducir el estrés asociado con el manejo de crisis en el aire o con su trabajo, es esencial comenzar por hacer una evaluación personal del estrés en todas las áreas de su vida."},
  {"id": 257, "s": 4, "q": "Los pasajeros de un vuelo chárter han llegado casi una hora tarde a un vuelo que requiere reserva. ¿Cuál de las siguientes alternativas ilustra mejor la reacción de ANTIAUTORIDAD?", "o": ["Estas reglas de reserva no se aplican a este vuelo.", "Si el piloto se apresura, es posible que aún llegue a tiempo.", "El piloto no puede evitar que los pasajeros lleguen tarde."], "a": 0, "e": "La actitud anti-autoridad se encuentra en personas a las que no les gusta que nadie les diga qué hacer. En cierto sentido, están diciendo que nadie puede decirme qué hacer. Pueden estar resentidos de que alguien les diga qué hacer o pueden considerar las reglas, regulaciones y procedimientos como tontos O innecesarios."},
  {"id": 258, "s": 4, "q": "Mientras realiza una verificación operativa del sistema de presurización de la cabina, el piloto descubre que la función de control de velocidad no está operativa. Sabe que puede controlar manualmente la presión de la cabina, por lo que elige ignorar la discrepancia. ¿Cuál de las siguientes alternativas ilustra mejor la reacción de NVULNERABILIDAD?", "o": ["Qué es lo peor que podría pasar.", "Puedo manejar un pequeño problema como este.", "Es demasiado tarde para arreglarlo ahora."], "a": 0, "e": "La actitud de invulnerabilidad se encuentra en personas que sienten que los accidentes les suceden a los demás, pero nunca a ellos. Saben que pueden ocurrir accidentes y saben que cualquier persona puede verse afectada, pero nunca sienten ni creen realmente que se verán involucrados personalmente. Los pilotos que piensan de esta manera tienen más probabilidades de arriesgarse y aumentar el riesgo."},
  {"id": 259, "s": 4, "q": "El piloto y los pasajeros están ansiosos por llegar a su destino para una presentación comercial. Se informa que las tormentas eléctricas de nivel IV están alineadas a lo largo de su ruta de vuelo prevista. ¿Cuál de las siguientes alternativas ilustra mejor la reacción de IMPULSIVIDAD?", "o": ["Quieren darse prisa y ponerse en marcha, antes de que las cosas empeoren.", "Una tormenta no los detendrá.", "No pueden cambiar el clima, así que es mejor que se vayan."], "a": 0, "e": "La impulsividad es la actitud de las personas que frecuentemente sienten la necesidad de hacer algo, cualquier cosa, de forma inmediata. No se detienen a pensar en lo que están a punto de hacer, no seleccionan la mejor alternativa, y hacen lo primero que se les ocurre."},
  {"id": 260, "s": 4, "q": "Durante un vuelo IFR, un piloto emerge de una nube y se encuentra a 300 pies de un helicóptero. ¿Cuál de las siguientes alternativas ilustra mejor la reacción 'MACHO'?", "o": ["No está demasiado preocupado; todo va a estar bien.", "Vuela un poco más cerca, solo para mostrarle.", "Rápidamente se da la vuelta y se sumerge, para evitar la colisión."], "a": 1, "e": "La actitud Macho se encuentra en personas que siempre están tratando de demostrar que son mejores que nadie. Siempre están pensando 'puedo hacerlo, les mostraré'. Los pilotos con este tipo de actitud intentarán demostrar su valía asumiendo riesgos para impresionar a los demás."},
  {"id": 261, "s": 4, "q": "Cuando un piloto reconoce un pensamiento peligroso, debe corregirlo aplicando el antídoto correspondiente. ¿Cuál de los siguientes es el antídoto para la actitud peligrosa ANTI- AUTORIDAD?", "o": ["No tan rápido. Piensa primero.", "No me pasará a mí. Me podría pasar.", "No me lo digas. Sigue las reglas. Suelen tener razón."], "a": 2, "e": "La actitud anti-autoridad (¡no me lo digas!) Se encuentra en personas a las que no les gusta que nadie les diga qué hacer. El antídoto para esta actitud es: sigue las reglas, por lo general tienen razón. La respuesta (A) es incorrecta porque es el antídoto para la actitud impulsiva. La respuesta (B) es incorrecta porque es el antídoto para la actitud de invulnerabilidad."},
  {"id": 262, "s": 4, "q": "Un piloto y amigos volarán a un partido de fútbol fuera de la ciudad. Cuando llegan los pasajeros, el piloto determina que estarán por encima del peso bruto máximo para el despegue con la carga de combustible existente. ¿Cuál de las siguientes alternativas ilustra mejor la reacción de la RESIGNACIÓN?", "o": ["Bueno, nadie le dijo sobre el peso extra.", "El peso y el equilibrio es una formalidad impuesta a los pilotos por la AAC", "No puede esperar para descargar combustible, tienen que llegar a tiempo."], "a": 0, "e": "La actitud de resignación se encuentra en los pilotos que piensan, '¿de qué sirve?' No se ven a sí mismos como capaces de hacer una gran diferencia en lo que les sucede. Cuando las cosas van bien, el piloto tiende a pensar que es buena suerte. Cuando las cosas van mal, el piloto puede sentir que alguien quiere atraparlos o atribuirlo a la mala suerte. El piloto dejará la acción a otros, para bien o para mal. A veces, estos pilotos incluso aceptarán solicitudes poco razonables solo para ser un 'buen tipo\"."},
  {"id": 263, "s": 4, "q": "¿Cuál de los siguientes es el paso final del modelo Decide para una gestión de riesgos eficaz y toma de decisiones aeronáuticas?", "o": ["Estimar.", "Evaluar.", "Eliminar."], "a": 1, "e": "El modelo DECIDE, que consta de un proceso de seis pasos, está destinado a proporcionar al piloto una forma lógica de abordar la toma de decisiones: Detectar, Estimar, Elegir, Identificar, Hacer y Evaluar."},
  {"id": 264, "s": 4, "q": "¿Cuál de los siguientes es el primer paso del modelo Decide para la gestión eficaz de riesgos y la toma de decisiones aeronáuticas?", "o": ["Detectar.", "Identificar.", "Evaluar."], "a": 0, "e": "El modelo DECIDE, que consta de un proceso de seis pasos, está destinado a proporcionar al piloto una forma lógica de abordar la toma de decisiones: Detectar, Estimar, Elegir, Identificar, Hacer y Evaluar."},
  {"id": 265, "s": 4, "q": "El modelo Decide se compone de un proceso de 6 pasos para proporcionar al piloto una forma lógica de abordar la toma de decisiones aeronáuticas. Estos pasos son:", "o": ["detectar, estimar, elegir, identificar, hacer y evaluar.", "determinar, evaluar, elegir, identificar, hacer y eliminar.", "determinar, eliminar, elegir, identificar, detectar y evaluar."], "a": 0, "e": "El modelo DECIDE, que consta de un proceso de seis pasos, está destinado a proporcionar al piloto una forma lógica de abordar la toma de decisiones: Detectar, Estimar, Elegir, Identificar, Hacer y Evaluar."},
  {"id": 266, "s": 4, "q": "El marcador de “final de calle de rodaje”:", "o": ["Indica que la calle de rodaje no continúa.", "Identifica el área donde están prohibidas las aeronaves.", "Proporciona una dirección de rodaje general a la calle de rodaje nombrada."], "a": 0, "e": "Los marcadores de final de calle de rodaje se utilizan para indicar que la calle de rodaje no continúa. La respuesta (B) es incorrecta porque el movimiento periférico no se detecta fácilmente, especialmente en condiciones adversas; por lo tanto, esta no sería una técnica de exploración eficaz."},
  {"id": 267, "s": 4, "q": "Una vez que un piloto al mando acepta una autorización de aterrizaje y espera corta (LAHSO), la autorización debe cumplirse, al igual que cualquier otra autorización ATC, a menos que:", "o": ["se obtiene una autorización modificada o se produce una emergencia.", "el viento cambia o la distancia de aterrizaje disponible disminuye.", "la distancia de aterrizaje disponible disminuye o aumenta la densidad de altitud."], "a": 0, "e": "Una vez aceptado, se debe cumplir con un LAHSO a menos que se obtenga una autorización enmendada o se produzca una emergencia."},
  {"id": 268, "s": 4, "q": "Al girar hacia una calle de rodaje desde otra calle de rodaje, ¿cuál es el propósito de la señal direccional de la calle de rodaje?", "o": ["Indica dirección a la pista de despegue.", "Indica la designación y la dirección de la calle de salida de la pista.", "Indica la designación y la dirección de la calle de rodaje que sale de una intersección."], "a": 2, "e": "El letrero direccional de la calle de rodaje identifica las designaciones de la (s) calle (s) de rodaje que se cruzan y que salen de la intersección en las que normalmente se esperaría que un piloto virara o esperara antes. La respuesta (A) es incorrecta porque este es el propósito de la señal de ubicación de la pista. La respuesta (B) es incorrecta porque este es el propósito de la señal de destino."},
  {"id": 269, "s": 4, "q": "¿Qué debe considerar al planear aterrizar en otro aeropuerto?", "o": ["Aterrizar y realizar procedimientos cortos.", "Compruebe si hay marcas de aterrizaje y aeropuerto.", "iluminación del aeropuerto mediante cableado continuo."], "a": 0, "e": "Como parte del proceso de planificación previa al vuelo de un piloto, los pilotos deben determinar si su aeropuerto de destino tiene LAHSO. Si es así, su proceso de planificación previa al vuelo debe incluir una evaluación de qué combinaciones de LAHSO funcionarían para ellos dada la distancia de aterrizaje requerida de su aeronave. Una buena toma de decisiones del piloto es saber de antemano si se puede aceptar una autorización de LAHSO si se ofrece."},
  {"id": 270, "s": 4, "q": "El letrero de posición de espera en la pista se encuentra en:", "o": ["pistas que se cruzan con otras pistas.", "calles de rodaje protegidas de una aeronave que se aproxima a una pista.", "pistas que se cruzan con otras calles de rodaje."], "a": 0, "e": "Los letreros de instrucción obligatoria se utilizan para indicar una entrada a una pista o área crítica y áreas donde una aeronave tiene prohibido ingresar. El letrero de posición de espera en la pista se encuentra en el puesto de espera en las calles de rodaje que se cruzan con una pista o en las que se cruzan con otras pistas."},
  {"id": 271, "s": 4, "q": "Las \"marcas de posición de espera en la pista\" en calles de rodaje:", "o": ["Identifican dónde se prohíbe el rodaje de las aeronaves cuando el control de tierra no los autoriza a continuar.", "Identifican dónde se supone que deben detenerse las aeronaves cuando no están autorizadas para avanzar hacia la pista.", "Permiten un permiso de aeronave en la pista."], "a": 1, "e": "Las marcas de posición de espera en la pista indican dónde se supone que debe detenerse una aeronave. Cuando se usa en una calle de rodaje, estas marcas identifican los lugares donde se supone que una aeronave debe detenerse cuando no tiene autorización para avanzar hacia la pista."},
  {"id": 272, "s": 4, "q": "La marca de \"barra de demarcación amarilla\" indica:", "o": ["La pista con umbral desplazado que precede a la pista.", "Una línea de espera desde una calle de rodaje hasta una pista.", "El comienzo de la pista disponible para aterrizar en el lado de aproximación."], "a": 0, "e": "Una barra de demarcación delimita una pista con un umbral desplazado de una pista explosiva, una parada o una calle de rodaje que precede a la pista. Una barra de demarcación tiene 3 pies (1 m) de ancho y es amarilla, ya que no está ubicada en la pista."},
  {"id": 273, "s": 5, "q": "Todo proceso físico del tiempo va acompañado o es el resultado de:", "o": ["una transferencia de calor.", "el movimiento del aire.", "un diferencial de presión."], "a": 0, "e": "La cantidad de energía solar que recibe cualquier región varía con la hora del día, con las estaciones y con la latitud. Estas diferencias en la energía solar crean variaciones de temperatura. Las temperaturas también varían con las diferencias de superficie topográfica y con la altitud. Esta variación de temperatura, o intercambio de calor, crea fuerzas que impulsan a la atmósfera en su interminable movimiento."},
  {"id": 274, "s": 5, "q": "¿Qué condiciones son favorables para la formación de una inversión de temperatura en superficie?", "o": ["Noches despejadas y frescas con viento en calma o ligero.", "Zona de aire inestable que transfiere rápidamente el calor de la superficie.", "Amplias zonas de cúmulos con bases lisas y niveladas a la misma altura."], "a": 0, "e": "A menudo se produce una inversión cerca del suelo en las noches claras y frescas cuando el viento es ligero. La respuesta (B) es incorrecta porque el aire cerca de la superficie debe ser estable para permitir que el suelo fresco baje la temperatura del aire circundante. La respuesta (C) es incorrecta porque los cúmulos están muy por encima de la superficie."},
  {"id": 275, "s": 5, "q": "¿Qué causa el viento?", "o": ["La rotación de la tierra.", "Modificación de la masa de aire.", "Diferencias de presión."], "a": 2, "e": "Las diferencias de temperatura crean diferencias de presión. Estas diferencias de presión impulsan un complejo sistema de vientos en un intento interminable de alcanzar el equilibrio."},
  {"id": 276, "s": 5, "q": "La altitud por densidad es la distancia vertical sobre el nivel medio del mar en la atmósfera estándar en la que:", "o": ["La altitud por presión se corrige para la temperatura estándar.", "Una densidad atmosférica determinada.", "Se consideran la temperatura, la presión, la altitud y la humedad."], "a": 1, "e": "La altitud por densidad es la distancia vertical sobre el nivel del mar en la atmósfera estándar en la que se encuentra una densidad determinada. La densidad del aire tiene efectos significativos en el rendimiento del avión."},
  {"id": 277, "s": 5, "q": "En el hemisferio norte, el viento se desvía hacia la:", "o": ["derecha por la fuerza de Coriolis.", "derecha por la fricción de la superficie.", "izquierda por la fuerza de Coriolis."], "a": 0, "e": "La fuerza de Coriolis desvía el aire hacia la derecha en el hemisferio norte."},
  {"id": 278, "s": 5, "q": "¿Por qué el viento tiende a fluir en paralelo a las isobaras de presión por encima del nivelde fricción?", "o": ["La fuerza de Coriolis tiende a contrarrestar el gradiente de presión horizontal.", "La fuerza de Coriolis actúa perpendicularmente a una línea que une los máximos y los mínimos.", "La fricción del aire con la tierra desvía el aire perpendicularmente al gradiente de presión."], "a": 0, "e": "La fuerza del gradiente de presión impulsa el viento y es perpendicular a las isobaras. Cuando se establece por primera vez una fuerza de gradiente de presión, el viento comienza a soplar de mayor a menor presión directamente a través de las isobaras. Sin embargo, en el momento en que el aire comienza a moverse, la fuerza de Coriolis lo desvía hacia la derecha. Por lo tanto, el viento se desvía a 90° y se sitúa en paralelo a las isobaras o contornos. En este momento, la fuerza de Coriolis equilibra exactamente la fuerza del gradiente de presión. Con las fuerzas en equilibrio, el viento permanecerá paralelo a las isobaras o contornos."},
  {"id": 279, "s": 5, "q": "El sistema de vientos asociado a una zona de bajas presiones en el hemisferio norte es:", "o": ["un anticiclón y es causado por el aire frío descendente.", "un ciclón y es causado por la fuerza de Coriolis.", "un anticiclón y es causado por la fuerza de Coriolis."], "a": 1, "e": "Las tormentas que se desarrollan entre los sistemas de alta presión se caracterizan por la baja presión. Como los vientos tratan de soplar hacia el centro de la baja presión, también se desvían hacia la derecha. Así, el viento alrededor de una zona de baja presión se mueve en sentido contrario a las agujas del reloj. La baja presión y su sistema de vientos es un ciclón. La respuesta (A) es incorrecta porque describen un sistema de altas presiones. La respuesta (C) es incorrecta porque describen un sistema de altas presiones."},
  {"id": 280, "s": 5, "q": "Con respecto a los patrones de flujo de viento mostrados en los gráficos de análisis de superficie; cuando las isobaras son:", "o": ["Cercanas y la fuerza del gradiente de presión es leve y las velocidades del viento son más débiles.", "Lejanas y la fuerza del gradiente de presión es mayor y las velocidades del viento son más fuertes.", "Cercanas y la fuerza del gradiente de presión es mayor y las velocidades del viento son más fuertes."], "a": 2, "e": "Cuanto más estrecha sea la separación de las isobaras, más fuerte será la fuerza del gradiente de presión. Cuanto más fuerte es la fuerza del gradiente de presión, más fuerte es el viento. Por lo tanto, las isobaras muy espaciadas significan vientos fuertes y ligeros."},
  {"id": 281, "s": 5, "q": "¿Qué impide que el aire fluya directamente de las zonas de alta presión a las de baja presión?", "o": ["Fuerza de Coriolis.", "Fricción superficial.", "Fuerza de gradiente de presión."], "a": 0, "e": "La fuerza del gradiente de presión impulsa el viento y es perpendicular a las isobaras de presión. Cuando se establece por primera vez una fuerza de gradiente de presión, el viento comienza a soplar de mayor a menor presión directamente a través de las isobaras. Sin embargo, en el momento en que el aire comienza a moverse, la fuerza de Coriolis lo desvía hacia la derecha. Después, el viento se desvía 90° y se sitúa en paralelo a las isobaras o contornos. En este momento, la fuerza de Coriolis equilibra exactamente la fuerza del gradiente de presión. Con las fuerzas en equilibrio, el viento permanecerá paralelo a las isobaras o contornos. La respuesta (B) es incorrecta porque la fricción de la superficie mueve el aire de máximos a mínimos valores, disminuyendo la velocidad del viento, lo que disminuye el efecto de la fuerza de Coriolis. La respuesta (C) es incorrecta porque la fuerza del gradiente de presión provoca el movimiento inicial desde las zonas de alta presión hacia las de baja presión."},
  {"id": 282, "s": 5, "q": "Mientras se vuela a campo traviesa, en el hemisferio norte, se experimenta un viento cruzado continuo a la izquierda el cual está asociado a un sistema de viento alto. Esto indica que usted:", "o": ["está volando hacia una zona de condiciones generalmente desfavorables.", "se encuentra volando desde una zona con condiciones meteorológicas desfavorables.", "no se puede determinar las condicione meteorológicas sin conocer los cambios de presión."], "a": 0, "e": "Cuando se vuela en el hemisferio norte, experimentar un viento cruzado continuo a la izquierda indica que se está entrando en un sistema bajo presión. El viento sopla en sentido contrario a las agujas del reloj, lo que explica un viento cruzado a la izquierda. En general, un sistema de bajas presiones se asocia con el mal tiempo. La respuesta (B) es incorrecta porque si se ha volado desde una zona de condiciones meteorológicas desfavorables, lo que significa que se tendría un viento cruzado a la derecha. La respuesta (C) es incorrecta porque el viento puede proporcionar una indicación de los cambios de presión y del tiempo."},
  {"id": 283, "s": 5, "q": "¿Qué afirmación es cierta con respecto a un sistema de alta o baja presión?", "o": ["Una zona de alta presión o cresta es un área de aire ascendente.", "Una zona de baja presión o vaguada es una zona de aire descendente.", "Una zona de alta presión o cresta es una zona de aire descendente."], "a": 2, "e": "El aire que sale de una presión alta o cresta reduce la cantidad de aire. Las crestas, por tanto, son zonas de aire descendente. La respuesta (A) es incorrecta porque el aire de alta presión desciende. La respuesta (B) es incorrecta porque el aire de baja presión asciende."},
  {"id": 284, "s": 5, "q": "¿Qué afirmación es cierta respecto a los sistemas de alta o baja presión?", "o": ["Una zona de alta presión o cresta es un área de aire ascendente.", "Una zona de bajas presiones o vaguada es una zona de aire ascendente.", "Tanto las zonas de alta como de baja presión se caracterizan por el aire descendente."], "a": 1, "e": "En la superficie, cuando el aire converge en una baja presión, no puede ir hacia afuera en contra del gradiente de presión, ni puede ir hacia abajo en el suelo. Debe ir hacia arriba. Por lo tanto, una baja o vaguada es una zona de aire ascendente. La respuesta (A) es incorrecta porque el aire de alta presión desciende y el de baja presión asciende. La respuesta (C) es incorrecta porque el aire de alta presión desciende y el de baja presión sube."},
  {"id": 285, "s": 5, "q": "Cuando se vuela hacia una zona de bajas presiones en el hemisferio norte, la dirección y la velocidad del viento será:", "o": ["a la izquierda y disminuyendo.", "a la izquierda y aumentando.", "derecha y disminuyendo."], "a": 1, "e": "En el hemisferio norte, el viento alrededor de una zona de baja es contrario a las agujas del reloj. Por lo tanto, al volar hacia el centro de una zona de baja, el viento será por la izquierda. Al volar hacia un sistema de presión, el espacio entre las isobaras disminuirá al aumentar la velocidad del viento."},
  {"id": 286, "s": 5, "q": "¿Qué afirmación es cierta en cuanto a la temperatura real del aire y la dispersión de la temperatura del punto de rocío? La dispersión de la temperatura:", "o": ["disminuye a medida que la humedad relativa disminuye", "disminuye a medida que aumenta la humedad relativa.", "aumenta a medida que aumenta la humedad relativa."], "a": 1, "e": "La diferencia entre la temperatura del aire y la temperatura del punto de rocío se denomina \"dispersión\". A medida que la dispersión es menor, la humedad relativa aumenta."},
  {"id": 287, "s": 5, "q": "La circulación general del aire asociada a una zona de altas presiones en el hemisferio norte es:", "o": ["hacia fuera, hacia abajo y en el sentido de las agujas del reloj.", "hacia fuera, hacia arriba y en el sentido de las agujas del reloj.", "hacia adentro, hacia abajo y en el sentido de las agujas del reloj."], "a": 0, "e": "Cuando el aire intenta salir de la alta presión, es desviado hacia la derecha por la fuerza de Coriolis. Así, el viento alrededor de una alta sopla en el sentido de las agujas del reloj. El aire que sale de una zona de alta presión agota la cantidad de aire. Las crestas son zonas de aire descendente."},
  {"id": 288, "s": 5, "q": "La mejor descripción de virga es:", "o": ["serpentinas de precipitación que se arrastran por debajo de las nubes y que se evaporan antes de llegar al suelo.", "torrentes de nubes de pared que se arrastran por debajo de los cumulonimbos y que se disipan antes de llegar al suelo.", "zonas turbulentas bajo las nubes cumulonimbos."], "a": 0, "e": "El término \"virga\" se refiere a las corrientes de precipitación que se arrastran por debajo de las nubes y que se evaporan antes de llegar al suelo. La respuesta (B) es incorrecta porque la virga suele ser fina y difusa. La respuesta (C) es incorrecta porque la virga es una forma de precipitación."},
  {"id": 289, "s": 5, "q": "La humedad se añade al aire mediante:", "o": ["sublimación y condensación.", "evaporación y condensación.", "evaporación y sublimación."], "a": 2, "e": "La evaporación es el cambio de agua líquida a vapor de agua invisible. La sublimación es el cambio del hielo directamente a vapor de agua. La respuesta (A) es incorrecta porque la condensación elimina la humedad del aire. La respuesta (B) es incorrecta porque la condensación elimina la humedad del aire."},
  {"id": 290, "s": 5, "q": "Los gránulos de hielo encontrados durante el vuelo normalmente son una prueba de que:", "o": ["un frente cálido ha pasado.", "un frente cálido está a punto de pasar.", "hay tormentas eléctricas en la zona."], "a": 1, "e": "La lluvia que cae desde el aire cálido de arriba a través del aire más frío de abajo puede congelarse durante su descenso, cayendo en forma de gránulos de hielo. Esto puede ocurrir siempre que exista una Capa de aire más cálido por encima de una capa más fría (es decir, un frente cálido o un frente frío). La respuesta (A) es incorrecta porque después del paso del frente cálido ya no habrá una capa de aire cálido sobre una capa de aire frio, lo cual es necesario para la formación de bolitas de hielo. La respuesta (C) es incorrecta porque los gránulos de hielo no provienen necesariamente de las tormentas eléctricas, sino de la lluvia que se congela a mayor altura."},
  {"id": 291, "s": 5, "q": "¿Qué indica encontrar granos de hielo a 8,000 pies?", "o": ["Lluvia helada a mayor altitud.", "Se está acercando una zona de tormentas.", "Se encontrará con granizo si continua su vuelo."], "a": 0, "e": "La lluvia que cae desde el aire cálido de arriba a través del aire más frío de abajo puede congelarse durante su descenso, cayendo en forma de gránulos de hielo. Esto puede ocurrir siempre que exista Una Capa de aire más cálido por encima de una capa más fría (es decir, un frente cálido o un frente frío). La respuesta (B) es incorrecta porque la lluvia helada puede producirse sin tormentas eléctricas. La respuesta (C) es incorrecta porque las bolas de hielo son una forma de granizo."},
  {"id": 292, "s": 5, "q": "Los gránulos de hielo encontrados durante el vuelo son normalmente una prueba de que:", "o": ["ha pasado un frente frío.", "hay tormentas eléctricas en la zona.", "la lluvia helada existe a mayor altitud."], "a": 2, "e": "La lluvia que cae desde el aire cálido de arriba a través del aire más frío de abajo puede congelarse durante su descenso, cayendo en forma de gránulos de hielo. Esto puede ocurrir siempre que exista Una capa de aire más cálido por encima de una capa más fría (es decir, un frente cálido o un frente frio)."},
  {"id": 293, "s": 5, "q": "Cuando se pronostica un aire condicionalmente inestable con alto contenido de humedady una temperatura superficial muy cálida ¿Qué tipo de tiempo se puede esperar?", "o": ["Fuertes corrientes ascendentes y nubes grandes.", "Visibilidad restringida cerca de la superficie en una zona amplia.", "Fuertes corrientes ascendentes y nubes de desarrollo vertical."], "a": 2, "e": "Las características del aire inestable son las nubes cumulonimbos, las precipitaciones lluviosas, la turbulencia y la buena visibilidad, excepto en los obstáculos que soplan. La respuesta (A) es incorrecta porque las nubes de gran tamaño son características del aire estable. La respuesta (B) es incorrecta porque la visibilidad restringida es característica del aire estable."},
  {"id": 294, "s": 5, "q": "¿Cuál es la base aproximada de los cúmulos si la temperatura a 2,000 Pies MSL es de 10 °C y el punto de rocío es de 1 °C?", "o": ["3,000 Pies MSL.", "4,000 Pies MSL.", "6,000 Pies MSL."], "a": 2, "e": "En una corriente de convección, la temperatura y el punto de rocío convergen a unos 2,5 °C por cada 1.000 pies. Una estimación de las bases de las nubes convectivas se puede encontrar dividiendo la convergencia en la dispersión de la temperatura. 1. (10 - 1) ÷ 2,5 = 3,6 x 1.000 = 3.600 pies de base 1. 2.000 pies MSL + 3.600 pies AGL = 5.600 pies MSL."},
  {"id": 295, "s": 5, "q": "Si las nubes se forman como resultado de un aire muy estable y húmedo que se ve obligado a ascender por la ladera de una montaña, las nubes serán:", "o": ["nubes tipo cirrus sin desarrollo vertical ni turbulencia.", "nubes tipo cúmulo con considerable desarrollo vertical y turbulencia.", "nubes tipo estratos con poco desarrollo vertical y poca o ninguna turbulencia."], "a": 2, "e": "El aire estable se resiste al movimiento ascendente; por lo tanto, se producen nubes estratificadas. La respuesta (A) es incorrecta porque las nubes tipo cirrus, son altos y están compuestos por cristales de hielo. La respuesta (B) es incorrecta porque el aire inestable provoca un desarrollo vertical."},
  {"id": 296, "s": 5, "q": "¿Qué determina la estructura o el tipo de nubes que se formarán como consecuencia del ascenso forzado del aire?", "o": ["El método por el que se eleva el aire.", "La estabilidad del aire antes de que se produzca la elevación.", "La humedad relativa del aire después de la elevación."], "a": 1, "e": "El hecho de que el aire sea estable o inestable dentro de una capa determina en gran medida la estructura de las nubes. Cuando el aire estable es forzado hacia arriba, el aire tiende a retener el flujo horizontal y cualquier nubosidad es plana y estratificada. Cuando el aire inestable es forzado hacia arriba, la perturbación crece y cualquier nubosidad resultante muestra un amplio desarrollo vertical."},
  {"id": 297, "s": 5, "q": "¿Cuáles son las características del aire estable?", "o": ["Buena visibilidad; precipitación constante; nubes estratos.", "Poca visibilidad; precipitaciones constantes; nubes estratos.", "Poca visibilidad; precipitaciones intermitentes; cúmulos de nubes."], "a": 1, "e": "Las características del aire estable son las nubes estratiformes y la niebla, las precipitaciones continuas, el aire suave y la visibilidad de buena a mala en la niebla y el humo. La respuesta (A) es incorrecta porque la buena visibilidad es característica del aire inestable. La respuesta (C) es incorrecta porque las precipitaciones intermitentes y los cúmulos son característicos del aire inestable."},
  {"id": 298, "s": 5, "q": "¿Cuál de las siguientes disminuiría la estabilidad de una masa de aire?", "o": ["Calentamiento desde abajo.", "Enfriamiento desde abajo.", "Disminución del vapor de agua."], "a": 0, "e": "Un cambio en la tasa de lapso de la temperatura ambiente de una masa de aire determinará su estabilidad. El calentamiento o enfriamiento de la superficie en la parte superior puede hacer que el aire sea más inestable. La respuesta (B) es incorrecta porque el enfriamiento desde abajo aumenta la estabilidad. La respuesta (C) es incorrecta porque una disminución del vapor de agua reduce el punto de rocío del aire, pero no afecta a la estabilidad."},
  {"id": 299, "s": 5, "q": "¿A partir de que medición de la atmósfera se puede determinar la estabilidad?", "o": ["Presión atmosférica.", "El gradiente térmico vertical.", "El gradiente adiabático seco."], "a": 1, "e": "Un cambio en la tasa de lapso de la temperatura ambiente de una masa de aire determinará su estabilidad. El calentamiento o enfriamiento de la superficie en el aire puede hacer que el aire sea más inestable. Por otro lado, el enfriamiento o el calentamiento de la superficie en el aire suele inclinar la balanza hacia una mayor estabilidad. La respuesta (A) es incorrecta porque la presión atmosférica afecta a la temperatura y a los movimientos del aire, pero no determina la estabilidad de la atmósfera. La respuesta (C) es incorrecta porque la tasa de lapso adiabático seco es una tasa constante."},
  {"id": 300, "s": 5, "q": "¿Qué tipo de tiempo se puede esperar del aire húmedo e inestable y de las temperaturas superficiales muy cálidas?", "o": ["Nieblas y nubes bajas.", "Precipitaciones fuertes y continuas.", "Fuertes corrientes ascendentes y nubes cumulonimbos."], "a": 2, "e": "Las características del aire inestable son las nubes cumulonimbo, las precipitaciones lluviosas, la turbulencia y la buena visibilidad, excepto en los obstáculos que soplan. La respuesta (A) es incorrecta porque la niebla y los estratos son características del aire estable. La respuesta (B) es incorrecta porque las precipitaciones continuas son características del aire estable."},
  {"id": 301, "s": 5, "q": "¿Qué aumentaría la estabilidad de una masa de aire?", "o": ["Calentamiento desde abajo.", "Enfriamiento desde abajo.", "Disminución del vapor de agua."], "a": 1, "e": "Un cambio en la tasa de lapso de la temperatura ambiente de una masa de aire determinará su estabilidad. El enfriamiento o calentamiento de la superficie en el aire suele inclinar la balanza hacia una mayor estabilidad. La respuesta (A) es incorrecta porque el calentamiento desde abajo disminuye la estabilidad. La respuesta (C) es incorrecta porque una disminución del vapor de agua reduce el punto de rocío del aire, pero no afecta a la estabilidad."},
  {"id": 302, "s": 5, "q": "Las condiciones necesarias para la formación de nubes estratiformes son una acción de elevación y:", "o": ["aire inestable y seco.", "aire estable y húmedo.", "aire inestable y húmedo."], "a": 1, "e": "El aire estable y húmedo y el enfriamiento adiabático son necesarios para formar nubes estratiformes."},
  {"id": 303, "s": 5, "q": "¿Qué tipos de nubes indicarían una turbulencia convectiva?", "o": ["Nubes tipo cirrus.", "Nubes tipo nimbostrato.", "Nubes tipo cúmulos."], "a": 2, "e": "Los cúmulos de buen tiempo, que suelen verse en las tardes soleadas, son señales en el cielo que indican turbulencia convectiva. Las alturas verticales van desde los cúmulos de buen tiempo poco profundos hasta los gigantescos cumulonimbos de tormenta. La respuesta (A) es incorrecta porque los cirros son nubes altas formadas por cristales de hielo y no se generan por ninguna actividad convectiva. La respuesta (B) es incorrecta porque las nubes nimbostratos son nubes planas de lluvia, formadas en aire estable y no producen actividad convectiva ni turbulencia."},
  {"id": 304, "s": 5, "q": "La presencia de nubes lenticulares altocúmulos es un buen indicio de:", "o": ["formación de hielo lenticular en aire tranquilo.", "turbulencia muy fuerte.", "condiciones de fuerte helada."], "a": 1, "e": "Las nubes lenticulares en pie sugieren una onda de montaña; espere turbulencias a muchos kilómetros a sotavento de las montañas."},
  {"id": 305, "s": 5, "q": "La formación de nubes predominantemente estratiformes o predominantemente cumulonimbos depende de:", "o": ["la fuente de elevación.", "la estabilidad del aire que se eleva.", "la temperatura del aire que se eleva."], "a": 1, "e": "Cuando el aire estable es forzado a subir, el aire tiende a retener el flujo horizontal. Cualquier nubosidad es plana y estratificada. Cuando el aire inestable es forzado hacia arriba, la perturbación crece, y cualquier nubosidad resultante muestra un amplio desarrollo vertical. La respuesta (A) es incorrecta porque la estabilidad del aire determina el tipo de nubes que se forman. La respuesta (C) es incorrecta porque la temperatura del aire determina la altitud de las nubes que se forman."},
  {"id": 306, "s": 5, "q": "¿Qué combinación de variables meteorológicas produciría probablemente nubes de tipo cumuliforme, buena visibilidad y lluvia torrencial?", "o": ["Aire estable, húmedo y elevación orográfica.", "Aire inestable, húmedo y elevación orográfica.", "Aire inestable, húmedo y sin mecanismo de elevación."], "a": 1, "e": "Las características del aire inestable y húmedo son las nubes cumuliformes, las precipitaciones lluviosas, la turbulencia y la buena visibilidad, excepto en los obstáculos que soplan. La \"elevación orográfica\" es la acción de elevación producida por un objeto físico, como la ladera de una montaña, que fuerza el aire hacia arriba. La respuesta (A) es incorrecta porque si el aire es estable, se formarán precipitaciones constantes y nubes estratiformes. La respuesta (C) es incorrecta porque debe existir un mecanismo de elevación para que se formen nubes cumuliformes y lluvias."},
  {"id": 307, "s": 5, "q": "¿Cuál es una característica del aire estable?", "o": ["Nubes estratiformes.", "Cúmulos de buen tiempo.", "Disminución rápida de la temperatura con la altitud."], "a": 0, "e": "Las características del aire estable son las nubes estratiformes y la niebla, las precipitaciones continuas, el aire suave y la visibilidad de regular a mala en la bruma y el humo. La respuesta (B) es incorrecta porque los cúmulos son característicos del aire inestable. La respuesta (C) es incorrecta porque un rápido descenso de la temperatura con la altitud indica una alta tasa de lapso y es característico del aire inestable."},
  {"id": 308, "s": 5, "q": "Una masa de aire húmeda e inestable se caracteriza por:", "o": ["Poca visibilidad y aire suave.", "Nubes cumulonimbos y precipitaciones en chubasco.", "Nubes estratiformes y precipitaciones continuas."], "a": 1, "e": "Las características del aire inestable son las nubes cumuliformes, las precipitaciones en chubasco, la turbulencia y la buena visibilidad, excepto por turbulencias mecánicas. La respuesta (A) es incorrecta porque la mala visibilidad y el aire suave son características del aire estable. La respuesta (C) es incorrecta porque las nubes estratiformes y las precipitaciones continuas son características del aire estable."},
  {"id": 309, "s": 5, "q": "¿Cuáles son las características de una atmosfera inestable?", "o": ["Una masa de aire fresco y seco.", "Una masa de aire cálido y húmedo.", "Aire descendente en el hemisferio norte."], "a": 1, "e": "Las características del aire inestable son las nubes negras, las precipitaciones lluviosas, la turbulencia y la buena visibilidad, excepto en los obstáculos que soplan."},
  {"id": 310, "s": 5, "q": "Cuando una masa de aire es estable ¿cuál de estas condiciones es más probable que exista?", "o": ["Numerosos cúmulos y cumulonimbos.", "Cambio de turbulencia de moderada a severa en los niveles inferiores.", "Calima, el polvo, la bruma, etc. Se concentran en los niveles inferiores con la consiguiente mala visibilidad."], "a": 2, "e": "Las características típicas de una masa de aire estable son: - Nubes estratiformes y niebla - Precipitaciones continuas - Aire suave - Visibilidad de regular a mala por bruma y calima."},
  {"id": 311, "s": 5, "q": "¿Cuál es una característica del aire estable?", "o": ["Nubes cumulonimbo.", "Excelente visibilidad.", "Visibilidad restringida."], "a": 2, "e": "Las características típicas de una masa de aire estable son: -Nubes estratiformes y niebla -Precipitaciones continuas -Aire suave Visibilidad de regular o mala en la niebla"},
  {"id": 312, "s": 5, "q": "¿Cuál es una característica típica de una masa de aire estable?", "o": ["Nubes cumulonimbos.", "Precipitaciones en chubasco.", "Precipitaciones continuas."], "a": 2, "e": "Las características típicas de una masa de aire estable son: - Nubes estratiformes y niebla - Precipitaciones continuas - Aire suave - Visibilidad de regular a mala en la niebla y la calima."},
  {"id": 313, "s": 5, "q": "¿Cuál afirmación es verdadera sobre la oclusión de un frente frío? El aire por delante del frente cálido:", "o": ["es más frío que el aire que está detrás del frente frío que lo adelanta.", "es más cálido que el aire detrás del frente frío que lo sobrepasa.", "tiene la misma temperatura que el aire que está detrás del frente frío que lo adelanta."], "a": 1, "e": "En la oclusión del frente frío, el aire más frío está debajo del frente frío. Cuando sobrepasa el frente cálido, levanta el frente cálido en el aire y el aire frío sustituye al aire frío en la superficie."},
  {"id": 314, "s": 5, "q": "¿Cuáles son las características de una masa de aire frío que se desplaza sobre una superficie cálida?", "o": ["Nubes cumulonimbos, turbulencia y poca visibilidad.", "Nubes cumulonimbos, turbulencia y buena visibilidad.", "Nubes estratiformes, aire suave y poca visibilidad."], "a": 1, "e": "El aire frío que se mueve sobre una superficie cálida se calienta desde abajo, generando inestabilidad y aumentando la posibilidad de chubascos. El aire inestable se caracteriza por las nubes cumuliformes, las turbulencias y la buena visibilidad."},
  {"id": 315, "s": 5, "q": "Las condiciones necesarias para la formación de cumulonimbos son una acción de elevación y:", "o": ["aire inestable y seco.", "aire estable y húmedo.", "aire inestable y húmedo."], "a": 2, "e": "Para que se formen los cumulonimbos, el aire debe tener suficiente vapor de agua, una tasa de lapso inestable y un impulso inicial hacia arriba (elevación) para poner en marcha el proceso de la tormenta."},
  {"id": 316, "s": 5, "q": "La niebla producida por la actividad frontal es el resultado de la saturación debido a:", "o": ["enfriamiento nocturno.", "enfriamiento adiabático.", "evaporación de las precipitaciones."], "a": 2, "e": "Cuando la lluvia o llovizna relativamente cálida cae a través de aire frío, la evaporación de la precipitación satura el aire frío y forma niebla. La respuesta (A) es incorrecta porque el enfriamiento nocturno produce niebla por radiación. La respuesta (B) es incorrecta porque el enfriamiento adiabático produce niebla de ladera o de montaña."},
  {"id": 317, "s": 5, "q": "¿Cuál es una característica importante respecto a la cizalladura del viento?", "o": ["Sólo está presente en los niveles inferiores y existe en sentido horizontal.", "Está presente en cualquier nivel y sólo existe en sentido vertical.", "Puede estar presente en cualquier nivel y puede existir tanto en sentido horizontal como vertical."], "a": 2, "e": "La cizalladura del viento puede estar asociada a un cambio de viento o a un gradiente de velocidad del viento en cualquier nivel de la atmósfera. Puede estar asociada a una inversión de la temperatura en niveles bajos, en una zona frontal, o a una turbulencia de aire claro (CAT) en niveles altos asociados a una corriente en chorro o a una circulación fuerte. La respuesta (A) es incorrecta porque la cizalladura del viento se produce tanto vertical como horizontalmente, y en todas las altitudes. La respuesta (B) es incorrecta porque la cizalladura del viento se produce tanto vertical como horizontalmente, y en todas las altitudes."},
  {"id": 318, "s": 5, "q": "Es habitual encontrar una cizalladura de viento peligrosa:", "o": ["cerca de la actividad frontal cálida o estacionaria.", "cuando la velocidad del viento es superior a 35 nudos.", "en áreas de inversión de temperatura y cerca de tormentas."], "a": 2, "e": "A menudo hay un viento fuerte justo por encima de la parte superior de una capa de inversión. Volar dentro o fuera de este viento induce una situación de cizalladura. Los fenómenos meteorológicos más destacados que causan problemas de cizalladura del viento a bajo nivel son las tormentas eléctricas y ciertos sistemas frontales en el aeropuerto o cerca de él. La respuesta (A) es incorrecta porque la cizalladura del viento peligrosa se encuentra más comúnmente cerca de las inversiones y las tormentas eléctricas. La respuesta (B) es incorrecta porque el viento fuerte no significa que siempre habrá cizalladura del viento; el viento debe estar en diferentes direcciones."},
  {"id": 319, "s": 5, "q": "La cizalladura del viento a bajo nivel puede ocurrir cuando:", "o": ["los vientos de superficie son ligeros y variables.", "hay una inversión de temperatura en niveles bajos con fuertes vientos por encima de la inversión.", "Los vientos de superficie son superiores a 15 nudos y no hay cambios en la dirección y la velocidad del viento con la altura."], "a": 1, "e": "Al despegar o aterrizar con viento en calma y con cielo despejado unas horas antes o después del amanecer, prepárese para una inversión de temperatura cerca del suelo. Puede estar relativamente seguro de que existe una zona de cizalladura en la inversión si sabe que el viento a 2.000 a 4.000 pies tiene una velocidad de 25 nudos o más. Deje un margen de velocidad aerodinámica por encima de la velocidad normal de ascenso o aproximación para aliviar el peligro de entrar en pérdida en caso de turbulencia o cambio repentino de la velocidad del viento."},
  {"id": 320, "s": 5, "q": "Si se encuentra una inversión de temperatura inmediatamente después del despegue o durante la aproximación al aterrizaje, existe un peligro potencial debido a:", "o": ["la cizalladura del viento.", "los fuertes vientos de superficie.", "las fuertes corrientes convectivas."], "a": 0, "e": "Puede estar relativamente seguro de que hay una zona de cizalladura en la inversión si se sabe que el viento a 2,000 a 4,000 pies con una velocidad de 25 nudos o más. Deje un margen de velocidad aérea por encima de la velocidad normal de ascenso o aproximación para aliviar el peligro de una pérdida, en caso de turbulencia o cambio repentino en la velocidad del viento. La respuesta (B) es incorrecta porque los vientos fuertes de superficie no representan un peligro tan grande como la cizalladura del viento. La respuesta (C) es incorrecta porque una inversión de temperatura no genera fuertes corrientes convectivas."},
  {"id": 321, "s": 5, "q": "DADO: Vientos a 3.000 pies AGL 30 Nudos. Vientos en superficie: Calmados. Durante la aproximación para el aterrizaje bajo cielos despejados con turbulencia convectiva unas horas después del amanecer, se debe:", "o": ["Aumentar la velocidad de aproximación ligeramente por encima de lo normal para evitar la entrada en pérdida.", "Mantener la velocidad de aproximación en el nivel normal o ligeramente inferior para compensar la flotación.", "No alterar la velocidad del aire de aproximación, estas condiciones son casi ideales."], "a": 0, "e": "Al despegar o aterrizar con viento en calma y con cielo despejado unas horas antes o después del amanecer, prepárese para una inversión de temperatura cerca del suelo. Puede estar relativamente seguro de que existe una zona de cizalladura en la inversión si sabe que el viento a 2.000 o 4.000 pies tiene una velocidad de 25 nudos o más. Aumente la velocidad del aire ligeramente por encima de la velocidad normal de ascenso o aproximación para aliviar el peligro de una pérdida en caso de turbulencia o cambio repentino en la velocidad del viento."},
  {"id": 322, "s": 5, "q": "Las corrientes convectivas son más activas en las tardes cálidas de verano, cuando los vientos son:", "o": ["bajos.", "moderados.", "fuertes."], "a": 0, "e": "Las corrientes convectivas son más activas en las tardes cálidas de verano, cuando los vientos son ligeros. El aire calentado en la superficie crea una capa inestable poco profunda y el aire caliente es forzado a subir. La convección aumenta en fuerza y a mayores alturas a medida que aumenta el calentamiento de la superficie. La respuesta (B) es incorrecta porque los vientos moderados y fuertes interrumpen el movimiento vertical de las corrientes convectivas. La respuesta (C) es incorrecta porque los vientos moderados y fuertes interrumpen el movimiento vertical de las corrientes convectivas."},
  {"id": 323, "s": 5, "q": "Cuando se vuele a baja altura sobre terrenos accidentados, crestas o cordilleras, el mayor peligro potencial de las corrientes de aire turbulentas se encontrará normalmente en el:", "o": ["sotavento cuando se vuela con viento de cola.", "sotavento cuando se vuela contra el viento.", "barlovento cuando se vuela contra el viento."], "a": 1, "e": "En el lado de sotavento se pueden encontrar corrientes descendentes peligrosas. La respuesta (A) es incorrecta porque con un viento de cola, se estaría volando lejos de la montaña con el viento. La respuesta (C) es incorrecta porque estarías volando en el aire que se eleva en el lado de barlovento."},
  {"id": 324, "s": 5, "q": "Durante una aproximación, el medio más importante y más fácilmente reconocible para ser alertado de una posible cizalladura del viento es la monitorización de la:", "o": ["Cantidad de compensador requerido para aliviar las presiones de control.", "Cambios de rumbo necesarios para permanecer en línea central de la pista.", "Potencia y velocidad vertical necesarias para mantenerse en la senda de planeo adecuada."], "a": 2, "e": "Dado que la velocidad de descenso en la pendiente de planeo está directamente relacionada con la velocidad de avance, una velocidad de descenso alta indicaría un fuerte viento de cola. A la inversa, una tasa de descenso baja indica un viento fuerte en contra. La potencia necesaria para mantener la pendiente de planeo también será diferente de las condiciones típicas sin cizalladura. Se necesitará menos potencia de lo normal para mantener la pendiente de planeo cuando haya un viento de cola y se necesitará más potencia para un viento fuerte en contra."},
  {"id": 325, "s": 5, "q": "Durante la salida, en condiciones de sospecha de cizalladura del viento en niveles bajos, una disminución repentina del viento en contra provocará:", "o": ["una pérdida de velocidad del aire igual a la disminución de la velocidad del viento.", "una ganancia de velocidad del aire igual a la disminución de la velocidad del viento.", "no hay cambios en la velocidad del aire, pero la velocidad con respecto al suelo disminuirá."], "a": 0, "e": "La peor situación en la salida ocurre cuando la aeronave se encuentra con un viento de cola que aumenta rápidamente, un viento de frente que disminuye y/o una corriente descendente. El despegue bajo estas circunstancias llevaría a una condición de rendimiento disminuido. Un viento de cola creciente o un viento de frente decreciente, cuando se encuentra, causará una disminución de la velocidad aérea indicada. La aeronave inicialmente se inclinará hacia abajo debido a la disminución de la sustentación en proporción a la pérdida de velocidad del aire. Después de encontrar la cizalladura, si el viento permanece constante, la velocidad de avance de la aeronave aumentará gradualmente y la velocidad aérea indicada volverá a su valor original. La respuesta (B) es incorrecta porque una disminución repentina del viento en contra provocará una pérdida de velocidad aerodinámica. La respuesta (C) es incorrecta porque hay una pérdida inicial de velocidad del aire, seguida de un aumento de la velocidad en tierra."},
  {"id": 326, "s": 5, "q": "¿Qué situación es más probable que produzca una precipitación helada? La lluvia que cae del aire que tiene una temperatura de:", "o": ["32 °F menos en aire con una temperatura superior a 32 °F.", "0 °C o menos en un aire con una temperatura de O *C o más.", "Más de 32 °F en el aire que tiene una temperatura de 32 °F o menos."], "a": 2, "e": "La lluvia que cae a través de un aire más frío puede sobre enfriarse, congelándose al impactar como lluvia helada, o puede congelarse durante su descenso, cayendo en forma de gránulos de hielo. El agua puede congelarse a 0\"C o 32 °F,"},
  {"id": 327, "s": 5, "q": "¿Qué afirmación es cierta sobre los peligros del granizo?", "o": ["Los daños del granizo en vuelo horizontal son mínimos debido al movimiento vertical del granizo en las nubes.", "La lluvia en la superficie es una indicación fiable de que no hay granizo en el aire.", "Los granizos pueden encontrarse en el aire a varios kilómetros de una tormenta."], "a": 2, "e": "Los granizos pueden caer a cierta distancia del núcleo de la tormenta. Se ha observado la caída de granizo en el aire libre a varios kilómetros de la tormenta principal. La respuesta (A) es incorrecta porque el granizo es uno de los mayores peligros para los aviones. La respuesta (B) es incorrecta porque la lluvia en la superficie no significa la ausencia de granizo en el aire."},
  {"id": 328, "s": 5, "q": "El granizado es más probable que se asocie con:", "o": ["nubes cúmulos.", "nubes cumulonimbos.", "nubes estratocúmulos."], "a": 1, "e": "Se debe prevenir la posibilidad de que caiga granizo con cualquier tormenta, especialmente bajo el yunque de un gran cumulonimbo."},
  {"id": 329, "s": 5, "q": "Las condiciones meteorológicas más severas, como los vientos destructivos, el granizo intenso y los tornados, suelen estar asociadas a:", "o": ["frentes cálidos de movimiento lento que se inclinan por encima de la tropopausa.", "líneas de borrasca.", "frentes ocluidos de rápido movimiento."], "a": 1, "e": "Una línea de borrasca es una banda estrecha no frontal de tormentas activas. A menudo contiene fuertes tormentas estacionarias y representa el peligro meteorológico más intenso para las aeronaves. La respuesta (A) es incorrecta porque los frentes cálidos no suelen producir tiempo severo. La respuesta (C) es incorrecta porque el tiempo producido por los frentes ocluidos no es tan severo como una línea de borrasca."},
  {"id": 330, "s": 5, "q": "De las siguientes afirmaciones, ¿cuál es correcta en relación con la turbulencia asociadaa las tormentas eléctricas?", "o": ["Fuera de la nube, la turbulencia de cizalladura puede encontrarse a 50 millas lateralmente de una tormenta severa.", "La turbulencia de cizalladura sólo se encuentra en el interior de los cumulonimbos o en un radio de 8 kilómetros de estos.", "Fuera de la nube, la turbulencia de cizalladura puede encontrarse a 20 millas lateralmente de una tormenta severa."], "a": 2, "e": "Las turbulencias peligrosas están presentes en todas las tormentas eléctricas, y una tormenta eléctrica severa puede dañar un fuselaje. La turbulencia más fuerte dentro de las nubes ocurre con la cizalladura entre las corrientes ascendentes y descendentes. Fuera de las nubes, se han encontrado turbulencias de cizalladura a varios miles de pies por encima y a 20 millas lateralmente de una tormenta severa."},
  {"id": 331, "s": 5, "q": "Si el radar aéreo indica un eco de tormenta extremadamente intenso, esta tormenta debe evitarse a una distancia de al menos:", "o": ["20 millas.", "10 millas.", "5 millas."], "a": 0, "e": "Si el uso del radar aéreo indica ecos extremadamente intensos, deben evitarse al menos a 20 millas."},
  {"id": 332, "s": 5, "q": "¿Qué afirmación es cierta respecto a las líneas de borrasca?", "o": ["Siempre se asocian a los frentes fríos.", "Son lentos en su formación, pero rápidos en su movimiento.", "No son frontales y a menudo contienen tormentas severas y estables."], "a": 2, "e": "Una línea de borrasca es una banda estrecha no frontal de tormentas activas. A menudo contiene tormentas eléctricas severas de estado estable y presenta el peligro meteorológico más intenso para las aeronaves. La respuesta (A) es incorrecta porque las líneas de borrasca pueden formarse en cualquier zona de aire inestable, pero normalmente se encuentran delante de los frentes fríos. La respuesta (B) es incorrecta porque las borrascas suelen formarse rápidamente."},
  {"id": 333, "s": 5, "q": "¿Qué afirmación es cierta respecto a las líneas de borrasca?", "o": ["Se forman lentamente, pero se mueven rápidamente.", "Se asocia únicamente a los sistemas frontales.", "Ofrecen los riesgos meteorológicos más intensos paras las aeronaves."], "a": 2, "e": "Una línea de borrasca es una banda estrecha no frontal de tormentas activas. Suele contener fuertes tormentas estables y presenta el peligro meteorológico más intenso para las aeronaves. La respuesta (A) es incorrecta porque las líneas de borrasca suelen formarse rápidamente. La respuesta (B) es incorrecta porque las líneas de borrasca pueden formarse en cualquier zona de aire inestable, pero normalmente se encuentran delante de los frentes fríos."},
  {"id": 334, "s": 5, "q": "Seleccione la afirmación correcta respecto al ciclo de vida de una tormenta eléctrica:", "o": ["Las corrientes de aire continúan desarrollándose durante la fase de disipación de una tormenta.", "El comienzo de la lluvia en la superficie de la tierra indica la fase de madurez de la tormenta.", "El comienzo de la lluvia en la superficie de la tierra indica la fase de disipación de la tormenta."], "a": 1, "e": "La etapa de madurez de una tormenta eléctrica comienza cuando la precipitación empieza a caer desde la base de las nubes. Las corrientes descendentes alcanzan velocidades que pueden superar los 2,500 pies por minuto. Mientras tanto, las corrientes ascendentes alcanzan un máximo con velocidades que pueden superar los 6,000 pies por minuto. Las corrientes ascendentes y descendentes en estrecha proximidad crean una fuerte cizalladura vertical y un entorno muy turbulento."},
  {"id": 335, "s": 5, "q": "¿Qué signos visibles indican una turbulencia extrema en las tormentas?", "o": ["Base de las nubes cerca de la superficie, fuerte lluvia y granizo.", "Bajo techo y visibilidad, granizo y precipitación estática.", "Nubes cumulonimbos, relámpagos muy frecuentes y nubes en rodillo (Arcus)."], "a": 2, "e": "Las nubes cumulonimbos representan una masa de aire inestable que indica condiciones turbulentas. Cuanto más frecuentes sean los rayos, más grave será la tormenta. La nube Arcus es más frecuente en las tormentas frontales frías o en la línea de borrasca y significa una zona extremadamente turbulenta."},
  {"id": 336, "s": 5, "q": "¿Qué fenómeno meteorológico indica el comienzo de la fase de madurez de unatormenta?", "o": ["El comienzo de la lluvia.", "El aspecto de la parte superior de un yunque.", "La tasa de crecimiento de la nube es máxima."], "a": 0, "e": "La etapa de madurez de una tormenta eléctrica comienza cuando la precipitación empieza a caer desde la base de las nubes. Las corrientes descendentes alcanzan velocidades que pueden superar los 2,500 pies por minuto. Mientras tanto, las corrientes ascendentes alcanzan un máximo con velocidades que pueden superar los 6,000 pies por minuto. La respuesta (B) es incorrecta porque la cima del yunque aparece durante la etapa de maduración, pero no necesariamente al principio. La respuesta (C) es incorrecta porque la máxima velocidad de crecimiento de las nubes se produce entre la mitad y el final de la etapa madura."},
  {"id": 337, "s": 5, "q": "¿Qué característica se asocia normalmente a la fase de cúmulo de una tormentaeléctrica?", "o": ["Nube de rollos.", "Corriente ascendente continua.", "Comienza a llover en la superficie."], "a": 1, "e": "La característica principal de la etapa de cúmulo de una tormenta eléctrica es una corriente ascendente continua. La respuesta (A) es incorrecta porque la nube rodante y el comienzo de la lluvia en la superficie son características de la etapa madura. La respuesta (C) es incorrecta porque la nube rodante y el comienzo de la lluvia en la superficie son características de la etapa madura."},
  {"id": 338, "s": 5, "q": "Durante el ciclo de vida de una tormenta eléctrica, ¿Qué etapa se caracteriza predominante por las corrientes descendentes?", "o": ["Madurez.", "Cúmulo.", "Disipación."], "a": 2, "e": "Las corrientes descendentes caracterizan la etapa de disipación de la célula de tormenta. La respuesta (A) es incorrecta porque la etapa de madurez tiene tanto corrientes ascendentes como descendentes. La respuesta (B) es incorrecta porque la etapa de desarrollo o cúmulo tiene principalmente corrientes ascendentes."},
  {"id": 339, "s": 5, "q": "¿Qué distancia mínima debe existir entre los ecos intensos del radar antes de intentar volar entre estas tormentas?", "o": ["20 millas.", "30 millas.", "40 millas."], "a": 2, "e": "El piloto debe evitar volar entre ecos muy intensos a menos que estén separados por al menos 40 millas."},
  {"id": 340, "s": 5, "q": "Las tormentas eléctricas identificadas como severas o que dan un eco de radar intenso, ¿A qué distancia deben evitarse?", "o": ["5 millas.", "Al menos 25 millas.", "Al menos 20 millas."], "a": 2, "e": "Evite por lo menos a 20 millas cualquier tormenta eléctrica identificada como severa o que dé un eco intenso en el radar. Esto es especialmente cierto bajo el yunque de un gran cumulonimbo."},
  {"id": 341, "s": 5, "q": "Las mayores amenazas para una aeronave que opera en la proximidad de tormentas eléctricas son:", "o": ["truenos y fuertes lluvias.", "granizos y las turbulencias.", "precipitación estática y baja visibilidad."], "a": 1, "e": "La turbulencia peligrosa está presente en todas las tormentas eléctricas; en una tormenta eléctrica severa, puede dañar un fuselaje. El granizo compite con la turbulencia como el mayor peligro de las tormentas eléctricas para las aeronaves."},
  {"id": 342, "s": 5, "q": "Usted está evitando una tormenta eléctrica que se encuentra en su trayectoria de vuelo. Está a más de 20 millas de la célula; sin embargo, está bajo el yunque de la célula. ¿Es esto un peligro?", "o": ["No, la distancia a la célula es segura.", "Sí, el granizo puede ser descargado desde el yunque.", "Sí, la distancia está aún en el área de disipación."], "a": 1, "e": "Evite por lo menos 20 millas cualquier tormenta eléctrica identificada como severa o que dé un eco intenso en el radar. Esto es especialmente cierto bajo el yunque de un gran cumulonimbo donde se puede descargar granizo."},
  {"id": 343, "s": 5, "q": "¿Qué peligro en vuelo se asocia más comúnmente con los frentes cálidos?", "o": ["Niebla de advección.", "Niebla de radiación.", "Niebla inducida por la precipitación."], "a": 2, "e": "Cuando una lluvia o llovizna relativamente cálida cae a través de aire frío, la evaporación de la precipitación satura el aire frío y forma niebla. La niebla inducida por la precipitación puede llegar a ser bastante densa y continuar durante un largo período de tiempo. Esta niebla puede cubrir grandes áreas, suspendiendo completamente las operaciones aéreas. Suele estar asociada a los frentes cálidos, pero puede producirse con los frentes fríos de movimiento lento y con los frentes estacionarios."},
  {"id": 344, "s": 5, "q": "¿Cuál de las siguientes afirmaciones es cierta en relación con el uso del radar meteorológico aerotransportado para el reconocimiento de determinadas condiciones meteorológicas?", "o": ["El radar no ofrece ninguna garantía de evitar las condiciones meteorológicas.", "La evasión del granizo está asegurada cuando se vuela entre los ecos más intensos y apenas se aleja de ellos.", "La zona despejada entre los ecos intensos indica que se puede mantener la visión de las tormentas cuando se vuela entre los ecos."], "a": 0, "e": "El radar meteorológico solo detecta las gotas de precipitación. No detecta las diminutas gotas de las nubes. Por lo tanto, el alcance del radar no proporciona ninguna seguridad para evitar el mal tiempo, nubes o niebla. La respuesta (B) es incorrecta porque el granizo puede ser lanzado a varias millas de los ecos intensos. La respuesta (C) es incorrecta porque pueden existir nubes sin precipitación entre los ecos."},
  {"id": 345, "s": 5, "q": "La situación más propicia para la formación de niebla de advección es:", "o": ["una ligera brisa que desplaza el aire frio sobre la superficie del agua.", "una masa de aire que se desplaza hacia el interior desde la costa durante el invierno.", "una masa de aire cálido y húmedo que se asienta sobre una superficie fría en condiciones de ausencia de viento."], "a": 1, "e": "La niebla por advección se forma cuando el aire cálido y húmedo se desplaza sobre el suelo más frío O el agua. La niebla se forma en alta mar y luego es arrastrada por el viento hacia el interior. Es más común a lo largo de las zonas costeras, pero a menudo se desarrolla en las zonas continentales. La respuesta (A) es incorrecta porque describe la niebla de vapor. La respuesta (C) es incorrecta porque describe la niebla de radiación."},
  {"id": 346, "s": 5, "q": "La niebla de advección se ha desplazado sobre un aeropuerto costero durante el día. ¿Qué puede tender a disipar o elevar esta niebla en nubes bajas?", "o": ["Enfriamiento nocturno.", "Radiación superficial.", "Viento de 15 nudos o más fuerte."], "a": 2, "e": "La niebla por advección se profundiza a medida que aumenta la velocidad del viento hasta unos 15 nudos. Los vientos mucho más fuertes que los 15 nudos levantan la niebla en una capa de nubes bajas o estratocúmulo. La respuesta (A) es incorrecta porque el enfriamiento nocturno y la radiación superficial forman la niebla de radiación. La respuesta (B) es incorrecta porque el enfriamiento nocturno y la radiación superficial forman la niebla de radiación."},
  {"id": 347, "s": 5, "q": "¿Qué levanta la niebla de advección en las nubes bajas?", "o": ["Enfriamiento nocturno.", "La sequedad de la masa terrestre subyacente.", "Vientos en superficie de aproximadamente 15 nudos o más fuertes."], "a": 2, "e": "La niebla por advección se profundiza a medida que aumenta la velocidad del viento hasta unos 15 nudos. Los vientos mucho más fuertes que los 15 nudos levantan la niebla en una capa de nubes bajas o de tipo estratocúmulo. La respuesta (A) es incorrecta porque el enfriamiento nocturno y la sequedad de la masa terrestre subyacente conducen a la niebla por radiación. La respuesta (B) es incorrecta porque el enfriamiento nocturno y la sequedad de la masa terrestre subyacente provocan niebla por radiación."},
  {"id": 348, "s": 5, "q": "¿En qué se diferencian la niebla de advección, la niebla de radiación y la niebla de vapor en su formación o ubicación?", "o": ["La niebla por radiación se limita a las zonas terrestres; la niebla por advección es más común en las zonas costeras; la niebla de vapor se forma sobre una superficie de agua.", "La niebla por advección se profundiza a medida que aumenta la velocidad del viento hasta 20 nudos; la niebla de vapor requiere un viento en calma o muy ligero; la niebla por radiación se forma cuando el suelo o el agua enfrían el aire por radiación.", "La niebla de vapor se forma a partir del aire húmedo que se desplaza sobre una superficie más fría; la niebla de advección requiere aire frío sobre una superficie más cálida; la niebla de radiación se produce por el enfriamiento radial del suelo."], "a": 0, "e": "La niebla por radiación se limita a las zonas terrestres porque las superficies de agua se enfrían poco por la radiación nocturna. La niebla por advección es más común a lo largo de las zonas costeras, pero a menudo se desarrolla en las zonas continentales. La niebla de vapor, también conocida como \"humo del mar\", se forma en invierno cuando el aire frío y seco pasa de las zonas terrestres a las aguas oceánicas comparativamente cálidas."},
  {"id": 349, "s": 5, "q": "Con respecto a la niebla de advección, ¿qué afirmación es cierta?", "o": ["Se desarrolla lentamente y se disipa con bastante rapidez.", "Se forma casi exclusivamente por la noche o cerca del amanecer.", "Puede aparecer repentinamente durante el día o la noche, y es más persistente que la niebla de radiación."], "a": 2, "e": "La niebla de advección es más persistente que la niebla de radiación y puede avanzar rápidamente independientemente de la hora del día o de la noche. La respuesta (A) es incorrecta porque la niebla de advección puede avanzar rápidamente independientemente de la hora del día o de la noche y es persistente. La respuesta (B) es incorrecta porque describe la niebla de radiación."},
  {"id": 350, "s": 5, "q": "¿Qué característica está asociada a la tropopausa?", "o": ["Altura constante sobre la tierra.", "Cambio abrupto en el gradiente térmico vertical.", "Límite superior absoluto de formación de nubes."], "a": 1, "e": "Al ser la fina capa límite entre la troposfera y la estratosfera, la tropopausa señala un cambio abrupto en el gradiente de temperatura. La respuesta (A) es incorrecta porque la tropopausa está más lejos de la superficie de la Tierra en el ecuador que en los polos. La respuesta (C) es incorrecta porque las nubes pueden formarse por encima de la tropopausa."},
  {"id": 351, "s": 5, "q": "Un lugar común de turbulencia de aire claro es:", "o": ["En una vaguada superior en el lado polar de una corriente en chorro.", "Cerca de una cresta en la parte ecuatorial de un flujo de alta presión.", "Al sur de una cresta de alta presión orientada al este/oeste en su fase de disipación."], "a": 0, "e": "La turbulencia de aire claro (CAT) es mayor cerca de los máximos de velocidad del viento, normalmente en los lados polares donde hay una combinación de fuerte cizalladura del viento, curvatura en el flujo y advección de aire frío asociada con contornos fuertemente curvados de fuertes vaguadas y crestas en el aire. Una ubicación frecuente del CAT es una vaguada superior en el lado frío o polar de la corriente en chorro."},
  {"id": 352, "s": 5, "q": "La corriente en chorro y las turbulencias de aire claro asociadas pueden identificarse a veces visualmente en vuelo por:", "o": ["polvo o neblina a nivel de vuelo.", "largas vetas de nubes cirrus.", "una temperatura constante del aire exterior."], "a": 1, "e": "Las largas vetas de nubes tipo cirrus a veces pueden ayudar al piloto a identificar visualmente la corriente en chorro y la turbulencia de aire claro asociada (CAT). La respuesta (A) es incorrecta porque el polvo o la bruma indican que no hay suficiente viento o movimiento de aire para disipar las partículas. La respuesta (C) es incorrecta porque la CAT es causada por la mezcla de diferentes temperaturas de aire a diferentes niveles de presión."},
  {"id": 353, "s": 5, "q": "Durante los meses de invierno en las latitudes medias, la corriente de chorro se desplaza hacia el:", "o": ["Norte y la velocidad disminuye.", "Sur y la velocidad incrementa.", "Norte y la velocidad incrementa."], "a": 1, "e": "En las latitudes medias, la velocidad media del viento de la corriente de chorro es considerablemente mayor en los meses de invierno, ya que se desplaza más al sur."},
  {"id": 354, "s": 5, "q": "La fuerza y la ubicación de la corriente en chorro es normalmente:", "o": ["más débil y más al norte en el verano.", "más fuerte y más al norte en el invierno.", "más fuerte y más al norte en el verano."], "a": 0, "e": "La corriente en chorro es considerablemente más débil en las latitudes medias durante los meses de verano, y está más al norte que en invierno."},
  {"id": 355, "s": 5, "q": "La condición más favorable para la formación de ondas de montaña son una capa de:", "o": ["aire estable en la altura de la montaña y un viento de al menos 20 nudos soplando a través de la cresta.", "aire inestable a la altura de la montaña y un viento de al menos 20 nudos soplando a través de la cresta.", "aire húmedo e inestable en la altura de la montaña y un viento de menos de 5 nudos a través de la cresta."], "a": 0, "e": "Una fuerte onda de montaña requiere: 1. Una marcada estabilidad en la corriente de aire perturbada por las montañas; 2. La velocidad del viento a nivel de la cumbre debe superar un mínimo que varía de 15 a 25 nudos, según la altura de la cordillera; y 3. Dirección del viento dentro de los 30° respecto a la cordillera. La sustentación disminuye a medida que los vientos son más paralelos a la cordillera."},
  {"id": 356, "s": 5, "q": "¿Qué tipo de corriente en chorro puede provocar mayores turbulencias?", "o": ["Una corriente en chorro recta asociada a una caída de presión.", "Una corriente en chorro curvada asociada a una caída de presión.", "Una corriente en chorro que se produce durante el verano en las latitudes más bajas."], "a": 1, "e": "Las corrientes en chorro curvas, especialmente las que se curvan alrededor de una depresión profunda, son más propensas a tener bordes turbulentos que las corrientes en chorro rectas. La respuesta (A) es incorrecta porque una corriente en chorro curvada es más fuerte que una corriente en chorro recta. La respuesta (C) es incorrecta porque la corriente en chorro es más débil en verano."},
  {"id": 357, "s": 5, "q": "Se puede esperar una fuerte cizalladura del viento cuando:", "o": ["En el frente de la corriente de chorro, por encima de un núcleo que tiene una velocidad de 60 a 90 nudos.", "Si las isotermas de 5 °C están espaciadas entre 7° y 10° de altitud.", "En el lado de baja presión de un núcleo de chorro, donde la velocidad en el núcleo es más fuerte que 110 nudos."], "a": 2, "e": "Las corrientes en chorro más fuertes que los 110 nudos (en el núcleo) son propensas a tener áreas de turbulencia significativa cerca de ellas en la tropopausa inclinada por encima del núcleo, en el frente de la corriente en chorro por debajo del núcleo y en el lado de baja presión del núcleo. En estas zonas suelen producirse fuertes cizalladuras de viento. La respuesta (A) es incorrecta porque entre 60 y 90 nudos es habitual en la corriente en chorro y si se encontraran turbulencias serían a los lados y en el fondo del núcleo. La respuesta (B) es incorrecta porque estas condiciones no crean exclusivamente cizalladura del viento."},
  {"id": 358, "s": 5, "q": "El Sistema de Alerta de Cizalladura del Viento de Bajo Nivel (LLWAS) proporciona datosde viento y proceso de software para detectar la presencia de:", "o": ["una columna de aire en rotación que se extiende desde un cumulonimbo.", "un cambio en la dirección y/o velocidad del viento en una distancia muy corta por encima del aeropuerto.", "el movimiento descendente del aire asociado a los vientos continuos que soplan con componente este debido a la rotación de la tierra."], "a": 1, "e": "La cizalladura del viento puede estar asociada a un cambio del viento o a un gradiente de velocidad del viento en cualquier nivel de la atmósfera. Puede estar asociada a una inversión de temperatura en niveles bajos, en una zona frontal, o a una turbulencia de aire claro (CAT) en niveles altos asociada a una corriente en chorro o a una circulación fuerte. La respuesta (A) es incorrecta porque describe un tornado. La respuesta (C) es incorrecta porque el LLWAS detecta los cambios de viento cerca del aeropuerto."},
  {"id": 359, "s": 5, "q": "Una de las características más peligrosas de las ondas de montaña son las zonas turbulentas en y:", "o": ["por debajo de las nubes del rotor.", "por encima de las nubes del rotor.", "por debajo de las nubes lenticulares."], "a": 0, "e": "Las \"nubes de rotor\" parecen permanecer estacionarias, paralelas a la cordillera, y se sitúan a unas pocas millas a sotavento de las montañas. La turbulencia es más frecuente y severa en y debajo de los rotores estacionarios justo debajo de las crestas de las olas en o por debajo de los niveles de las cimas de las montaña."},
  {"id": 360, "s": 5, "q": "El hielo que cubre la superficie superior del ala de un avión suele provocar:", "o": ["que el avión entre en pérdida con un ángulo de ataque superior al normal.", "que el avión entre en perdida con un ángulo de ataque inferior al normal.", "factores de resistencia aerodinámica tan grandes que no se puede obtener suficiente velocidad para el despegue."], "a": 1, "e": "El hielo en el ala provoca perturbaciones en el flujo de aire. Esto provocará la separación del flujo de aire (entrada en pérdida) a un ángulo de ataque más bajo, lo que provocará una tendencia a entrar en pérdida durante el despegue. La respuesta (A) es incorrecta porque el hielo en la superficie del ala suele hacer que el avión entre en pérdida a un ángulo de ataque más bajo. La respuesta (C) es incorrecta porque la resistencia aerodinámica no suele ser suficiente para impedir que el avión obtenga la velocidad de despegue."},
  {"id": 361, "s": 5, "q": "Durante un vuelo IFR a campo traviesa, usted ha recogido hielo en el borde de ataque de las alas de un grosor estimado de 1/2°. Ahora está por debajo de las nubes a 2000 pies AGL y se está acercando a su aeropuerto de destino bajo VER. La visibilidad bajo las nubes es de más de 10 millas, los vientos en el aeropuerto de destino son de 8 nudos a lo largo de la pista y la temperatura de la superficie es de 3 grados Celsius. Usted decide:", "o": ["Utilizar una velocidad de aproximación y aterrizaje más rápida de lo normal.", "Realizar la aproximación y aterrizaje con una velocidad normal ya que el hielo no es lo suficientemente grueso como para tener un efecto notable.", "Hacer la aproximación más despacio de lo normal para disminuir el efecto de “Enfriamiento por el viento” y romper el hielo."], "a": 0, "e": "El hielo se acumulará de forma desigual en el avión. Añadirá peso y resistencia, y disminuirá el empuje y la sustentación. Con las acumulaciones de hielo, las aproximaciones de aterrizaje deben realizarse con un ajuste mínimo de flaps y con un margen adicional de velocidad aerodinámica. Deben evitarse los cambios bruscos de la configuración en la velocidad del aire. La respuesta (B) es incorrecta porque el hielo con un grosor similar al del papel de lija en el borde de ataque y la superficie superior de un ala puede reducir la sustentación del ala hasta en un 30% y aumentar la resistencia en un 40%. La respuesta (C) es incorrecta porque el hielo aumentará la resistencia, requiriendo una sustentación adicional (velocidad del aire); no se puede confiar en el efecto de la \"sensación térmica\" para derretir/eliminar el hielo que ya se ha acumulado; volar más lento de lo normal aumenta la posibilidad de entrar en pérdida debido a la disminución de la sustentación."},
  {"id": 362, "s": 5, "q": "Hay un sistema de alta presión que se encuentra al sur de su ruta planificada en el hemisferio norte en un vuelo de oeste a este a campo traviesa. Para aprovechar los vientos favorables, usted planificaría su ruta:", "o": ["En el lado norte de la zona de alta presión.", "En el lado sur de la zona de alta presión.", "A través del centro de la zona de alta presión."], "a": 0, "e": "Las altas presiones fluyen hacia el exterior en el sentido de las agujas del reloj, por lo que el piloto ganará vientos de cola si vuela en el lado norte del sistema de altas presiones."},
  {"id": 363, "s": 6, "q": "Durante la preparación previa al vuelo, la mejor forma de obtener los pronósticos del informe meteorológico es comunicándose con:", "o": ["la oficina de previsión meteorológica (WFD).", "el centro de control de tráfico de rutas aéreas.", "el servicio"], "a": 0, "e": "Los informes y pronósticos están disponibles a través del servicio de solicitud / respuesta en todos los FSS, WSO y WSFO. La respuesta (B) es incorrecta porque ARTCC se ocupa del control del tráfico aéreo. La respuesta (C) es incorrecta porque PATWAS tiene un número limitado de pronósticos de ruta y sinopsis que puede proporcionar."},
  {"id": 364, "s": 6, "q": "La información meteorológica más actualizada en ruta y destino para un vuelo por instrumentos debe obtenerse de:", "o": ["servicio de vuelo.", "emisión ATIS.", "NOTAM."], "a": 0, "e": "El servicio de vuelo ofrece más servicio de información meteorológica de la aviación que cualquier otro medio de servicio del gobierno. Las estaciones de servicio de vuelo proporcionan informes meteorológicos, retransmisiones meteorológicas programadas y no programadas, y proporciona apoyo meteorológico a los vuelos en su área. La respuesta (B) es incorrecta porque el Servicio automático de información de terminales (ATIS) proporciona información para operaciones en un aeropuerto específico y no proporciona información para operaciones en ruta. La respuesta (C) es incorrecta porque NOTAM es una publicación que contiene información sobre las operaciones del aeropuerto y no tendría información sobre el clima en ruta y destino."},
  {"id": 365, "s": 6, "q": "La sección de comentarios de un informe meteorológico rutinario de aeródromo (METAR) contiene la siguiente información codificada. ¿Qué significa? RMK FZDZB42 WSHFT 30 FROPA", "o": ["Llovizna helada con bases de nubes por debajo de los 4,200 pies.", "Llovizna helada por debajo de los 4.200 pies y cizalladura del viento.", "Cambio de viento a tres cero por paso frontal."], "a": 2, "e": "RMK - los comentarios siguen FZDZB42 - la llovizna helada comenzó 42 minutos después de la hora WSHFT 30 FROPA - cambio de viento a tres cero debido al paso frontal."},
  {"id": 366, "s": 6, "q": "¿Qué se entiende por observación meteorológica METAR especial para KBOI? ESPECI KBOI 091854Z 32005KT 1 1/25M RA BR OVCO007 17/16 A2990 RMK RAB12", "o": ["La lluvia y la niebla oscurecen dos décimas partes del cielo; la lluvia comenzó a las 1912Z.", "Lluvia y neblina que obstruyen la visibilidad; la lluvia comenzó a las 1812Z.", "Lluvia y nubes a 1200 pies AGL."], "a": 1, "e": "SPECI KBO! - informe especial para KBOI 0918542: la fecha y la hora en que se realiza la observación es el día 9 del mes, 1854, hora Zulú 32005KT - vientos reales de 320° a 5 nudos 1-1/2 SM RA BR: las visibilidades son 1-1/2 millas terrestres con lluvia y niebla OVC 007 - el techo está cubierto a 700 pies 17/16 - la temperatura es de 17 °C y el punto de rocío es de 16 °C A2990 - altímetro es 29,90 RMK RAB12 - comentarios, la lluvia comenzó 12 minutos después de la hora."},
  {"id": 367, "s": 6, "q": "La estación que origina la siguiente observación METAR tiene una elevación de campo de 3,500 pies MSL. Si la cubertura del cielo es una capa continua, ¿cuál es el grosor de la capade nubes? (Parte superior de las nubes reportado a 7.500 pies MSL). METAR KHOB 151250Z 17006KT 4SM OVCO0O05 13/11 A2998", "o": ["2,500 pies.", "3,500 pies.", "4,000 pies."], "a": 1, "e": "KHOB reporta un techo de 500 pies (OVC005). Esto significa que la base de la capa de nubes está a 4,000 pies (3,500 MSL + 500 pies AGL). La parte superior de las nubes está reportada a 7.500 pies MSL. Por lo tanto, la capa de nubes es de 3,500 pies de grueso (7,500 - 4,000)."},
  {"id": 368, "s": 6, "q": "¿Qué condiciones de viento prevería cuando se reporten tormentas en su destino?", "o": ["Variaciones rápidas en la velocidad del viento de 15 nudos o más entre picos y calma.", "Ráfagas máximas de al menos 35 nudos combinadas con un cambio en la dirección del viento de 30 * o más.", "Aumentos repentinos de la velocidad del viento de al menos 16 nudos a una velocidad sostenida de 22 nudos o más durante al menos 1 minuto."], "a": 2, "e": "Una ráfaga es un aumento repentino de la velocidad del viento de 16 nudos a una velocidad sostenida de 22 nudos o más que dura al menos 1 minuto. La respuesta (A) es incorrecta porque describe ráfagas. La respuesta (B) es incorrecta porque describe la cizalladura del viento."},
  {"id": 369, "s": 6, "q": "¿Qué cobertura de nubes significativa es reportada por este informe del piloto? KMOBUA /OV 15NW MOB 1340Z / SK OVC-TOP025 / OVC045-TOP090", "o": ["Existen tres (3) capas de nubes separadas con bases a 250, 7,500 y 9,000 pies.", "La parte superior de las nubes bajas es de 2,500 pies; la base y la parte superior de la segunda capa de nubes es de 4.500 y 9.000 pies, respectivamente.", "La base de la segunda capa de nubes es de 2,500 pies; la parte superior de la segunda capa nubes es de 7.500 pies; La base de la tercera capa es de 9.000 pies."], "a": 1, "e": "UA - informe piloto /OV 15NW MOB: el piloto estaba a 15 millas al noroeste de Mobile, a las 1340 UTC / SK OVC-TOPO025 - cobertura del cielo, capa superior cubierta a 2500 pies /0VC045-TOPO90: una segunda capa está a 4.500 pies con la parte superior a 9.000 pies MSL."},
  {"id": 370, "s": 6, "q": "Para determinar mejor las condiciones meteorológicas observadas entre las estacionesde informes meteorológicos, el piloto debe consultar:", "o": ["informes de pilotos.", "pronósticos del área.", "mapas de pronóstico."], "a": 0, "e": "Los informes meteorológicos de los pilotos son el mejor medio para determinar las condiciones meteorológicas observadas entre las estaciones de informes meteorológicos. También es el único método para observar directamente las cimas de las nubes, la formación de hielo y las turbulencias. La respuesta (B) es incorrecta porque los pronósticos de área y los mapas de pronóstico son pronósticos y no condiciones meteorológicas observadas. La respuesta (C) es incorrecta porque los pronósticos de área y los mapas de pronóstico son pronósticos y no condiciones meteorológicas observadas."},
  {"id": 371, "s": 6, "q": "¿Cuál es el significado de los términos PROB40 2102 + TSRA tal como se utilizan en los pronósticos de aeródromo de una terminal (TAF)?", "o": ["Probabilidad de tormentas eléctricas fuertes con chubascos de lluvia por debajo de 4000 pies en el momento 2102.", "Entre las 2100Z y las 0200Z hay un cuarenta por ciento (40%) de probabilidad de tormentas eléctricas con lluvia intensa.", "A partir de las 2102Z, cuarenta por ciento (40%) de probabilidad de tormentas eléctricas fuertes y chubascos de lluvia."], "a": 1, "e": "El TAF informa que hay un 40% de probabilidad (PROB40) entre las 2100Z y las 0200Z (2102) de tormentas eléctricas y lluvias intensas (+ TSRA)."},
  {"id": 372, "s": 6, "q": "¿Qué significa la contracción VRB en el Pronóstico de Aeródromo Terminal (TAF)?", "o": ["La velocidad del viento es variable a lo largo del período.", "La base de las nubes es variable.", "La dirección del viento es variable."], "a": 2, "e": "Una dirección del viento variable se indica mediante 'VRB' donde usualmente aparece la dirección de tres dígitos."},
  {"id": 373, "s": 6, "q": "¿Cuál afirmación relativa al siguiente pronóstico de aeródromo terminal (TAF) es verdadera? TAF KMEM 091135Z 0915 15005KT 55M HZ BKN060 FM1600 VRBO04KT P6SM skc", "o": ["El viento en el período válido implica que se pronostica que los vientos en la superficie serán superiores a 5 KTS.", "La dirección del viento es de 160 * a 4 KTS y la visibilidad reportada es de 6 millas terrestres.", "SKC en el período válido indica que no hay tiempo significativo y cielo despejado."], "a": 2, "e": "TAF KMEM - pronóstico de aeródromo terminal para Memphis 0911352: la observación se realiza el día 9 del mes a las 1135, hora zulú 15005KT - los vientos son de 150° a 5 nudos 5SM HZ: la visibilidad es de 5 millas terrestres en neblina BKN06O0 - el techo está roto 6,000 pies FM1600 - desde 1600Z VRB04KT - el viento es variable a 4 nudos P6SM: la visibilidad es superior a 6 millas terrestres SKC: cielo despejado."},
  {"id": 374, "s": 6, "q": "En el siguiente METAR /TAF para HOU, ¿cuál es el techo y visibilidad pronosticada parael séptimo día del mes a las 06007° KHOU 061734Z 0618/0718 16014G22KT P6SM VCSH BKN018 BKNO035. FMO70100 17010KT P6SM BKN015 OVCO025. FMO70500 17008KT 4SM BR SCT008 OVCO12. FMO71000 18005KT 3SM BR OVCO007. FMO0O71500 23008KT 55M BR VCSH SCT008 OVCO015.", "o": ["Visibilidad de 6 millas con un techo fracturado a 15,000 pies MSL.", "A 4 millas náuticas de visibilidad y cielo cubierto a 700 pies MSL.", "Visibilidad de 4 millas terrestres y cielo cubierto a 1200 pies AGL."], "a": 2, "e": "La tercera línea del TAF lee desde el 7 a las 0500 viento 170 a 8 nudos, visibilidad 4 millas terrestres en niebla, 800 AGL dispersos, 1200 AGL nublado. Debido a que el próximo pronóstico del tiempo no se da hasta el día 7 a las 1000, debería usar la información del pronóstico del día 7 a las 0500 para responder la pregunta \"FMO70500 17008KT 4SM BR SCT008 OVCO12°. Recuerde que una capa dispersa no significa un techo."},
  {"id": 375, "s": 6, "q": "¿Cuántas veces al día se emiten los pronósticos de aeródromo terminal (TAF) y qué período de tiempo cubren?", "o": ["Cuatro veces al día y suelen tener una validez de 24 horas.", "Seis veces al día y generalmente son válidas por un período de 24 horas, incluyendo un pronóstico certero de 4 horas.", "Cuatro veces al día y son válidos por 12 horas, incluyendo un pronóstico certero de 6 horas."], "a": 0, "e": "Terminal Aerodrome Forecast (TAF) es una declaración concisa de las condiciones meteorológicas esperadas en un aeropuerto durante un período específico (generalmente 24 horas). Los TAF utilizan los mismos códigos que los informes meteorológicos METAR. Están programados cuatro veces al día para períodos de 24 horas a partir de las 0000Z, 0600Z, 1200Z y 18002."},
  {"id": 376, "s": 6, "q": "Para determinar mejor el pronóstico general de las condiciones meteorológicas que cubren la información de vuelo en una región, el piloto debe referirse a:", "o": ["gráficos de pronósticos para la aviación (GFA).", "mapas de representación meteorológica.", "mapas de satélite."], "a": 0, "e": "Los gráficos de pronósticos para la aviación (GFA) están destinados a proporcionar la información meteorológica de aviación necesaria para brindar a los usuarios una imagen completa del clima que puede afectar los vuelos en los EE. UU. Continentales (CONUS)."},
  {"id": 377, "s": 6, "q": "¿Qué tipo de avisos meteorológicos a bordo provee a un piloto en ruta, con información acerca de la posibilidad de engelamiento moderado, turbulencia moderada, vientos de 30 nudos o más en la superficie y un extensivo oscurecimiento de las montañas?", "o": ["SIGMETS y SIGMETS convectivos.", "Alertas de pronóstico de tiempo severo (AWW) y SIGMETS.", "AIRMETS y Centro de Advertencias Meteorológicas (CWA)."], "a": 2, "e": "Los AIRMET y los Centros de Advertencias Meteorológicas (CWA) pueden ser importantes para cualquier piloto u operador de aeronaves y se emiten para todo el espacio aéreo nacional. Son de especial interés para los operadores y pilotos de aeronaves sensibles a los fenómenos descritos y para los pilotos sin habilitación de instrumentos. Se emiten para los siguientes fenómenos meteorológicos los cuales son potencialmente peligrosos para las aeronaves: engelamiento moderado, turbulencia moderada, vientos sostenidos de 30 nudos o más en la superficie, área extensa de techos de menos de 1,000 pies y/o visibilidad de menos de tres millas, y extensivo oscurecimiento de las montañas."},
  {"id": 378, "s": 6, "q": "¿Qué referencia única contiene información sobre una erupción volcánica que está ocurriendo o se espera que ocurra?", "o": ["Avisos meteorológicos durante el vuelo.", "Pronósticos del área terminal (TAF).", "Mapas de representación del tiempo."], "a": 0, "e": "Los avisos meteorológicos en vuelo (SIGMET) brindan información sobre la erupción volcánica que está ocurriendo o se espera que ocurra. La respuesta (B) es incorrecta porque Terminal Area Forecasts (TAF) es una declaración concisa de las condiciones meteorológicas esperadas en un aeropuerto durante un período específico. La respuesta (C) es incorrecta porque un mapa de representación meteorológica es un informe del tiempo en el momento de la observación."},
  {"id": 379, "s": 6, "q": "¿Cuál describe correctamente el propósito de los SIGMET convectivos (WST)? Aquií", "o": ["Consisten en una observación cada hora de tornados, actividad significativa de tormentas y gran actividad de granizo.", "Contienen tanto una observación como un pronóstico de toda la actividad de tormentas eléctricas y granizo. El pronóstico es válido solo por 1 hora.", "Consisten tanto en una observación y pronóstico, o solo en un pronóstico de tornados, actividad significativa de tormentas eléctricas o granizo mayor o igual a 3/4 de pulgada de diámetro."], "a": 2, "e": "Los SIGMET convectivos se emiten en los Estados Unidos limítrofes para cualquiera de los siguientes: 1. Tormentas eléctricas severas debido a vientos en la superficie mayores o iguales a 50 nudos o granizo en la superficie mayor o igual a 3/4 de pulgada de diámetro o tornados; 2. Tormentas eléctricas integradas; 3. Línea de tormentas eléctricas; o 4. Tormentas eléctricas mayores o iguales al nivel VIP cuatro, que afecten al 40% o más de un área de al menos 3,000 millas cuadradas. La respuesta (A) es incorrecta porque los SIGMET son pronósticos no programados. La respuesta (B) es incorrecta porque los SIGMET se emiten solo para tormentas eléctricas severas y granizo de 3/4 de pulgada o más y pueden ser válidos hasta por 2 horas."},
  {"id": 380, "s": 6, "q": "¿Qué valores se utilizan para los Pronósticos de Vientos Altos?", "o": ["Dirección verdadera y MPH.", "Dirección verdadera y nudos.", "Dirección magnética y nudos."], "a": 1, "e": "La dirección del viento se refiere al norte verdadero y la velocidad del viento se indica en nudos en los informes de pronóstico de vientos en altura."},
  {"id": 381, "s": 6, "q": "Los SIGMET se emiten como una advertencia de condiciones climáticas que son peligrosas.", "o": ["A todos los aviones.", "Particularmente a aviones pesados.", "Particularmente a aviones ligeros."], "a": 0, "e": "Un SIGMET advierte sobre condiciones meteorológicas potencialmente peligrosas para todas las aeronaves, diferentes a actividad convectiva."},
  {"id": 382, "s": 6, "q": "En el cuadro de análisis de superficie, las líneas continuas que representan los patronesde presión a nivel del mar se denominan:", "o": ["Isobaras.", "Isogónicas.", "Milibares"], "a": 0, "e": "Las isobaras son líneas continuas que representan el patrón de presión. Por lo general, están espaciados a intervalos de cuatro milibares en un mapa de análisis de superficie. La respuesta (B) es incorrecta porque los isogónicas son líneas de variación magnética, que se encuentran en las cartas de navegación. La respuesta (C) es incorrecta porque los milibares son unidades de presión."},
  {"id": 383, "s": 6, "q": "Las líneas discontinuas en una carta de análisis de superficie, si se muestran, indican que el gradiente de presión es:", "o": ["débil.", "fuerte.", "inestable."], "a": 0, "e": "Cuando un gradiente de presión es débil, a veces se insertan isobaras discontinuas a intervalos de dos milibares para definir más claramente el patrón de presión. La respuesta (B) es incorrecta porque los gradientes de presión fuertes se indican mediante isobaras sólidas poco espaciadas a intervalos de 4-mb. La respuesta (C) es incorrecta porque la estabilidad se refiere a las tasas de variación de temperatura."},
  {"id": 384, "s": 6, "q": "¿Qué carta proporciona un medio fácil de localizar las posiciones frontales y los centrosde ¿ presión observados?", "o": ["Carta de análisis de superficie.", "Carta de análisis de presión constante.", "Carta de representación meteorológica"], "a": 0, "e": "Los gráficos de análisis de superficie se utilizan para indicar frentes y sistemas de presión. La respuesta (B) es incorrecta porque los gráficos de análisis de presión constante proporcionan el contenido de humedad, las temperaturas y los vientos observados en altura. La respuesta (C) es incorrecta porque la Tabla de representación meteorológica muestra la ubicación frontal, la cobertura y altura de las nubes y VFR / MVFR / IFR."},
  {"id": 385, "s": 6, "q": "En una carta de análisis de superficie, el espaciado estrecho de las isobaras indica:", "o": ["gradiente de presión débil.", "fuerte gradiente de presión.", "fuerte gradiente de temperatura."], "a": 1, "e": "El espaciado estrecho de las isobaras indica que existe un fuerte gradiente de presión. La respuesta (A) es incorrecta porque las isobaras más espaciadas indican un gradiente de presión más débil. La respuesta (C) es incorrecta porque las isotermas indican cambios de temperatura."},
  {"id": 386, "s": 6, "q": "La carta de análisis de superficie muestra:", "o": ["Ubicaciones frontales y movimiento esperado, centros de presión, cobertura de nubes y obstrucciones a la visión en el momento de la transmisión de la carta.", "posiciones frontales reales, patrones de presión, temperatura, punto de rocío, viento, clima y obstrucciones a la visión en el momento válido de la carta.", "distribución real de la presión, sistemas frontales, alturas y cobertura de las nubes, temperatura, punto de rocío y viento en el momento que se muestra en la carta."], "a": 1, "e": "La carta de análisis de superficie muestra las posiciones del sistema frontal, los patrones de presión y la temperatura, el punto de rocío, el viento, el clima y las obstrucciones a la visión en estaciones individuales en la carta de superficie válido para el tiempo indicado. La respuesta (A) es incorrecta porque la carta de análisis de superficie informa el clima en el momento de la observación. La respuesta (C) es incorrecta porque las cartas de análisis de superficie no indican la altura de las nubes."},
  {"id": 387, "s": 6, "q": "¿Qué carta meteorológica muestra las condiciones pronosticadas a existir en un momento específico en el futuro?", "o": ["Carta de niveles de congelación.", "Carta de representación meteorológica.", "Carta de pronóstico del tiempo significativo de 12 horas."], "a": 2, "e": "Las cartas de pronóstico muestran los pronósticos meteorológicos para algún momento futuro en áreas limítrofes y adyacentes a los EE. UU. La respuesta (A) es incorrecta porque no hay una Carta llamada Tabla de niveles de congelación. La respuesta (B) es incorrecta porque las Cartas de representación meteorológica muestran condiciones válidas solo para el tiempo indicado en la carta."},
  {"id": 388, "s": 6, "q": "¿Qué fenómeno meteorológico está implícito dentro de un área delimitada por pequeñas líneas onduladas en una carta de pronóstico meteorológico significativo de nivel superior?", "o": ["Nubes uniformes, formación de hielo, turbulencia de leve a moderada.", "Nubes cumulonimbus, engelamiento y turbulencia de moderada o mayor.", "Nubes lenticulares estacionarias o cumuliformes, turbulencia de moderada a severa y formación de hielo."], "a": 1, "e": "Las pequeñas líneas onduladas encierran áreas donde se espera el desarrollo de Cumulonimbus. Las nubes cumulonimbus implican engelamiento y turbulencia de moderada a mayor."},
  {"id": 389, "s": 6, "q": "¿La carta de pronóstico del tiempo significativo de nivel superior pronostica un tiempo significativo para qué espacio aéreo?", "o": ["18.000 pies a 45.000 pies.", "24.000 pies a 45.000 pies.", "24.000 pies a 63.000 pies."], "a": 2, "e": "La Carta de pronóstico de tiempo significativo de nivel superior de EE. UU. Pronostica un clima significativo que abarca el espacio aéreo desde 24,000 pies a 63,000 pies de altitud de presión (400 a 70 milibares)."},
  {"id": 390, "s": 6, "q": "¿Cuál es el límite superior de la carta de pronóstico del tiempo significativo de bajo nivel?", "o": ["30,000 pies.", "24,000 pies.", "18,000 pies."], "a": 1, "e": "La carta de pronóstico meteorológico Significativo de Bajo Nivel Incluye un clima significativo desde la superficie hasta 24,000 pies (400 milibares)."},
  {"id": 391, "s": 6, "q": "La diferencia encontrada al restar la temperatura de una parcela de aire teóricamente elevada de la superficie a 500 milibares y la temperatura existente a 500 milibares se llama:", "o": ["índice elevado.", "índice negativo.", "índice positivo."], "a": 0, "e": "El índice elevado se calcula como si una parcela de aire cerca de la superficie se elevara a 500 milibares. A medida que el aire se 'eleva', se enfría por expansión. La temperatura que tendría a 500 milibares se resta de la temperatura existente de 500 milibares (mb). La diferencia es el índice elevado; puede ser positivo, cero o negativo. La respuesta (B) es incorrecta porque un índice positivo significa que la porción de aire levantada es más fría que el aire existente a 500 mb, y el aire es estable. La respuesta (C) es incorrecta porque un índice negativo significa que la porción de aire elevada está más caliente que el aire existente a 500 mb, y el aire es inestable."},
  {"id": 392, "s": 6, "q": "La eclosión en una carta de análisis de presión constante indica:", "o": ["ojo del huracán.", "velocidad del viento de 70 nudos a 110 nudos.", "velocidad del viento de 110 nudos a 150 nudos."], "a": 1, "e": "Para ayudar a identificar áreas de vientos fuertes, el sombreado indica velocidades del viento de 70 a 110 nudos, un área despejada dentro de un área sombreada indica viento de 110 a 150 nudos y un área de 150 a 190 nudos de viento está sombreada. La respuesta (A) es incorrecta porque el ojo del huracán tiene vientos muy bajos. La respuesta (C) es incorrecta porque un área despejada dentro de un área sombreada indica viento de 110 a 150 nudos."},
  {"id": 393, "s": 6, "q": "¿Qué información de planificación de vuelo puede obtener un piloto de una carta de análisis de presión constante?", "o": ["Vientos y temperaturas en niveles superiores", "Turbulencia de aire claro y condiciones de formación de hielo.", "Sistemas frontales y obstrucciones a la visión en altura."], "a": 0, "e": "La carta de análisis de presión constante es una fuente de temperatura observada, dispersión de temperatura / punto de rocío, humedad y viento. La respuesta (B) es incorrecta porque se pueden encontrar turbulencias de aire claro en las cartas de pronóstico y en los pronósticos de área. La respuesta (C) es incorrecta porque los sistemas frontales y las obstrucciones a la visión en altura se pueden encontrar en las cartas de Análisis de superficie y Representación meteorológica."},
  {"id": 394, "s": 6, "q": "¿A partir de cuál de las siguientes opciones se puede determinar la temperatura, el vientoy punto de rocío observados a una altitud específica?", "o": ["Cartas de estabilidad.", "Pronósticos de vientos en altura.", "Cartas de análisis de presión constante."], "a": 2, "e": "La tabla de análisis de presión constante es una fuente de temperatura observada, dispersión de temperatura / punto de rocío, humedad y viento. La respuesta (A) es incorrecta porque las cartas de estabilidad brindan información sobre estabilidad, nivel de congelación, precipitación y humedad relativa promedio. La respuesta (B) es incorrecta porque los pronósticos de vientos en altura no brindan información sobre la propagación de temperatura / punto de rocío."},
  {"id": 395, "s": 6, "q": "El valor mínimo de cortantes de viento crítico para una posible turbulencia moderada o severa es:", "o": ["4 nudos por cada 1,000 pies.", "6 nudos por cada 1,000 pies.", "8 nudos por cada 1,000 pies."], "a": 1, "e": "Las cortantes de viento crítico para una posible turbulencia es de 6 nudos por cada 1,000 pies."},
  {"id": 396, "s": 6, "q": "Un piloto que reporta turbulencias que provocan momentáneamente cambios leves y erráticos en la altitud y / o actitud debe reportarlo como:", "o": ["Corte ligero.", "Turbulencia ligera.", "Turbulencia moderada."], "a": 1, "e": "La turbulencia que provoca momentáneamente cambios leves y erráticos en la altitud y / o actitud (cabeceo, balanceo, guiñada) se informa como turbulencia leve / ligera. La respuesta (A) es incorrecta porque el corte ligero es un golpe leve, rápido y algo rítmico. La respuesta (C) es incorrecta porque una turbulencia moderada provoca cambios en la altitud y / o actitud y variaciones en la velocidad indicada."},
  {"id": 397, "s": 6, "q": "Cuando la turbulencia provoca cambios en la altitud y/o actitud, pero el control de la aeronave sigue siendo positivo, se debe informar como:", "o": ["ligera.", "severa.", "moderada."], "a": 2, "e": "La turbulencia moderada es similar a la turbulencia ligera, pero de mayor intensidad. Se producen cambios de altitud y/o actitud, pero la aeronave permanece en control positivo en todo momento. Suele provocar variaciones en la velocidad indicada. Moderadamente el corte es similar al corte ligero, pero de mayor intensidad. Provoca golpes o sacudidas rápidas sin cambios apreciables en la altitud o actitudde la aeronave. La respuesta (A) es incorrecta porque una turbulencia ligera provoca momentáneamente cambios leves y erráticos en la altitud y / o actitud. La respuesta (B) es incorrecta porque la turbulencia severa causa cambios grandes y abruptos en la altitud y / o actitud y la aeronave puede estar momentáneamente fuera de control."},
  {"id": 398, "s": 6, "q": "La turbulencia que se encuentre por encima de los 15,000 pies AGL no asociada con nubosidad cuculiforme, incluidas las tormentas eléctricas, debe informarse como:", "o": ["turbulencia severa.", "turbulencia de aire claro.", "turbulencia convectiva."], "a": 1, "e": "Las turbulencias de alto nivel (normalmente por encima de los 15.000 pies AGL) no asociadas con la nubosidad cauliforme, incluidas las tormentas eléctricas, deben notificarse como CAT (turbulencia de aire claro) precedidas por la intensidad adecuada, o golpe ligero o moderado. La respuesta (A) es incorrecta porque la turbulencia severa no depende de la altitud. La respuesta (C) es incorrecta porque la turbulencia convectiva se refiere a la acción de elevación relacionada con la turbulencia con cúmulos."},
  {"id": 399, "s": 6, "q": "Las transmisiones de avisos meteorológicos, incluidas las alertas de pronóstico meteorológico severo (AWW), los SIGMET y los SIGMET convectivos son proporcionados por:", "o": ["ARTCCSs en todas las frecuencias, excepto de emergencia, cuando cualquier parte del área descrita se encuentre dentro de las 150 millas del espacio aéreo bajo su jurisdicción.", "Servicio de vuelo en 122.2 MHz y VORS adyacentes, cuando cualquier parte del área descrita se encuentre dentro de las 200 millas del espacio aéreo bajo su jurisdicción.", "Ayudas a la navegación baja frecuencia seleccionadas y / o VOR."], "a": 0, "e": "Los ARTCC emiten una alerta de pronóstico de tiempo severo (AWW), SIGMET, SIGMET convectivo O alerta CWA una vez en todas las frecuencias, excepto de emergencia, cuando cualquier parte del área descrita está dentro de las 150 millas del espacio aéreo bajo su jurisdicción. Estas transmisiones contienen un SIGMET o CWA (identificación) y una breve descripción de la actividad meteorológica y el área general afectada."},
  {"id": 400, "s": 6, "q": "¿Cuál es el espesor de la capa de nubes dada una elevación del campo de 1,500 pies MSL con la parte superior del cielo cubierto a 7,000 pies MSL? METAR KHOB 151250Z 17006KT 4SM OVCO010 13/11 A2998", "o": ["4,500 pies.", "6,500 pies.", "5,500 pies."], "a": 0, "e": "KHOB informa un techo de 1000 pies (OVCO10). Esto significa que la parte inferior de la capa nublada tiene 2.500 pies (1.500 MSL + 1000 pies AGL). La cima del cielo nublado se reporta a 7,000 pies MSL. Por lo tanto, la capa nublada tiene un espesor de 4.500 pies (7.000 - 2.500)."},
  {"id": 401, "s": 6, "q": "¿Cuál es la base de la capa nublada más baja en el siguiente informe piloto? KMOB UA /OV APE230010 / TM 1515 / FLO85 / TP BE20 / SK BKNO065 / WX FVO3SM HZ FU / TQ 20 / TB LGT", "o": ["No hay un límite máximo definido en este informe.", "Hay una capa reportada a 8.500 pies.", "Hay una capa de nubes fragmentada a 6.500 pies."], "a": 2, "e": "La parte cubierta del cielo del reporte indica \"SK BKN 065°, lo que significa que nubosidad del cielo está fragmentada a 6.500 pies. La respuesta (A) es incorrecta porque el límite máximo se define en la sección \"SK\" del informe. La respuesta (B) es incorrecta porque \"FLO85° detalla el nivel de vuelo al que se dio el informe, no la cobertura del cielo."},
  {"id": 402, "s": 7, "q": "Un equipaje que pesa 90 libras se coloca en el compartimiento de equipaje de un avión de categoría normal que tiene un letrero que indica 100 libras de capacidad. Si este avión se somete a un factor de carga positivo de 3.5 Gs, la carga total del equipaje sería:", "o": ["315 libras y excedería la limitante.", "315 libras y no excedería la limitante.", "350 libras y no excedería la limitante."], "a": 1, "e": "Cada compartimento de carga debe diseñarse para su peso máximo de contenido rotulado en relación con los factores de carga críticos. Las aeronaves de categoría normal con un peso bruto de menos de 4,000 libras están diseñadas para un factor de carga de maniobra de 3.8 veces el peso de la aeronave o 3.8 Gs. Por tanto, un factor de carga de 3.5 Gs no sería excesivo. El factor de carga es la relación entre una carga dada y su peso. Por lo tanto: 90.0 lbs de peso x 3.5 Gs = 315.0 lbs de carga."},
  {"id": 403, "s": 7, "q": "En aeropuertos de mayor altitud, el piloto debe saber que la velocidad indicada:", "o": ["no cambiará, pero la velocidad respecto a tierra será mayor.", "será mayor, pero la velocidad respecto a tierra no cambiará.", "deberá aumentarse para compensar el aire más fino."], "a": 0, "e": "Un avión en altitud aterrizará a la misma velocidad indicada que a nivel del mar, pero debido a la menor densidad del aire, tendrá una mayor velocidad verdadera. Si la velocidad verdadera es mayor, la velocidad respecto a tierra será mayor."},
  {"id": 404, "s": 7, "q": "Las tablas de rendimiento de una aeronave para despegue y ascenso se basan en:", "o": ["altitud de presión / densidad.", "altitud de la cabina.", "altitud verdadera."], "a": 0, "e": "La presión y la altitud de densidad son los factores utilizados en las tablas de rendimiento de la aeronave para el despegue y el ascenso. La respuesta (B) es incorrecta porque la altitud de la cabina es la altitud a la que se encuentra una cabina presurizada. La respuesta (C) es incorrecta porque la altitud verdadera es la altura sobre el nivel del mar. Las cartas aeronáuticas muestran las elevaciones de los obstáculos en altitud real."},
  {"id": 405, "s": 7, "q": "¿Qué efecto, si lo hubiera, tendría un cambio en la temperatura ambiente o la densidad del aire en el rendimiento de un motor a reacción?", "o": ["A medida que disminuye la densidad del aire, aumenta el empuje.", "A medida que aumenta la temperatura, aumenta el empuje.", "A medida que aumenta la temperatura, el empuje disminuye."], "a": 2, "e": "Un aumento de altitud hace que el flujo de aire del motor disminuya de una manera casi idéntica a la relación de densidad de altitud. Esto provoca una disminución significativa del empuje en altitud frente al empuje a nivel del mar a medida que aumenta la altitud. Un aumento en la temperatura del aire de entrada proporcionará una menor energía del gas de combustión y provocará una menor velocidad del chorro"},
  {"id": 406, "s": 7, "q": "¿Cuál es la temperatura estándar a 10,000 pies?", "o": ["-5 °C.", "-15 °C.", "+5 °C."], "a": 0, "e": "La temperatura estándar al nivel del mar es de 15 °C. La gradiente estándar de temperatura es de 2 °C / 1,000 pies. 10 x 2 = -20 °C disminución de temperatura a 10,000 pies + 15° - 20° = -5 °C temperatura estándar a 10,000 pies."},
  {"id": 407, "s": 7, "q": "¿Cuál es la temperatura estándar a 20.000 pies?", "o": ["-15 °C.", "-20 °C.", "-25 °C."], "a": 2, "e": "La temperatura estándar al nivel del mar es de 15 °C. La gradiente estándar de temperatura es de 2 °C / 1,000 pies. 20 x -2 = -40 °C disminución de temperatura a 20,000 pies 15 °C - 40 °C = -25 °C temperatura estándar a 20,000 pies"},
  {"id": 408, "s": 7, "q": "¿Cuáles son los valores estándar de temperatura y presión a nivel del mar?", "o": ["15 °C y 29,92\" Hg.", "59 °F y 1013.2\" Hg.", "15 °C y 29.92 Mb."], "a": 0, "e": "En la atmósfera estándar, la presión a nivel del mar es de 29,92 pulgadas de mercurio o 1013,2 hectopascales. La temperatura a nivel medio del mar es de 15 °C (59 °F)."},
  {"id": 409, "s": 7, "q": "Cuando se desvía a un aeropuerto alterno debido a una emergencia, los pilotos deben:", "o": ["depender de la radio como método principal de navegación.", "ascender a una altitud mayor porque será más fácil identificar los puntos de la ruta.", "aplicar cálculos básicos, estimaciones y otros atajos apropiados para desviarse al nuevo curso lo antes posible."], "a": 2, "e": "Los cálculos de rumbo, tiempo, velocidad y distancia en vuelo requieren los mismos procedimientos básicos que se utilizan en la planificación previa al vuelo. Sin embargo, debido a las limitaciones de espacio en la cabina y al equipo disponible, y debido a que la atención del piloto debe dividirse entre la solución del problema y la operación de la aeronave, el piloto debe aprovechar todos los atajos posibles y los cálculos básicos. La respuesta (A) es incorrecta porque cualquier forma de navegación es apropiada. La respuesta (B) es incorrecta porque los ascensos pueden consumir tiempo y combustible."},
  {"id": 410, "s": 7, "q": "¿Qué efecto tiene una pendiente positiva de pista en el rendimiento del despegue?", "o": ["Aumenta la velocidad de despegue.", "Aumenta la distancia de despegue.", "Disminuye la distancia de despegue."], "a": 1, "e": "El efecto de la pendiente de la pista sobre la distancia de despegue se debe a la componente del peso a lo largo de la trayectoria inclinada de la aeronave. Una pendiente positiva contribuiría con una componente de fuerza de retardo, mientras que una pendiente negativa contribuiría con un componente de fuerza de aceleración. En el caso de una pendiente ascendente (positiva), el componente de fuerza de retardo se suma a la resistencia y la fricción de rozamiento para reducir la fuerza neta de aceleración."},
  {"id": 411, "s": 7, "q": "Al iniciar un sobrepaso, el piloto debe tener en cuenta que:", "o": ["las comunicaciones por radio son clave para alertar a otras aeronaves en el circuito de que se está realizando una maniobra de sobrepaso.", "el avión está compensado para una condición potencia reducida y la aplicación de potencia de despegue hará que la nariz suba rápidamente.", "los flaps deben elevarse lo más rápido posible para reducir la resistencia y aumentar la velocidad para efectuar el sobrepaso adecuadamente."], "a": 1, "e": "Cuando se aplica potencia de despegue, por lo general se hace necesario ejercer una presión considerable sobre los controles para mantener el rumbo y una actitud de ascenso segura. Dado que el avión está compensado para la aproximación (una condición de baja potencia y velocidad), la aplicación de la potencia máxima permitida requiere una presión considerable sobre el control para mantener una actitud de ascenso. Esta aplicación de potencia tiende a levantar la nariz de la aeronave de forma repentina y produce una tendencia de viraje hacia la izquierda. La respuesta (A) es incorrecta porque la potencia es la primera preocupación del piloto en una maniobra de sobrepaso; volar antes de comunicar. La respuesta (C) es incorrecta porque los flaps solo deben retraerse una vez que se haya aplicado la potencia y se haya establecido la actitud de ascenso adecuada."},
  {"id": 412, "s": 7, "q": "En los cálculos de peso y balance, el peso básico vacío incluye el peso de la estructuradel avión, los motores y todo el equipo opcional instalado. El peso básico vacío también incluye:", "o": ["el combustible no utilizable, los fluidos requeridos para el funcionamiento de la aeronave y todo el aceite.", "todo el combustible utilizable, aceite, fluido hidráulico, pero no incluye el peso del piloto, los pasajeros ni el equipaje.", "todo combustible y aceite utilizable, pero no incluye ningún equipo o instrumento de radio que haya sido instalado por alguien que no sea el fabricante."], "a": 0, "e": "El peso básico vacío incluye combustible no utilizable, los líquidos requeridos para el funcionamiento de la aeronave y todo el aceite."},
  {"id": 413, "s": 7, "q": "Si todas las unidades de índice son positivas al realizar los cálculos de peso y balance, el datum estaría ubicado en:", "o": ["la línea central de las ruedas principales.", "la nariz o delante del avión.", "la línea central de la rueda de nariz o la rueda de cola, según el tipo de avión."], "a": 1, "e": "Por lo general, el brazo (unidad de índice) de una estación en la aeronave está expresado en pulgadas detrás del datum. Un brazo positivo indica que la posición del objeto está detrás del datum. Si todas las unidades de índice son positivas, el datum debe estar al menos en la nariz de la aeronave. La respuesta (A) es incorrecta porque el motor tendría un brazo negativo si el datum estuviera en la línea central de las ruedas principales. La respuesta (C) es incorrecta porque la hélice tendría un brazo negativo si el datum estuviera en la línea central de la rueda de nariz o la rueda de cola."},
  {"id": 414, "s": 7, "q": "¿Con cuál de los siguientes métodos se puede determinar el CG de una aeronave?", "o": ["Dividiendo los brazos totales por los momentos totales.", "Multiplicar el total de brazos por el peso total.", "División de momentos totales por peso total."], "a": 2, "e": "El momento total es el peso del avión por la distancia entre el datum y el CG. Por lo tanto: CG = Momento total ÷ Peso total."},
  {"id": 415, "s": 7, "q": "DADO: Peso A: 155 libras a 45 pulgadas después del datum. Peso B: 165 libras a 145 pulgadas después del datum. Peso C: 95 libras a 185 pulgadas después del datum. Con baseen esta información, ¿dónde se ubicaría el CG con respecto al datum?", "o": ["86.0 pulgadas.", "116.8 pulgadas.", "125.0 pulgadas."], "a": 1, "e": "1. El brazo es la distancia indicada después del datum para cada elemento: Peso x brazo = Momento 155 x 45 = 6,975 para A 165 x 145 = 23,925 para B + 95x 185 = + 17,575 para C Totales 415 lbs 48,475 lbs-in 2. Momentos ÷ Peso total = Ubicación del CG 48,475 ÷ 415 = 116.8 pulgadas."},
  {"id": 416, "s": 7, "q": "DADO: Peso A: 140 libras a 17 pulgadas después del datum. Peso B: 120 libras a 110 pulgadas después del datum. Peso C: 85 libras a 210 pulgadas después del datum. Con base en esta información, el CG se ubicaría ¿a qué distancia del datum?", "o": ["89.11 pulgadas.", "96.89 pulgadas.", "106.92 pulgadas."], "a": 1, "e": "1. El brazo es la distancia indicada después del datum para cada elemento: Peso x brazo = Momento 140 x 17 = 2,380 para A 120 x 110 = 13,200 para B + 85x 210 = + 17,850 para C 345 libras 33,430 libras-pulg 2. Momentos ÷ Peso total = Ubicación del CG 33,430 ÷ 345 = 96.89 pulgadas"},
  {"id": 417, "s": 7, "q": "DADO: Peso A: 135 libras a 15 pulgadas después del datum. Peso B: 205 libras a 117 pulgadas después del datum. Peso C: 85 libras a 195 pulgadas después del datum. Con base en esta información, el CG se ubicaría ¿a qué distancia del datum?", "o": ["100.2 pulgadas", "109 pulgadas", "121.7 pulgadas"], "a": 0, "e": "1. El brazo es la distancia indicada después del datum para cada elemento: Peso x brazo = Momento 135x 15 = 2,025 para A 205 x 117 = 23,985 para B + 85x 195 = + 16,575 para C 425 libras 42,585 libras-pulg. 2. Momentos ÷ Peso total = Ubicación del CG 42,585 ÷ 425 = 100.2 pulgadas"},
  {"id": 418, "s": 7, "q": "DADO: Peso A: 175 libras a 135 pulgadas después del datum. Peso B: 135 libras a 115 pulgadas después del datum. Peso C: 75 libras a 85 pulgadas después del datum. ¿A qué distancia del datum estaría el CG correspondiente a la sumatoria de estos pesos?", "o": ["91.76 pulgadas.", "111.67 pulgadas.", "118,24 pulgadas."], "a": 2, "e": "1. El brazo es la distancia indicada después del datum para cada elemento: Peso x brazo = Momento 175 x 135 = 23,625 para A 135 x 115= 15,525 para B +75x85 =+ 6,375 para C 385 libras 45,525 libras-pulg. 2. Momentos ÷ Peso total = Ubicación del CG 45,525 ÷ 385 = 118.25 pulgadas"},
  {"id": 419, "s": 7, "q": "DADO: Peso total 4,137 lb. Posición del CG 67.8 pulgadas. Consumo de combustible 13.7 GPH. Posición del CG del combustible 68.0. Después de 1 hora y 30 minutos de vuelo, el CG se ubicaría en la estación.", "o": ["67.79", "68.79", "70.78"], "a": 0, "e": "1. Encuentre el cambio de peso: 13.7 GPH durante 1.5 horas = 20.55 gal 20.55 galones x 6 libras / galón = 123.3 libras 2. El nuevo peso total es 4,137 — 123.3 = 4,013.7 3. La distancia entre el CG y el brazo de combustible es 68.0 - 67.8 = 0.2 4. Reemplace los valores en la fórmula y realice una multiplicación cruzada: 123.3 ÷ 4013.7 = cambio de CG + 0.2 = 24.66 = 4,013.7 (cambio de CG) 5. Divida para determinar el cambio de CG: 24.66 / 4,013.7 = cambio CG = 0.00614 123.3 ÷ 4013.7 = cambio de CG + 0.2 = 0,00614 pulgadas 6. Calcule el nuevo CG: CG inicial 67.80000 - Cambio de CG .00614 = Nueva posición del CG 67.79386."},
  {"id": 420, "s": 7, "q": "Una aeronave se carga con un peso de rampa de 3,650 libras y tiene un CG de 94.0, aproximadamente cuánto equipaje tendría que moverse desde el área de equipaje trasera en la estación 180 al área de equipaje delantera en la estación 40 para mover el CG a 92.0?", "o": ["52.14 libras.", "62.24 libras.", "78.14 libras."], "a": 0, "e": "Determine la cantidad de peso que se moverá: Peso desplazado ÷ Peso total = cambio en CG (94 - 92) + Dist. Peso desplazado (180 - 40) Peso a cambiar ÷ 3,650 lbs = 2.0 ÷ 140 3,650 x 2 + 140 = 7,300 + 140 = 52.143."},
  {"id": 421, "s": 7, "q": "Un avión se carga con un peso bruto de 4,800 libras, con tres piezas de equipaje en el compartimiento de equipaje trasero. El CG se encuentra a 98 pulgadas después del datum, lo que indica que está 1 pulgada por fuera del límite trasero. Si el equipaje que pesa 90 libras se mueve desde el compartimiento de equipaje trasero (145 pulgadas después del datum) al compartimiento delantero (45 pulgadas después del datum), ¿cuál es el nuevo CG?", "o": ["96.13 pulgadas después del datum.", "95.50 pulgadas después del datum."], "a": 0, "e": "1. Cambio en CG = Peso desplazado x Distancia desplazada ÷ Peso total 90 x (145 - 45) ÷ 4,800 = 1.875 pulgadas 2. Dado que el peso se desplazó hacia adelante, el CG también se mueve hacia adelante. El cambio de 1.875 pulgadas se resta del CG original. Nuevo CG = 98.0 — 1.875 = 96.13 pulgadas."},
  {"id": 422, "s": 7, "q": "DADO: Peso total 3,037 Ib. Posición del CG 68.8. Consumo de combustible 12.7 GPH. Posición del. CG del combustible 68.0. Después de 1 hora y 45 minutos de vuelo, ¿en qué estación estaría el CG?", "o": ["68.77.", "68.83.", "69.77."], "a": 1, "e": "1. Encuentre el cambio de peso: 12.7 GPH durante 1.75 horas = 22.23 gal 22.23 galones x 6 libras / galón = 133.35 libras 2. El nuevo peso total es 3,037 — 133.35 = 2,903.65 3. La distancia entre el CG y el brazo de combustible es 68.8 — 68.0 = 0.8 4. Reemplace los valores en la fórmula y realice una multiplicación cruzada: 133.35 ÷ 2,903.65 = cambio de CG + .8 = 106.68 = 2,903.65 (cambio de CG) 5. Divida para determinar el cambio de CG: 106.68 / 2,903.65 = cambio de CG = .03674 pulgadas 6. Calcule el nuevo CG: CG original 68.80000 + cambio CG .03674 = Nuevo CG 68.83674."},
  {"id": 423, "s": 7, "q": "Con respecto a la técnica requerida para una corrección de viento cruzado en eldespegue, un piloto debe usar:", "o": ["presión de los alerones de cara al viento e iniciar la rotación a una velocidad normal tanto aviones con patín de cola y los de tren triciclo.", "presión del timón de dirección a la derecha, presión de los alerones de cara al viento y una velocidad de rotación superior a la normal tanto en aviones con tren triciclo como en los de tren convencional.", "timón de dirección según sea necesario para mantener el control direccional, presión de los alerones de cara al viento y una velocidad de despegue superior a la normal en los aviones de tren convencional y tren triciclo."], "a": 2, "e": "Se requiere timón de dirección en todo momento para mantener el control direccional. La presión de los alerones de cara al viento mantendrá el ala baja y evitará derrapamiento lateral. Es deseable una velocidad de rotación ligeramente superior a la normal para asegurar un despegue positivo y evitar que la aeronave vuelva a tomar contacto con la pista. La respuesta (A) es incorrecta porque la velocidad de rotación debe aumentarse ligeramente y se debe aplicar presión sobre el timón de dirección para mantener el control direccional. La respuesta (B) es incorrecta porque se debe aplicar presión en el timón de dirección para mantener el control direccional, tanto hacia la derecha como hacia la izquierda."},
  {"id": 424, "s": 7, "q": "Cuando se encuentran turbulencias durante la aproximación para el aterrizaje, ¿qué acción se recomienda y por qué motivo principal?", "o": ["Aumente la velocidad ligeramente por encima de la velocidad de aproximación normal para lograr un control más positivo.", "Disminuya la velocidad ligeramente por debajo de la velocidad de aproximación normal para evitar sobrecargar el avión.", "Aumente la velocidad ligeramente por encima de la velocidad de aproximación normal para penetrar la turbulencia lo más rápido posible."], "a": 0, "e": "Las aproximaciones con motor a una velocidad ligeramente superior a la velocidad de aproximación normal deben utilizarse para aterrizar en aire significativamente turbulento. Esto proporciona un control más positivo del avión cuando se experimentan fuertes ráfagas de viento horizontal o corrientes ascendentes y descendentes. La respuesta (B) es incorrecta porque, dado que la velocidad de aproximación está muy por debajo de V (A), no se producirán daños estructurales. La respuesta (C) es incorrecta porque el aumento de la velocidad de aproximación es para aumentar la efectividad del control, no para volar a través de turbulencias más rápido."},
  {"id": 425, "s": 7, "q": "Si experimenta una falla de motor en un avión monomotor después del despegue, debe:", "o": ["establecer la actitud de planeo adecuada.", "virar para enfrentar el viento", "ajustar el cabeceo para mantener VY."], "a": 0, "e": "En el caso de una falla del motor en el ascenso inicial, la primera responsabilidad del piloto es mantener el control de la aeronave. En una actitud de ascenso sin potencia, el avión está en un ángulo de ataque de pérdida o cerca a éste. Al mismo tiempo, es posible que el piloto aún mantenga el timón de dirección deflectado a la derecha. El piloto debe bajar inmediatamente la nariz para evitar una pérdida mientras deflecta el timón de dirección para asegurar un vuelo coordinado. No se debe intentar volver a la pista desde la que se despegó. El piloto debería establecer un planeo controlado hacia un área de aterrizaje adecuada, preferiblemente dentro del rumbo de vuelo de la aeronave."},
  {"id": 426, "s": 7, "q": "¿Qué tipo de aproximación y aterrizaje se recomienda en condiciones de ráfagas de viento?", "o": ["Aproximación con potencia y aterrizaje con potencia.", "Aproximación sin potencia y aterrizaje con potencia.", "Aproximación con potencia y aterrizaje sin potencia."], "a": 0, "e": "Las aproximaciones con motor a una velocidad ligeramente superior a la velocidad de aproximación normal deben utilizarse para aterrizar en aire significativamente turbulento. Estas aproximaciones para aterrizar generalmente se realizan a la velocidad de aproximación normal más la mitad del factor de ráfaga de viento. Se debe utilizar una cantidad adecuada de potencia para mantener la velocidad correcta en todo momento."},
  {"id": 427, "s": 7, "q": "Un aterrizaje adecuado con viento cruzado en una pista requiere que, en el momento del aterrizaje:", "o": ["la dirección de desplazamiento del avión y su eje lateral estén perpendicular a la pista.", "la dirección de desplazamiento del avión y su eje longitudinal estén paralelos a la pista.", "el ala a favor del viento debe bajarse lo suficiente para eliminar la tendencia del avión a derrapar."], "a": 1, "e": "La dirección del desplazamiento y el eje longitudinal deben estar paralelos a la pista o se producirá un derrape, con posibles daños a la aeronave. La respuesta (A) es incorrecta porque la dirección de desplazamiento del avión debe ser paralela a la pista. La respuesta (C) es incorrecta porque el ala a favor del viento debe bajarse para eliminar el derrape."},
  {"id": 428, "s": 8, "q": "¿Cuál es el máximo error de marcación (+ o -) permitido para una comprobación operativa del equipo VOR cuando se utiliza una señal de prueba en tierra aprobada?", "o": ["4 grados.", "6 grados.", "8 grados."], "a": 0, "e": "El máximo error de marcación permitido es de +4° cuando se utiliza un VOR."},
  {"id": 429, "s": 8, "q": "¿Qué datos debe anotar en la bitácora de la aeronave o en otro registro, el piloto que realiza una comprobación operativa del VOR para operaciones IFR?", "o": ["Nombre o identificación del VOR, lugar de la comprobación operativa, importe del error de marcación y fecha de la comprobación.", "Fecha del chequeo, lugar del chequeo operacional, error de marcación y firma.", "Nombre o identificación del VOR, importe del error de porte, fecha del chequeo y firma."], "a": 1, "e": "Cada persona que realice una comprobación operativa del VOR anotará la fecha, el lugar, el error de marcación y firmará el registro de la aeronave u otro registro."},
  {"id": 430, "s": 8, "q": "Cuando se navega RNAV basado en los sensores VOR/DME, la selección de un VORque no tiene servicio DME:", "o": ["provocará la pérdida de la capacidad RNAV.", "no afecta la capacidad de navegación.", "no afecta a la navegación siempre que el GPS funcione adecuadamente."], "a": 0, "e": "Las unidades RNAV basadas en VOR/DME necesitan tanto señales VOR como DME para funcionar en modo RNAV, Si la radioayuda seleccionada es un VOR sin DME, el modo RNAV no funcionará. Cuando el DME no está disponible, la unidad RNAV funcionará como un receptor VOR con capacidad DME en modo VOR (o no RNAV)."},
  {"id": 431, "s": 8, "q": "A partir de los siguientes datos indique un valor aproximado para la altitud por densidad: Altitud de presión 12,000 pies. Temperatura real del aire +50 °F", "o": ["11,900 pies.", "14,130 pies.", "18,150 pies."], "a": 1, "e": "Utilizando un computador de vuelo E6B: 1. Convierta 50 °F a *C utilizando la tabla de conversión de temperatura que se encuentra en la parte inferior del computador de vuelo, de donde obtendrá 10 °C. 2. En la casilla de la derecha \"Altitud de la densidad\", observe que la escala sobre la casilla está demarcada como temperatura del aire (”C). La escala dentro de la casilla está identificada como altitud de presión (en miles de pies). Gire el disco y coloque la altitud de presión de 12,000 pies frente a una temperatura del aire de 10 °C. La altitud de densidad mostrada en la ventana de altitud de densidad es de 14,130 pies. Utilizando un CX-3: 1. En el menú FLT seleccione Altitud. 2. Introduzca una PAIt de 12,000 FT y OAT de 50 °F para obtener una DAIt de 14,134 FT o aproximadamente 14,130 pies."},
  {"id": 432, "s": 8, "q": "A partir de los siguientes datos indique un valor aproximado para la altitud por densidad: Altitud de presión 5.000 pies. Temperatura real del aire +30 °C", "o": ["7,200 pies.", "7,800 pies.", "9,000 pies."], "a": 1, "e": "Utilizando un computador de vuelo E6-B: 1. Refiérase a la casilla \"Density Altitude\". Observe que la escala situada encima está identificada como “air temperature (*C)”, la escala dentro de la casilla está identificada como “pressure altitude (in thousand of feet)”. Gire el disco y ajuste la altitud de presión (pressure altitude) de 5,000 pies frente a una temperatura del aire (air temperature) 30 °C. 2. La altitud por densidad mostrada en la ventana es de 7.800 pies."},
  {"id": 433, "s": 8, "q": "A partir de los siguientes datos indique un valor aproximado para la altitud por densidad: Altitud de presión 6,000 pies. Temperatura real del aire +30 °F", "o": ["9,000 pies.", "5,500 pies.", "5,000 pies."], "a": 1, "e": "Utilizando un E6B: 1. Convierta 30 °F a *C utilizando la tabla de conversión de temperatura que se encuentra en la parte inferior del E6-B o del computador de vuelo CX-3. El resultado es -1 °C. 2. Consulte la ventana de la derecha \"Altitud de la densidad\". Observe que la escala sobre la casilla etiquetada como temperatura del aire (?C). La escala dentro de la propia casilla está etiquetada como altitud de presión (en miles de pies). Gire el disco y coloque la altitud de presión de 6,000 pies frente a una temperatura del aire de -1 °C. La altitud de densidad mostrada en la ventana es de 5,500 pies. Utilizando un CX-3: 1. En el menú FLT seleccione Altitud. 2. Introduzca una PAIt de 6,000 FT y OAT de 30 °F para obtener una DAIt de 5,494 FT o aproximadamente 5,500 pies."},
  {"id": 434, "s": 8, "q": "A partir de los siguientes datos indique un valor aproximado para la altitud por densidad: Altitud de presión 7,000 pies. Temperatura real del aire (TAT) + 15 °C", "o": ["5,000 pies.", "8,500 pies.", "9,500 pies."], "a": 1, "e": "Utilizando un computador de vuelo E6-B: 1. Refiérase a la casilla \"Density Altitude\". Observe que la escala situada encima está identificada como “air temperatura” (*C), la escala dentro de la casilla está identificada como “pressure altitude (in thousand of feet). Gire el disco y ajuste la altitud de presión (pressure altitude) de 7,000 pies frente a una temperatura del aire (air temperature) 15 °C. 2. Laaltitud de densidad mostrada en la ventana es de 8.500 pies."},
  {"id": 435, "s": 8, "q": "Una aeronave desciende a un aeropuerto con las siguientes condiciones: Altitud de crucero 6.500 pies. Elevación del aeropuerto 700 pies. Desciende a 800 pies AGL. Velocidad de descenso 500 ft/min. Velocidad promedio real 110 nudos. Curso verdadero 335°. Velocidad promedio del viento 060° a 15 nudos. Variación 3° W. Desviación +2°. Consumo medio de combustible 8.5 gal/h. Determine el tiempo aproximado de descenso, el rumbo de la brújula (CH), la distancia y el combustible consumido durante el descenso:", "o": ["10 minutos, 348°, 18 NM, 1.4 galones.", "10 minutos, 355°, 17 NM, 2.4 galones.", "12 minutos, 346°, 18 NM, 1.6 galones."], "a": 0, "e": "1. Calcular el tiempo de descenso: Tiempo = distancia vertical ÷ velocidad vertical Donde distancia vertical = 6.500 - 1.500 = 5.000 pies Tiempo = 5.000 pies ÷ 500 FPM = 10 minutos = 0,1667 h 2. Calcular el combustible requerido: 8.5 gal/h x 0.1667 h = 1.42 galones 3. Calcular el ángulo de corrección del viento y la velocidad con respecto al suelo utilizando un triángulo de viento: WCA = 8° derecha Velocidad con respecto al suelo = 108 nudos 4. Calcular el rumbo verdadero (TH = TC + WCA): 335° + 8° = 343° TH 5. Calcular el rumbo de la brújula (CH = TH + Var + Dev): 343° + 3° + 2° = 348 * CH 6. Calcular la distancia recorrida: Distancia = 108 nudos x 0.1667 hora = 18 NM."},
  {"id": 436, "s": 8, "q": "Una aeronave desciende a un aeropuerto con las siguientes condiciones: Altitud de crucero 7.500 pies. Elevación del aeropuerto 1.300 pies. Desciende a 800 pies AGL. Velocidad de descenso 300 ft/min. Velocidad promedio real 120 nudos. Curso verdadero 165°. Velocidad promedio del viento 240° a 20 nudos. Variación 4° E. Desviación -2°. Consumo medio de combustible 9.6 gal/h. Determine el tiempo aproximado de descenso, el rumbo de la brújula (CH), la distancia y el combustible consumido durante el descenso:", "o": ["16 minutos, 168°, 30 NM, 2.9 galones.", "18 minutos, 164°, 34 NM, 3.2 galones.", "18 minutos, 168°, 34 NM, 2.9 galones."], "a": 2, "e": "1. Calcular el tiempo de descenso: Tiempo = distancia vertical ÷ velocidad vertical Donde distancia vertical = 7,500 — 2,100 = 5,400 pies Tiempo = 5,400 pies ÷ 300 FPM = 18 minutos = 0,3 horas 2. Calcular el combustible requerido: 9.6 gal/h x 0.3 hora = 2.88 galones 3. Calcular el ángulo de corrección del viento y la velocidad con respecto al suelo utilizando un triángulo de viento: WCA = 9° derecha Velocidad con respecto al suelo = 113 nudos 4. Calcular el rumbo verdadero (TH = TC + WCA): 165° + 9° = 174° TH 5. Calcular el rumbo de la brújula (CH = TH + Var + Dev): 174° - 4° - 2° = 168° CH 6. Calcular la distancia recorrida: Distancia = 113 nudos x 0.3 horas = 33.9 NM."},
  {"id": 437, "s": 8, "q": "Una aeronave desciende a un aeropuerto con las siguientes condiciones: Altitud de crucero 10.500 pies. Elevación del aeropuerto 1.700 pies. Desciende a 1.000 pies AGL. Velocidad de descenso 600 ft/min. Velocidad promedio real 135 Nudos. Curso verdadero 263°. Velocidad promedio del viento 330° a 30 Nudos. Variación 7° E. Desviación +3°. Consumo medio de combustible 11.5 gal/h. Determine el tiempo aproximado de descenso, el rumbo de la brújula (CH), la distancia y el combustible consumido durante el descenso:", "o": ["9 minutos, 274°, 26 NM, 2.8 galones.", "13 minutos, 274°, 28 NM, 2.5 galones.", "13 minutos, 271°, 26 NM, 2.5 galones."], "a": 2, "e": "1. Calcula el tiempo de descenso: Tiempo = distancia vertical ÷ velocidad vertical Donde distancia vertical = 10,500 — 2,700 = 7,800 pies Tiempo = 7,800 pies ÷ 600 FPM = 13 minutos = 0.2167 hora 2. Calcule el combustible requerido: 11.5 gal/h x 0.2167 hora = 2.49 galón 3. Calcule el ángulo de corrección del viento y la velocidad con respecto suelo utilizando un triángulo de viento: WCA = 12° derecha Velocidad con respecto al suelo = 120 nudos 4. Calcule el rumbo verdadero (TH = TC + WCA): 263° + 12° = 275° TH 5. Calcular el rumbo de la brújula (CH = TH + Var + Dev): 275° - 77 + 3 = 271 CH 6. Calcule la distancia volada: 120 nudos x 0.2167 hora = 26 NM."},
  {"id": 438, "s": 8, "q": "Si el consumo de combustible es de 80 libras por hora y la velocidad con respecto al suelo es de 180 nudos, ¿Cuánto combustible se necesita para que la aeronave recorra 460 NM?", "o": ["205 libras.", "212 libras.", "460 libras."], "a": 0, "e": "1. Calcule el tiempo en ruta: 460 NM ÷ 180 nudos = 2.556 horas 2. Determine el consumo de combustible: 80 libras/hora x 2.56 horas = 204.8 libras."},
  {"id": 439, "s": 8, "q": "Si una aeronave consume 95 libras de combustible por hora a una altitud de crucero de 6.500 pies y la velocidad con respecto al suelo es de 173 nudos, ¿Cuánto combustible se necesita para recorrer 450 NM?", "o": ["248 libras.", "265 libras.", "284 libras."], "a": 0, "e": "1. Calcule el tiempo en ruta: 450 NM = 173 nudos = 2.6 horas 2. Determine el consumo de combustible: 95 libras/hora x 2.6 horas = 247 libras."},
  {"id": 440, "s": 8, "q": "Si una aeronave consume 12.5 galones de combustible por hora a una altitud de crucero de 8,500 pies y la velocidad con respecto al suelo es de 145 nudos, ¿cuánto combustible necesita para recorrer 435 NM?", "o": ["27 galones.", "34 galones.", "38 galones."], "a": 2, "e": "1. Calcular el tiempo en ruta: 435 NM ÷ 145 nudos = 3 horas 2. Determinar el consumo de combustible: 12.5 GPH x 3 horas = 37.5 galones."},
  {"id": 441, "s": 8, "q": "Si una aeronave consume 9.5 galones de combustible por hora a una altitud de crucero de 6,000 pies y la velocidad con respecto al suelo es de 135 nudos, ¿Cuánto combustible se necesita para recorrer 420 NM?", "o": ["27 galones.", "30 galones.", "35 galones."], "a": 1, "e": "1. Calcule el tiempo en ruta: 420 NM ÷ 135 nudos = 3.11 horas 2. Determine el consumo de combustible: 9.5 GPH x 3.11 horas = 29.5 galones."},
  {"id": 442, "s": 8, "q": "Si una aeronave consume 14.7 galones de combustible por hora a una altitud de crucero de 7,500 pies y la velocidad con respecto al suelo es de 167 nudos, ¿Cuánto combustible se necesita para recorrer 560 NM?", "o": ["50 galones.", "53 galones.", "57 galones."], "a": 0, "e": "1. Calcule el tiempo en ruta: 560 NM ÷ 167 nudos = 3.35 horas 2. Determine el consumo de combustible: 14.8 GPH x 3.35 horas = 49.6 galones."},
  {"id": 443, "s": 8, "q": "Si el consumo de combustible es de 14.7 galones por hora y la velocidad con respecto al suelo es de 157 nudos, ¿Cuánto combustible se necesita para que la aeronave recorra 612 NM?", "o": ["58 galones.", "60 galones.", "64 galones."], "a": 0, "e": "1. Calcule el tiempo en ruta: 612 NM ÷ 157 nudos = 3.9 horas 2. Determine el consumo de combustible: 14.7 GPH x 3.9= 57.33 galones."},
  {"id": 444, "s": 8, "q": "Con los siguientes datos determine la dirección y velocidad del viento. urso verdadero 105°.Rumbo verdadero 085°. Velocidad verdadera (TAS) 95 nudos. Velocidad con respecto al suelo 87 nudos.", "o": ["020° y 32 nudos.", "030° y 38 nudos.", "200° y 32 nudos."], "a": 0, "e": "Utilizando un ordenador E6-B: 1. Gire la carátula del azimut y ajuste 105° en la escala “TRUE INDEX”. 2. Deslice el tablero para ajustar en la escala de velocidad con respecto al suelo, 87 nudos. 3. Determine el ángulo por corrección de viento WCA comparando el curso con el rumbo 105° - 085° = 20° a la izquierda Marque el WCA en el arco de la TAS, 95 nudos. Gire la carátula del azimut hasta que el punto marcado quede sobre la línea central. 6. La dirección del viento estará indicada en la escala del “TRUE INDEX” y la velocidad del viento corresponderá al número de unidades entre el agujero en el centro de la carátula y el punto marcado: 020° y 32 nudos."},
  {"id": 445, "s": 8, "q": "Con los siguientes datos determine la dirección y velocidad del viento. Curso verdadero 345°. Rumbo verdadero 355°. Velocidad verdadera (TAS) 85 nudos. Velocidad con respecto al suelo 95 nudos. Determine la dirección y velocidad del viento:", "o": ["095° y 19 nudos.", "113° y 19 nudos.", "238° y 18 nudos."], "a": 1, "e": "Utilizando un computador de vuelo E6-B: 1. Gire la carátula del azimut y ajuste 345° en la escala “TRUE INDEX”. 2. Deslice el tablero para ajustar en la escala de velocidad con respecto al suelo, 95 nudos. 3. Determine el ángulo por corrección de viento WCA comparando el curso con el rumbo. 345° - 355 = 10° a la derecha 4. Marque el WCA en el arco de la TAS: 85 nudos. 5. Gire la carátula del azimut hasta que el punto marcado quede sobre la línea central. 6. La dirección del viento estará indicada en la escala del “TRUE INDEX” y la velocidad del viento corresponderá al número de unidades entre el agujero en el centro de la caratula y el punto marcado. 114° y 19 nudos."},
  {"id": 446, "s": 8, "q": "Con los siguientes datos determine el tiempo en ruta y el consumo de combustible: Distancia fuera de curso 9 millas. Distancia volada 95 millas. Distancia por volar 125 millas. Para dirigirse al destino, el ángulo total de corrección sería:", "o": ["4°.", "6°.", "10%,"], "a": 2, "e": "1. Determine el número de grados de corrección necesarios para estar paralelo el curso deseado: Millas fuera de rumbo x 60 ÷ Número de millas voladas = Corrección para estar paralelo al curso deseado. 9 x 60 ÷ 95 = 5.68° para estar paralelo al curso deseado. 2. Determine el número de grados de corrección adicionales necesarios para interceptar el rumbo: Millas fuera de rumbo x 60 ÷ Número de millas restantes = Corrección para interceptar. 9 x 60 ÷ 125 = 4.32° adicionales para interceptar. 3. Sume el número de grados necesarios para paralizar el rumbo y el número de grados necesarios para interceptar el rumbo para encontrar el ángulo de corrección total necesario para converger en el destino: 5.68° para paralizar + 4.32° para interceptar = 10.00° totales para dirigirse al destino."},
  {"id": 447, "s": 8, "q": "Con los siguientes datos determine el tiempo en ruta y el combustible consumido. Viento 175° a 20 nudos. Distancia 135 NM. Curso verdadero 075°. Velocidad verdadera (TAS) 80 nudos. Consumo de combustible 105 Ib/h.", "o": ["1 hora 28 minutos y 73.2 libras.", "1 hora 38 minutos y 158 libras.", "1 hora 40 minutos y 175 libras."], "a": 2, "e": "1. Calcular la velocidad con respecto al suelo: Dirección del viento 175° Velocidad del viento 20 nudos Rumbo 075° Velocidad real del aire (TAS) 80 nudos Velocidad con respecto al suelo 81,0 nudos 2. Determine el tiempo en ruta: 135 NM ÷ 81 nudos = 1.67 horas = 1 hora 40 minutos 3. Calcular el combustible consumido: 105.0 libras/hora x 1.67 horas = 175.0 libras."},
  {"id": 448, "s": 8, "q": "Una aeronave sale de un aeropuerto en las siguientes condiciones: Elevación del aeropuerto 1,000 pies. Altitud de crucero 9,500 pies. Velocidad de ascenso 500 ft/min. Velocidad promedio real 135 nudos. Curso verdadero 215°, Velocidad promedio del viento 290° a 20 nudos. Variación 3° W. Desviación -2°. Consumo promedio de combustible 13 gal/h. Determine el tiempo aproximado, el rumbo de la brújula, la distancia y el combustible consumido durante el ascenso:", "o": ["14 minutos, 234°, 26 NM, 3.9 galones.", "17 minutos, 224°, 36 NM, 3.7 galones.", "17 minutos, 242°, 31 NM, 3.5 galones."], "a": 1, "e": "1. Calcule el tiempo de ascenso: Tiempo = distancia vertical ÷ velocidad vertical Donde distancia vertical = 9,500 — 1,000 = 8,500 pies Tiempo = 8,500 pies ÷ 500 FPM = 17 minutos = 0.283 horas . Calcule el combustible requerido: 13 gal/h x 0.283 hora = 3.679 galones . Calcule el ángulo de corrección del viento (WCA) y la velocidad con respecto al suelo utilizando un triángulo de viento: WCA = 8° derecha Velocidad con respecto al suelo = 128 nudos . Calcule el rumbo verdadero (TH = TC + WCA): 215 + 8° = 223° TH . Calcular el rumbo de la brújula (CH = TH + Var + Dev): 223° + 3° - 2° = 224° CH . Calcule la distancia recorrida: Distancia = 128 nudos x 0.283 horas = 36.2 NM."},
  {"id": 449, "s": 8, "q": "Una aeronave sale de un aeropuerto en las siguientes condiciones: Elevación del aeropuerto 1,500 pies. Altitud de crucero 9,500 pies. Velocidad de ascenso 500 ft/min. Velocidad promedio real 160 nudos. Curso verdadero 145°. Velocidad promedio del viento 080° a 15 nudos. Variación 5° E. Desviación -3. Consumo medio de combustible 14 gal/h. Determine el tiempo aproximado, el rumbo de la brújula, la distancia y el combustible consumido durante el ascenso:", "o": ["14 minutos, 128°, 35 NM, 3.2 galones.", "16 minutos, 132°, 41 NM, 3.7 galones.", "16 minutos, 128°, 32 NM, 3.8 galones."], "a": 1, "e": "1. Calcule el tiempo de ascenso: Tiempo = distancia vertical ÷ velocidad vertical Donde distancia vertical = 9,500 — 1,500 = 8,000 pies Tiempo = 8,000 pies ÷ 500 FPM = 16 minutos = 0.27 horas 2. Calcule el combustible requerido: 14 gal/h x 0.2666 hora = 3.73 galones 3. Calcule el ángulo de corrección del viento y la velocidad con respecto al suelo utilizando un triángulo de viento: WCA = 5° izquierda Velocidad con respecto al suelo = 153 nudos 4. Calcule el rumbo verdadero (TH = TC + WCA): 145° - 5° = 140° TH 5. Calcular el rumbo de la brújula (CH = TH + Var + Dev): 140° - 5 - 3 = 132° CH 6. Calcule la distancia recorrida: Distancia = 153 nudos x 0.27 horas = 41.31 NM."},
  {"id": 450, "s": 8, "q": "Para seguir el radial 180 en alejamiento de una estación VOR, el procedimiento recomendado es poner el OBS en:", "o": ["360° y hacer correcciones de rumbo hacia la aguja del CDI.", "180° y hacer correcciones de rumbo lejos de la aguja del CDI.", "180° y hacer correcciones de rumbo hacia la aguja del CDI."], "a": 2, "e": "El seguimiento implica la corrección de la deriva que sea necesaria para mantener un curso directo hacia o desde una estación transmisora. El curso seleccionado para el seguimiento de salida es el curso mostrado bajo el índice de curso con el indicador TO/FROM mostrando FROM. Al girar hacia la aguja, la aeronave vuelve a la línea central del rumbo y centra la aguja."},
  {"id": 451, "s": 8, "q": "Para seguir el radial 215 en acercamiento de una estación VOR, el procedimiento recomendado es ajustar el OBS en:", "o": ["215° y hacer correcciones de rumbo hacia la aguja del CDI.", "215° y hacer correcciones de rumbo lejos de la aguja del CDI.", "035° y hacer correcciones de rumbo hacia la aguja del CDI."], "a": 2, "e": "El seguimiento implica la corrección de la deriva que sea necesaria para mantener un curso directo hacia o desde una estación transmisora. El curso seleccionado para el seguimiento en alejamiento es el curso mostrado bajo el índice de curso con el indicador TO/FROM mostrando FROM. Al virar hacia la aguja, la aeronave vuelve a la línea central del rumbo y centra la aguja."},
  {"id": 452, "s": 8, "q": "Una aeronave a 60 millas de una estación VOR tiene una indicación del CDI de un quinto de desviación, esto corresponde a una desviación de la línea central del curso de aproximadamente:", "o": ["6 millas.", "2 millas.", "1 milla."], "a": 1, "e": "El desplazamiento de la aeronave del curso es de aproximadamente 200 pies, por dot, por milla náutica. La indicación de desviación del CDI es una quinta parte de desviación a 60 millas de la estación, y una quinta parte o un dot de desviación corresponde a un desplazamiento de 2 millas de lalínea central del curso."},
  {"id": 453, "s": 8, "q": "¿Cómo debe hacer el piloto la comprobación del receptor VOR, cuando la aeronave se encuentra en el punto de comprobación designado en la superficie del aeropuerto?", "o": ["Ajuste el OBS en 180° más o menos 4°; el CDI debe centrarse con una indicación FROM.", "Coloque el OBS en el radial designado. El CDI debe centrarse dentro de más o menos 4° de ese radial con una indicación FROM.", "Con la aeronave dirigida directamente hacia el VOR y el OBS ajustado a 000°, el CDI debe centrarse dentro de más o menos 4° de ese radial con una indicación de TO."], "a": 1, "e": "Los puntos de comprobación en tierra y en el aire consisten en radiales certificados que deben recibirse en puntos específicos de la superficie del aeropuerto o sobre puntos de referencia específicos mientrasse está en el aire en las inmediaciones del aeropuerto. Si se indica un error superior a +4° mediante eluso de una comprobación en tierra, o +6° utilizando la comprobación en el aire, no se deberá realizar el vuelo IFR hasta tanto no se corrija el error. Precaución: No debe aplicarse ninguna otra corrección diferente a la indicada en la tarjeta de corrección suministrada por el fabricante al realizar estas comprobaciones del receptor VOR."},
  {"id": 454, "s": 8, "q": "Cuando se utiliza el VOT para hacer una comprobación del receptor VOR, el CDI debe estar centrado y el OBS debe indicar que la aeronave está en el:", "o": ["Radial 090.", "Radial 180.", "Radial 360."], "a": 2, "e": "Para utilizar el servicio de prueba del VOR en un aeródromo (VOT), sintonice la frecuencia VOT en su receptor VOR. Con el indicador de desviación de curso (CDI) centrado, el selector de curso (OBS) debe indicar 0° con la indicación TO/FROM mostrando FROM, o el OBS debe indicar 180° con la indicación TO/FROM mostrando TO. Dado que los radiales VOR se expresan siempre desde la estación, el OBS debe indicar que la aeronave está en el radial 360°."},
  {"id": 455, "s": 8, "q": "Para las operaciones IFR fuera de las aerovías establecidas, la parte de la ruta de vuelode un plan de vuelo IFR debe enumerar las ayudas a la navegación VOR que no estén a más de:", "o": ["A 40 millas de distancia.", "A 70 millas de distancia.", "A 80 millas de distancia."], "a": 2, "e": "La operación fuera de las aerovías establecidas por debajo de los 18,000 pies MSL utiliza radioayudas que no estén a más de 80 NM. Estas ayudas están indicadas en las cartas de ruta de baja altitud."},
  {"id": 456, "s": 8, "q": "A medida que la temperatura del aire aumenta, la altitud por densidad:", "o": ["Disminuye.", "Incrementa.", "Permanece igual"], "a": 1, "e": "La altitud por densidad es la altitud en condiciones de aire estándar, donde la densidad es la misma que la existente. Dicha densidad depende de la presión, temperatura y humedad del aire. Tanto una disminución de la presión como un aumento de la temperatura disminuyen la densidad del aire y aumentan la altitud por densidad."},
  {"id": 457, "s": 8, "q": "¿Qué procedimiento podría utilizar un piloto para navegar bajo VFR de un punto a otro cuando las referencias terrestres no son visibles?", "o": ["Navegación a estima.", "Navegación aérea observada.", "La VFR no está permitida en estas circunstancias."], "a": 0, "e": "La navegación aérea bajo VFR es la navegación por referencia a puntos de referencia en tierra o puntos de control. La navegación a estima es la que se realiza únicamente promedio de cálculos basados en el tiempo, velocidad, distancia y rumbo."},
];
